const ARC_V55 = {
 "魔法师":{cn:"真理之焰",theme:"知识是否该有禁忌",doctrine:"求知者不问值不值",keyNpc:"洛·晨雾",
  s1:{title:"幕一·真理的学徒",entry:"图书馆的旧书架深处，一本无人借阅的册子，封皮上有你的姓氏。",firstNode:"arc_mage1"},
  s2:{title:"幕二·元素的低语",entry:"元素学院的大师让你去地下一层取一份卷宗——那间库房，十年没开过门。",firstNode:"arc_mage4"},
  s3:{title:"幕三·禁咒的回响",entry:"有人在你窗下留下一行烧焦的字：'别念那页。'",firstNode:"arc_mage7"},
  s4:{title:"幕四·失衡的季风",entry:"大陆西岸的风，一年没吹对方向了——长老们说，这是某本书的代价。",firstNode:"arc_mage10"},
  s5:{title:"幕五·大裂解之前",entry:"洛·晨雾约你在星落塔顶见面——他要谈的，不是塔的事。",firstNode:"arc_mage13"}},
 "灵魂法师":{cn:"魂灯不灭",theme:"灵魂是否该被度量",doctrine:"亡者的账，生者来记",keyNpc:"澜·梦墟",
  s1:{title:"幕一·无影的学徒",entry:"晨曦圣殿的灯架上，多了一盏没人点过的灯——灯座刻着你的名字。",firstNode:"arc_soul1"},
  s2:{title:"幕二·镜中的访客",entry:"守镜人澜·梦墟传话：'镜子里有位客人，说是来找你的。'",firstNode:"arc_soul4"},
  s3:{title:"幕三·魂秤之约",entry:"有人送来半截旧秤杆——灵魂法师之间，这等于一封战书。",firstNode:"arc_soul7"},
  s4:{title:"幕四·魂灯忽明",entry:"圣殿的魂灯连灭七盏，每盏下面都压着一张写着你名字的纸。",firstNode:"arc_soul10"},
  s5:{title:"幕五·灯前之问",entry:"奥雷利安·晨曦的残影，在灯影里等你——他要问最后一个问题。",firstNode:"arc_soul13"}},
 "术士":{cn:"熔炉之心",theme:"造物主的责任",doctrine:"造出来，就得负责",keyNpc:"格朗·符文",
  s1:{title:"幕一·学徒的锤",entry:"锻造公会分给你一柄旧锤——锤柄上有三道裂痕，像三句没说完的话。",firstNode:"arc_smith1"},
  s2:{title:"幕二·炉底的动静",entry:"公会的初火熔炉，夜里总传出不属于火焰的声响。",firstNode:"arc_smith4"},
  s3:{title:"幕三·造物的代价",entry:"一件你亲手造的东西，开始在你睡着后自己移动。",firstNode:"arc_smith7"},
  s4:{title:"幕四·炉火之灾",entry:"王座下的初火异动，格朗·符文让你带上那柄旧锤，下到炉底。",firstNode:"arc_smith10"},
  s5:{title:"幕五·封炉之前",entry:"格朗·符文说：'火还烧着，但烧的是谁的日子，该由你决定了。'",firstNode:"arc_smith13"}},
 "战士":{cn:"战旗不倒",theme:"力量为何而战",doctrine:"握刀的手，先要知道为谁而握",keyNpc:"秦·长风",
  s1:{title:"幕一·新兵的战旗",entry:"战神团的演武场边，插着一面褪色的旧旗——老兵说，它等一个新主人。",firstNode:"arc_war1"},
  s2:{title:"幕二·北境的信",entry:"一封没有署名的信从北境寄来，信纸上只有一枚血指印。",firstNode:"arc_war4"},
  s3:{title:"幕三·荣耀的价",entry:"有人出钱买你的一场败——输得漂亮，给得也漂亮。",firstNode:"arc_war7"},
  s4:{title:"幕四·旗在人在",entry:"铁门关的战报传到学院：秦·长风单人立于关前——而那面旗，缺了一角。",firstNode:"arc_war10"},
  s5:{title:"幕五·旗之问",entry:"秦·长风在关前等你——'你这一刀，为谁而握？'",firstNode:"arc_war13"}},
 "骑士":{cn:"誓约之重",theme:"誓约是否该被打破",doctrine:"一诺既出，万山无阻",keyNpc:"伊莎·圣辉",
  s1:{title:"幕一·白袍的誓",entry:"誓约骑士团的礼堂里，你跪下的那一刻，地板上的纹路亮了一瞬。",firstNode:"arc_knight1"},
  s2:{title:"幕二·誓约之裂",entry:"团里有一位骑士，在执行任务时违背了誓约——没人敢提他的名字。",firstNode:"arc_knight4"},
  s3:{title:"幕三·两难之誓",entry:"两条誓约同时压在你头上：救一个人，就要背弃另一个人。",firstNode:"arc_knight7"},
  s4:{title:"幕四·圣辉之暗",entry:"伊莎·圣辉的旧伤复发——有人说是诅咒，有人说是誓约的反噬。",firstNode:"arc_knight10"},
  s5:{title:"幕五·剑与誓",entry:"伊莎·圣辉把她的剑放在你面前：'守它，或者打破它——你选。'",firstNode:"arc_knight13"}},
 "游侠":{cn:"荒野之声",theme:"守护什么",doctrine:"森林先于王座存在",keyNpc:"贺·断弓",
  s1:{title:"幕一·断弓之约",entry:"巡守的营地里，挂着半张旧弓——贺·断弓年轻时留下的。",firstNode:"arc_ranger1"},
  s2:{title:"幕二·林中的火",entry:"森林边缘起了一场不该起的火——风向，是逆着林子的。",firstNode:"arc_ranger4"},
  s3:{title:"幕三·文明之问",entry:"修路的人求你让路，守林的人求你拦路——两边的理由都对。",firstNode:"arc_ranger7"},
  s4:{title:"幕四·荒原的呼号",entry:"银叶城闭门后，东境的野兽开始反常——贺·断弓的箭袋空了一半。",firstNode:"arc_ranger10"},
  s5:{title:"幕五·森林之声",entry:"贺·断弓在山口等你：'这片林子守的是谁，你知道吗？'",firstNode:"arc_ranger13"}},
 "盗贼":{cn:"暗影法则",theme:"偷窃与正义",doctrine:"影子不抢，只拿",keyNpc:"杜·夜枭",
  s1:{title:"幕一·夜枭的记号",entry:"暗影阁的入门考验，是在城门上画一个记号——那晚，你画了两次。",firstNode:"arc_thief1"},
  s2:{title:"幕二·无声厅来信",entry:"一封没有署名的信从无声厅寄来：'三年前的旧账，该清了。'",firstNode:"arc_thief4"},
  s3:{title:"幕三·偷与不偷",entry:"一件该偷的东西放在你面前——偷了，有人活；不偷，也有人活。",firstNode:"arc_thief7"},
  s4:{title:"幕四·影中裂痕",entry:"暗影阁内部出了叛徒，杜·夜枭的名单上，多了一个你想不到的名字。",firstNode:"arc_thief10"},
  s5:{title:"幕五·影之审判",entry:"杜·夜枭把一枚旧徽章推到你面前：'暗影的规矩，你来说。'",firstNode:"arc_thief13"}},
 "牧师":{cn:"圣光之问",theme:"神是否存在",doctrine:"信，是先于看见的",keyNpc:"克莱门·圣言",
  s1:{title:"幕一·静默的见习",entry:"圣辉教会的见习室里，有一本空白的圣典——每一任见习牧师都写过，又都撕掉了。",firstNode:"arc_priest1"},
  s2:{title:"幕二·使徒宫的钟",entry:"教皇沉眠后，使徒宫的钟不再报时——只有重大事件，钟才会响。",firstNode:"arc_priest4"},
  s3:{title:"幕三·圣光之暗",entry:"一次净化行动中，你看见圣光落错了地方——它没有问该不该。",firstNode:"arc_priest7"},
  s4:{title:"幕四·静默殿门",entry:"克莱门·圣言开了静默殿的门——他站在门后，等你问他一个问题。",firstNode:"arc_priest10"},
  s5:{title:"幕五·钟声之前",entry:"使徒宫的钟，在夜里响了一声——只有你知道它为什么响。",firstNode:"arc_priest13"}},
 "商人":{cn:"天平两端",theme:"一切是否可交易",doctrine:"万物有价，唯情难称",keyNpc:"文森·金秤",
  s1:{title:"幕一·学徒的秤",entry:"金衡商会分给你一杆旧秤——秤杆上刻着前任主人的名字，已经磨得看不清了。",firstNode:"arc_trade1"},
  s2:{title:"幕二·总账房的灯",entry:"总账房深夜亮灯，账本上有一页，被撕掉了——文森·金秤的手边。",firstNode:"arc_trade4"},
  s3:{title:"幕三·价与无价",entry:"有人要买一件不卖的东西——而你，手里恰好有价。",firstNode:"arc_trade7"},
  s4:{title:"幕四·金秤之危",entry:"银穗商路断了，金衡商会一夜之间成了众矢之的——账房先生们开始连夜对账。",firstNode:"arc_trade10"},
  s5:{title:"幕五·称心",entry:"文森·金秤把秤交到你手里：'这杆秤称过万物，唯独没称过人心——你来。'",firstNode:"arc_trade13"}}
};
window.v55_ensureDefaults = function(){
  try{
    if(typeof S==='undefined'||!S) return;
    if(window.v54_ensureDefaults) v54_ensureDefaults();
    if(!S.skills) S.skills={};
    if(!S.arcV55) S.arcV55={};
    if(!S.skillLog) S.skillLog=[];
    var j = S.job||"";
    if(j && !S.arcV55[j]) S.arcV55[j]={stage:0,flags:{}};
    if(j && !S.skills[j]) S.skills[j]=[];
  }catch(e){}
};
window.v55_jobCn = function(){ try{ return (typeof S!=='undefined'&&S&&S.job)?S.job:""; }catch(e){ return ""; } };
window.v55_getSkill = function(id){
  try{
    var j=v55_jobCn(); var pool=SKILLS_V55[j]; if(!pool) return null;
    var all=[].concat(pool.t1||[],pool.t2||[],pool.t3||[],pool.t3b||[],pool.t4||[]);
    for(var i=0;i<all.length;i++){ if(all[i].id===id) return all[i]; }
    return null;
  }catch(e){ return null; }
};
window.v55_learned = function(id){
  try{ v55_ensureDefaults(); var j=v55_jobCn(); if(!j) return false; var arr=S.skills[j]||[]; for(var i=0;i<arr.length;i++){ if(arr[i]===id) return true; } return false; }catch(e){ return false; }
};
window.v55_learnAll = function(){
  try{
    v55_ensureDefaults(); var j=v55_jobCn(); if(!j) return;
    var pool=SKILLS_V55[j]; if(!pool) return;
    var rl=(S.realm||0); var added=0; var lockedNames=[];
    var all=[].concat(pool.t1||[],pool.t2||[],pool.t3||[],pool.t3b||[],pool.t4||[]);
    for(var i=0;i<all.length;i++){
      var s=all[i];
      if(rl>=s.realm && !v55_learned(s.id)){
        var locked=false;
        if(s.tier===4){ var rk=(window.v52_orgRank?v52_orgRank():0); var art=(S.artifact===j); if(!(rk>=2||art)) locked=true; }
        if(locked){ lockedNames.push(s.cn); continue; }
        S.skills[j].push(s.id);
        S.skillLog.push({id:s.id,at:rl,day:(S.day||0)});
        added++;
      }
    }
    if(added>0){ if(window.flashMsg) flashMsg('你悟出了新技法（'+added+' 门）'); if(window.v44_toast) try{v44_toast('新技法','你悟出了：'+added+' 门职业技法','success','⚔');}catch(e){} }
    if(lockedNames.length){ if(window.flashMsg) flashMsg('「'+lockedNames.join('」「')+'」尚蒙尘——你隐约觉得，这门技法还缺一把钥匙'); }
  }catch(e){}
};
window.v55_applyOne = function(s,out){
  try{
    var e=s.eff||{};
    if(e.type==="bonus"){ out.t+=e.value; out.labels.push("【技能】"+s.cn+(e.value>0?" +":" ")+e.value+(e.note?("·"+e.note):"")); }
    else if(e.type==="floor"){ if(out.t<e.value){ out.t=e.value; out.labels.push("【技能】"+s.cn+" · 保底"+(e.note?("·"+e.note):"")); } }
    else if(e.type==="pct"){ out.t=Math.round(out.t*(1+e.value)); out.labels.push("【技能】"+s.cn+" +"+Math.round(e.value*100)+"%"); }
    else if(e.type==="reroll"){ out.reroll=true; out.labels.push("【技能】"+s.cn+" · 可重掷"); }
    else if(e.type==="heal"){ out.labels.push("【技能】"+s.cn+" · 预备"); }
  }catch(e){}
  return out;
};
window.v55_skillApply = function(opt, t){
  var out={t:t,labels:[],reroll:false};
  try{
    if(typeof S==='undefined'||!S||!opt||!opt.check) return out;
    var sk=opt.check.sk||"", a=opt.check.a||"";
    var scene=(window.v52_sceneOf)?v52_sceneOf(sk,a):null;
    if(!scene) return out;
    v55_ensureDefaults(); var j=v55_jobCn(); if(!j) return out;
    var pool=SKILLS_V55[j]; if(!pool) return out;
    var all=[].concat(pool.t1||[],pool.t2||[],pool.t3||[],pool.t3b||[],pool.t4||[]);
    for(var i=0;i<all.length;i++){
      var s=all[i];
      if(!v55_learned(s.id)) continue;
      if(s.scene!==scene) continue;
      if(s.type==="被动"){ out=v55_applyOne(s,out); }
      else if(s.type==="主动"){
        if(S.skillPrep===s.id){ out=v55_applyOne(s,out); S.skillPrep=null; if(window.v55_castFX) try{v55_castFX(s);}catch(e){} }
      }
    }
    out.t=Math.max(5,Math.min(98,out.t));
    return out;
  }catch(e){ return {t:t,labels:[],reroll:false}; }
};
window.v55_castFX = function(s){
  try{
    if(window.v44_floatText) try{v44_floatText(document.getElementById('story'), s.cn, 'purple');}catch(e){}
    if(window.v34_playSfx) try{v34_playSfx('quest');}catch(e){}
  }catch(e){}
};
window.v55_prepSkill = function(id){
  try{
    if(typeof S==='undefined'||!S){ return; }
    v55_ensureDefaults(); var j=v55_jobCn();
    var s=v55_getSkill(id); if(!s){ if(window.flashMsg) flashMsg('未找到这门技法。'); return; }
    if(s.type!=="主动"){ if(window.flashMsg) flashMsg('「'+s.cn+'」无需运起。'); return; }
    if(!v55_learned(id)){ if(window.flashMsg) flashMsg('你尚未习得「'+s.cn+'」。'); return; }
    if(s.tier===4){ var rk=(window.v52_orgRank?v52_orgRank():0); var art=(S.artifact===j); if(!(rk>=2||art)){ if(window.flashMsg) flashMsg('你隐约觉得，这门技法还缺一把钥匙。'); return; } }
    var res=(s.cost&&s.cost.res)?s.cost.res:"mp"; var need=(s.cost&&s.cost.n)?s.cost.n:0;
    if(res==="mp"){ if((S.mp||0)<need){ if(window.flashMsg) flashMsg('气力不济——法力不足。'); return; } S.mp=(S.mp||0)-need; }
    else if(res==="gold"){ if((S.gold||0)<need){ if(window.flashMsg) flashMsg('囊中羞涩——金币不足。'); return; } S.gold=(S.gold||0)-need; }
    S.skillPrep=id;
    if(window.flashMsg) flashMsg('你已运起「'+s.cn+'」，等待出手时机');
    if(window.v34_playSfx) try{v34_playSfx('page');}catch(e){}
  }catch(e){}
};
window.v55_useRestore = function(id){
  try{
    if(typeof S==='undefined'||!S) return;
    v55_ensureDefaults(); var j=v55_jobCn();
    var s=v55_getSkill(id); if(!s) return;
    if(!v55_learned(id)){ if(window.flashMsg) flashMsg('尚未习得「'+s.cn+'」。'); return; }
    var e=s.eff||{};
    if(e.type==="heal"){ if((S.hp||0)>=S.maxHp){ if(window.flashMsg) flashMsg('你此刻气血充盈，无需「'+s.cn+'」。'); return; } S.hp=Math.min(S.maxHp,(S.hp||0)+e.value); if(window.flashMsg) flashMsg('「'+s.cn+'」— 恢复 '+e.value+' HP'); if(window.v34_playSfx) try{v34_playSfx('heal');}catch(e){} }
    else if(e.type==="revive"){ if((S.hp||0)>0){ if(window.flashMsg) flashMsg('你尚有余力，此术留待危时。'); return; } S.hp=Math.max(1,Math.floor((S.maxHp||100)*0.5)); if(window.flashMsg) flashMsg('「'+s.cn+'」— 一线生机，把你从死亡边缘拉了回来'); if(window.v34_playSfx) try{v34_playSfx('heal');}catch(e){} }
    else if(e.type==="gold"){ var cool=e.note?7:3; if(e.value>50) cool=7; var cd=(S.skillCd&&S.skillCd[id])||-999; var d=(S.day||0); if(d-cd<cool){ if(window.flashMsg) flashMsg('这门生意还差 '+((cool-(d-cd)))+' 天回本。'); return; } var cost=(s.cost&&s.cost.n)?s.cost.n:0; if((S.gold||0)<cost){ if(window.flashMsg) flashMsg('本金不够。'); return; } S.gold=(S.gold||0)-cost; S.gold=(S.gold||0)+e.value; if(!S.skillCd) S.skillCd={}; S.skillCd[id]=d; var gain=e.value-cost; if(window.flashMsg) flashMsg('「'+s.cn+'」— 进账 '+e.value+' 金（净 '+gain+'）'); if(window.v34_playSfx) try{v34_playSfx('coin');}catch(e){} }
  }catch(e){}
};
window.v55_skillBar = function(){
  try{
    var op=document.getElementById('options'); if(!op) return;
    if(typeof S==='undefined'||!S) return;
    v55_ensureDefaults(); var j=v55_jobCn(); if(!j) return;
    var pool=SKILLS_V55[j]; if(!pool) return;
    var scene=null;
    var nn=(typeof N!=="undefined"&&window.curNode&&N[curNode])?N[curNode]:null;
    if(nn&&nn.options){
      var os=typeof nn.options==="function"?nn.options():nn.options;
      for(var i=0;i<os.length;i++){ if(os[i]&&os[i].check){ var sc=(window.v52_sceneOf)?v52_sceneOf(os[i].check.sk,os[i].check.a):null; if(sc){ scene=sc; break; } } }
    }
    if(!scene) return;
    var all=[].concat(pool.t1||[],pool.t2||[],pool.t3||[],pool.t3b||[],pool.t4||[]);
    var usable=[];
    for(var k=0;k<all.length;k++){ var s=all[k]; if(s.type==="主动"&&v55_learned(s.id)&&s.scene===scene){ usable.push(s); } }
    if(!usable.length) return;
    var h='<div style="margin:10px 0 4px;padding:8px 10px;background:var(--bg-panel2);border:1px dashed var(--border);border-radius:8px;">';
    h+='<div style="font-size:12px;color:var(--text-muted);margin-bottom:6px;">✦ 技法可用（'+scene+'）：先运起一门，再出手</div>';
    for(var m=0;m<usable.length;m++){
      var sk=usable[m]; var prep=(S.skillPrep===sk.id);
      h+='<button class="btn btn-sm" style="margin:2px 6px 2px 0;'+(prep?'border-color:var(--text-gold);color:var(--text-gold);':'')+'" onclick="v55_prepSkill(\''+sk.id+'\')">'+(prep?'已运起·':'')+sk.cn+'<span style="font-size:11px;opacity:.75;margin-left:4px;">'+(sk.cost&&sk.cost.res==="gold"?'金':('MP'+((sk.cost&&sk.cost.n)?sk.cost.n:0)))+'</span></button>';
    }
    h+='</div>';
    var div=document.createElement('div'); div.innerHTML=h;
    op.appendChild(div.firstChild);
  }catch(e){}
};
window.v55_skillPanel = function(){
  try{
    v55_ensureDefaults();
    var st=document.getElementById('story'); var op=document.getElementById('options');
    if(!st||!op) return;
    if(window.clearOptions){ try{ clearOptions(); }catch(e){} }
    var j=v55_jobCn(); var pool=SKILLS_V55[j];
    var h='<div class="panel-header"><span class="panel-title">修行 · 职业技能</span><button class="panel-close" onclick="closePanel()">✕</button></div>';
    h+='<div style="margin:4px 0 8px;font-size:13px;color:var(--text-muted);">职业：'+j+'　境界：'+(S.realm||0)+'　已学：'+(S.skills[j]?S.skills[j].length:0)+' 门</div>';
    if(!pool){
      h+='<div style="margin:12px 0;padding:12px;background:var(--bg-panel2);border:1px dashed var(--border);border-radius:8px;color:var(--text-muted);font-size:13px;">该职业暂无技能数据。</div>';
      st.innerHTML=h; return;
    }
    var all=[].concat(pool.t1||[],pool.t2||[],pool.t3||[],pool.t3b||[],pool.t4||[]);
    var tiers=['t1','t2','t3','t3b','t4'];
    var tierCn={t1:'初阶 · 启灵',t2:'中阶 · 凝元',t3:'高阶 · 化意',t3b:'高阶 · 化意',t4:'本源 · 宗师'};
    for(var ti=0;ti<tiers.length;ti++){
      var grp=pool[tiers[ti]]||[];
      if(!grp.length) continue;
      h+='<div style="margin:10px 0 4px;font-size:14px;color:var(--text-secondary);">—— '+tierCn[tiers[ti]]+' ——</div>';
      for(var i=0;i<grp.length;i++){
        var s=grp[i];
        var learned=v55_learned(s.id);
        var locked=false;
        if(s.tier===4&&!learned){ var rk=(window.v52_orgRank?v52_orgRank():0); var art=(S.artifact===j); if(!(rk>=2||art)) locked=true; }
        var lockedNote=(s.tier===4&&!learned)?'<div style="font-size:11px;color:var(--text-muted);">尘封 · 组织 rank≥2 或 神器在手 可解</div>':'';
        var btns='';
        if(learned){
          if(s.type==="主动"){ btns='<button class="btn btn-sm" style="margin-top:6px;" onclick="v55_prepSkill(\''+s.id+'\')">'+(S.skillPrep===s.id?'已运起':'运起')+'</button>'; }
          else if(s.type==="恢复"||s.type==="经济"){ btns='<button class="btn btn-sm" style="margin-top:6px;" onclick="v55_useRestore(\''+s.id+'\')">使用</button>'; }
        }
        h+='<div style="margin:6px 0;padding:10px;background:var(--bg-panel2);border:1px solid var(--border);border-radius:8px;'+(learned?'':'opacity:.55;')+'">';
        h+='<div style="font-weight:bold;color:'+(learned?'var(--text-primary)':'var(--text-muted)')+';">'+s.cn+' <span style="font-size:11px;color:var(--text-muted);font-weight:normal;">('+s.type+(s.cost?(' · '+(s.cost.res==="gold"?'金'+s.cost.n:'MP'+s.cost.n)):' · 被动')+')</span></div>';
        h+='<div style="font-size:12px;color:var(--text-secondary);margin:4px 0;">'+s.desc+'</div>';
        h+='<div style="font-size:11px;color:var(--text-gold);">效果：'+(s.eff&&s.eff.type==="bonus"?'+'+s.eff.value+' 判定':(s.eff&&s.eff.type==="floor"?'保底 '+s.eff.value:(s.eff&&s.eff.type==="pct"?'+'+Math.round((s.eff.value||0)*100)+'%':(s.eff&&s.eff.type==="reroll"?'可重掷取高':(s.eff&&s.eff.type==="heal"?'恢复 '+s.eff.value+' HP':(s.eff&&s.eff.type==="revive"?'濒死救回':(s.eff&&s.eff.type==="gold"?'经济收益':'——')))))))+(s.eff&&s.eff.note?('·'+s.eff.note):'')+'</div>';
        h+=lockedNote+btns;
        h+='</div>';
      }
    }
    h+='<div style="margin-top:12px;"><button class="btn" onclick="v51_featPanel()">← 返回修行总览</button></div>';
    st.innerHTML=h;
    try{ if(window.v44_toast){} }catch(e){}
  }catch(e){}
};
window.v55_arcEntry = function(){
  try{
    var op=document.getElementById('options'); if(!op) return;
    if(typeof S==='undefined'||!S) return;
    v55_ensureDefaults(); var j=v55_jobCn(); if(!j) return;
    var arc=ARC_V55[j]; if(!arc) return;
    if(!S.arcV55[j]) S.arcV55[j]={stage:0,flags:{}};
    var st=S.arcV55[j].stage||0;
    if(st>=5) return;
    var enter=null;
    if(st===0){ if((S.academyYear||0)>=1) enter=arc.s1; }
    else if(st===1){ if(((window.v52_orgRank?v52_orgRank():0))>=1&&(S.academyYear||0)>=2) enter=arc.s2; }
    else if(st===2){ if((S.realm||0)>=3) enter=arc.s3; }
    else if(st===3){ if((S.realm||0)>=4) enter=arc.s4; }
    else if(st===4){ if((S.realm||0)>=5) enter=arc.s5; }
    if(!enter||!enter.firstNode) return;
    if(S.arcV55[j].flags['in_'+st]) return;
    var b=document.createElement('button'); b.className='opt opt-gold';
    b.innerHTML='<span class="od">◆</span> <span style="font-size:13px;">命运的【'+arc.cn+' · '+enter.title+'】</span><div style="font-size:12px;color:var(--text-muted);margin-top:2px;">'+enter.entry+'</div>';
    b.onclick=function(){ try{ S.arcV55[j].stage=st+1; S.arcV55[j].flags['in_'+st]=true; }catch(e){} go(enter.firstNode); };
    op.appendChild(b);
  }catch(e){}
};
/* ===== /v55inj:skills ===== */
/* ===== v55inj:arcA 职业命运弧 A（魔法师/战士/牧师） ===== */
N["arc_mage1"]=function(){return{
 sceneTitle:"真理之焰 · 幕一 · 真理的学徒",
 text:[
  "图书馆闭馆前半个时辰，你照例去还书。拐过第三排书架时，你的手背擦过一本斜插的册子——册子掉下来，摊开在地上。",
  "那页纸上只有一行字：「元素不喜欢被命令。」墨迹很旧，却还带着一点热度。你低头看了一眼封面：封皮上，写着一个姓氏——和你的姓氏一模一样。",
  "你四下看了看。没有人。灯光在书页上晃了一下，像是有什么东西，隔着很远的路，也隔着很长的年月，朝你笑了一下。",
  "你蹲下去，把那本册子捡了起来。指尖碰到纸面的一瞬，图书馆角落的烛火，齐刷刷地矮了一寸。",
  "你没有告诉任何人。那天晚上，你把它压在枕头底下，一夜没睡踏实。"
 ],
 options:[
  {t:"翻开那本册子",go:"arc_mage2"}
 ]
};};
N["arc_mage2"]=function(){return{
 sceneTitle:"真理之焰 · 幕一 · 第一页",
 text:[
  "册子很薄，一共十二页。前十一页讲的全是火——怎么聚火，怎么让火听话，怎么在火反噬之前把它按回丹田。批注的字迹很小，有些地方写了两遍，像是在和谁争论。",
  "你照着第一页的法子试了一次。没有念咒，只是把手摊开。指尖先是发凉，然后发烫——一朵豆大的火苗，在你掌心跳了起来。",
  "它跳得很轻，像一只活物，仰头看着你。你听见书页里有人在说话，声音很轻：「看，它认得你。」",
  "你猛地合上册子。火苗灭了。图书馆的灯，又亮回原来的样子。你坐在原地，手心发烫，心里却冷——你忽然明白，那不是书在教你，是书在认你。",
  "而火苗跳起来的那一刻，你好像听见了某个更远的回音：像是一扇门，在很深的地方，被人推了一下。"
 ],
 options:[
  {t:"把册子藏进怀里",go:"arc_mage3"}
 ]
};};
N["arc_mage3"]=function(){return{
 sceneTitle:"真理之焰 · 幕一 · 告诫",
 text:[
  "第二天，元素学院的老讲师把你叫到讲台边。他看了你很久，然后说：「你昨晚，碰了不该碰的东西。」",
  "你装作听不懂。老讲师没追问，只是把一枚铜戒放在你桌上：「火认主，是好事。但你要记住——元素有耳朵。有些话，说一次就够了。」",
  "他把那枚铜戒推到你面前：「戴上它。它会在你念错东西的时候，先替你疼一下。」",
  "你问为什么。老讲师顿了顿，说：「因为我也念错过。」他走出教室时，袖口露出手腕上一道很旧的疤——不是刀伤，是烧痕，一圈一圈，像是某种纹路从皮肤底下透出来，又被压了回去。",
  "你把铜戒戴上。戒圈略大，转了一圈，卡在指根。当天夜里，你第三次梦见那本册子——册子已经翻到了最后一页，最后一页上，写着你的名字。"
 ],
 options:[
  {t:"（命运的回响在等待你）去地下一层取卷宗",go:"arc_mage4"}
 ]
};};
N["arc_mage4"]=function(){return{
 sceneTitle:"真理之焰 · 幕二 · 元素的低语",
 text:[
  "元素学院的地下一层，楼梯尽头是一扇铁门。门锁上挂着一串铜铃——不响，只是挂着，像一个提醒。",
  "大师给你的字条上写着：「第三排左起第七格，取卷宗号 113。取完就走，不要看其他。」",
  "你推开门。门后很暗，空气里是灰尘和旧纸的味道，还有一丝很淡的硫磺味。第三排书架比前两排矮，像是被什么压弯过。你数到第七格，手伸进去，摸到一卷很重的羊皮纸。",
  "你把卷宗抽出来时，指尖碰到了旁边一个东西——一截烧焦的木头，嵌在书架缝隙里，焦黑得像一根手指。它上面刻着一个符号：和你那本册子封面上的，一模一样。",
  "你没看其他。但你关门的瞬间，听见书架深处，有什么东西翻了个身。"
 ],
 options:[
  {t:"带着卷宗回到地面",go:"arc_mage5"}
 ]
};};
N["arc_mage5"]=function(){return{
 sceneTitle:"真理之焰 · 幕二 · 卷宗 113",
 text:[
  "卷宗 113 是一份旧记录，记录着两百年前的一场「元素失衡」：那一年，大陆西岸的季风停了四个月，河面结冰，火焰在七月里自己熄灭。",
  "记录的最后，是一位老法师的批注：「非天灾。是有人把一门大咒念到了第七遍，念破了一层『现实』。元素漏了气，于是风没了方向。」",
  "批注末尾，还有一行更小的字，被人用墨涂掉了大半，只留下几个字：「……若再有人翻开此卷，勿念第七页。」",
  "你翻到第七页。那页纸是空白的，只在纸中央有一个淡淡的烧焦圆点——像是有什么东西，隔着两百年，隔着这卷羊皮纸，盯着你。",
  "你合上卷宗。指尖的铜戒，莫名其妙地发烫了一瞬。"
 ],
 options:[
  {t:"把第七页的事记在心里",go:"arc_mage6"}
 ]
};};
N["arc_mage6"]=function(){return{
 sceneTitle:"真理之焰 · 幕二 · 第一征兆",
 text:[
  "三日后，学院的火炉出了事。食堂的灶火无缘无故地忽明忽暗，厨娘们说是风，但你是法师，你看得出——火在怕什么。",
  "你走到灶边，把手按在灶台上。火苗缩了一下，然后又胆怯地靠过来，像一只认出主人的狗。",
  "你忽然明白了。不是火在怕什么——是火在听你的话。你只是站在这里，什么都没做，火就在试探你的意思。",
  "你收回手。火苗重新亮起来，正常得像什么都没发生过。但你知道：元素已经开始注意你了。而注意，从来都不是免费的。",
  "当晚，你的梦里第三次出现那本册子的最后一页。这一次，页面上除了你的名字，还多了一行字：「第七页，等你。」"
 ],
 options:[
  {t:"（你已站在门边）有人在你窗下留了字",go:"arc_mage7"}
 ]
};};
N["arc_mage7"]=function(){return{
 sceneTitle:"真理之焰 · 幕三 · 禁咒的回响",
 text:[
  "清晨，你在窗台上发现一行烧焦的字，字迹歪斜，像是写得很急：「别念那页。」",
  "没有落款。烧焦的边缘还带着温度——写下这行字的人，刚离开不久。你探头往下看，街道上空空的，只有一只灰鸽站在对面的屋顶上，歪着头看你。",
  "你蹲在窗台边，盯着那四个字。字迹的笔锋，和卷宗 113 里被涂掉的那行小字，是同一个人的手笔。",
  "这个人知道你看过卷宗。他知道你知道第七页。而他提醒你的方式，是烧了一行字——一个法师，用自己的火，给另一个法师留口信。",
  "你伸手碰了碰那行字。指腹一烫，焦痕碎成灰，飘了下去。灰落在你手上，凉了。",
  "「别念那页。」——可你忽然很想念。"
 ],
 options:[
  {t:"压下冲动，把册子锁进箱底（克制）",go:"arc_mage8"},
  {t:"深夜独自翻开册子，默念第七页（放任）",go:"arc_mage8",req:function(){return (typeof S!=='undefined'&&S&&(S.corruption||0)>=40);}}
 ]
};};
N["arc_mage8"]=function(){return{
 sceneTitle:"真理之焰 · 幕三 · 一念之间",
 text:[
  "那一夜，你把册子放在桌上，铜戒搁在书页上，像一座小小的封印。你坐了很久，窗外的风一直在吹，吹得灯影摇摇晃晃。",
  "你知道第七页上是什么——元素漏了气，现实被念破一层，风失去方向。而你只要念一遍，就能知道「念破现实」是什么样的感觉。",
  "求知欲像一根刺，扎在喉咙里。老讲师的铜戒，在你指根上轻轻转了一圈，像是在提醒你：有些门，进去就出不来。",
  "你最终合上了册子。那一刻，你听见一声极轻的叹息——不是你的，是从窗台下传来的。像是有个人，在黑暗里等了很久，等到你做了决定，才放心地转身离开。",
  "你抬头看向窗外。对面屋顶上，那只灰鸽还在。它歪着头看你，然后张开翅膀，飞向了月亮的方向。"
 ],
 options:[
  {t:"守住这一夜（你守住了）",go:"arc_mage9"}
 ]
};};
N["arc_mage9"]=function(){return{
 sceneTitle:"真理之焰 · 幕三 · 回响的代价",
 text:[
  "第二天，老讲师找到你，递给你一杯热茶。他没问昨晚发生了什么，只说：「戒圈松了吗？」",
  "你低头看。铜戒还是那么紧，但戒圈内侧，多了一道极细的裂痕——像是替你挡了一下什么。",
  "老讲师看着那道裂痕，沉默了很久：「两百年前，写下卷宗 113 的那位法师，也有一枚这样的戒指。他没管住自己，念了第七页。」",
  "「后来呢？」你问。",
  "「后来，」老讲师把茶喝完，「元素记住了他的名字。他死的那天，全城的火，都自己熄了。」他站起来，拍拍你的肩：「你昨晚没念。火会记得你这份克制。」",
  "你攥紧那枚铜戒。戒圈内侧的裂痕，像一条细细的河——而你知道，这条河，是你自己渡过去的。"
 ],
 options:[
  {t:"（命运的弦已绷紧）长老召见，关于季风",go:"arc_mage10"}
 ]
};};
N["arc_mage10"]=function(){return{
 sceneTitle:"真理之焰 · 幕四 · 失衡的季风",
 text:[
  "大陆西岸的消息传到学院那天，全城的火都暗了一瞬。季风已经停了两周，港口的风帆垂着，河面上漂着死鱼。",
  "长老们在议事厅召见你。你进去时，十二位长老的目光一齐落过来——不是看你，是看你手上的铜戒。",
  "「卷宗 113，你读过。」首席长老说，语气平淡，「两百年前的事，重演了。西岸有人把一门大咒念到了第七遍。」",
  "你沉默。首席长老又说：「这一次，我们不想再等元素自己记住他的名字。我们需要一个读过第七页、却忍住没念的人——去西岸，看看是哪扇门被推开了。」",
  "「为什么是我？」你问。",
  "首席长老看着你：「因为你的名字，两百年前，就已经写在那本册子的最后一页上了。」"
 ],
 options:[
  {t:"接下长老的委托",go:"arc_mage11"}
 ]
};};
N["arc_mage11"]=function(){return{
 sceneTitle:"真理之焰 · 幕四 · 洛·晨雾",
 text:[
  "出发前夜，传奇法师洛·晨雾在你宿舍门口等你。他倚着门框，手里捏着半块干面包，咬一口，说一句：「西岸那地方，风大，别穿太少。」",
  "「长老说我的名字写在册子上。」你说，「你信吗？」",
  "洛·晨雾把面包咽下去，认真想了想：「那本册子，我也读过。最后一页上，写的是我的名字。」",
  "你愣住了。他笑了一下，皱纹在灯下很深：「后来我把它划掉了——划掉那天，我把它埋进了图书馆最深处。谁能想到，它又长出来了，还长出了你的名字。」",
  "「所以你……」",
  "「所以我是来告诉你：」洛·晨雾正色，「册子选人，不是因为那个人注定念咒。是因为那个人，有本事不念。」他顿了顿，「你是那本册子等的第二个能忍住的人。第一个是我。」",
  "他把最后一口面包塞进嘴里：「走吧。西岸的风，我陪你去挡一半。」"
 ],
 options:[
  {t:"与洛·晨雾同行",go:"arc_mage12"}
 ]
};};
N["arc_mage12"]=function(){return{
 sceneTitle:"真理之焰 · 幕四 · 风眼",
 text:[
  "西岸的风眼，在断崖上。你站在风眼里，四周是停住的云、垂着的帆、静止的浪——世界像被抽走了「风」这个字。",
  "风眼正中央，插着一根法杖，杖身焦黑，杖头嵌着一枚碎裂的魔石。你走近时，魔石里浮起一个模糊的人影，没有五官，只有声音：「……第七遍……我数到了第七遍……」",
  "洛·晨雾在崖边站住，没有靠近。他背对着你，说：「那是两百年前埋下这根杖的法师。他念破了一层现实，自己也成了现实的一部分。」",
  "「我能做什么？」你问。",
  "「元素在听你的话。」洛·晨雾说，「你的火，认得你。让火记住风的方向——风不是敌人，它只是忘了回家的路。」",
  "你摊开手。一朵火苗在你掌心跳起来，很小，很稳。你把它放进风眼里。火苗没有熄灭，而是悬在半空，像一盏灯，缓缓地转了个方向。",
  "风眼动了。云开始流动，帆鼓了起来，浪重新有了声音。那个模糊的人影，在风里散开，最后只留下一句很轻的话：「……谢谢你，让我停手。」",
  "你收回手。洛·晨雾站在崖边，没有回头，只说了一句：「你比我想的，更像个法师。」"
 ],
 options:[
  {t:"（风已回家）回学院复命",go:"arc_mage13"}
 ]
};};
N["arc_mage13"]=function(){return{
 sceneTitle:"真理之焰 · 幕五 · 大裂解之前",
 text:[
  "终局的前夜，洛·晨雾约你在星落塔顶见面。塔顶的风很大，他站在栏杆边，手里握着那本旧册子——你一直以为它锁在你的箱底。",
  "「我知道你会问。」他说，「册子是我放回去的。你第一次进图书馆那天，我在楼上看着你伸手拿它。」",
  "你看着他。他把册子递过来：「最后一页，现在该写点什么了。」",
  "你低头看。最后一页上，你的名字旁边，多了一行字，是洛·晨雾的字迹：「门开着，但你可以选择不进去。这就是法师的真理——知道，不等于使用。」",
  "「大裂解也好，禁咒也好，」他说，「都是门。你这一路，学会了推门，也学会了不推门。现在，你该学会的是：什么时候让门开着，替后来的人，留一盏灯。」",
  "他把册子合上，放进你手里。塔顶的风吹过，你掌心那朵火苗——它还在。很小，很稳，像两百年来的每一盏灯。",
  "你握紧册子，走向塔顶的出口。风在你身后，推着你，也送着你。"
 ],
 options:[
  {t:"（带着真理之焰，走向终局）前往决战前夜",go:"ending_prelude_hub"}
 ]
};};
N["arc_war1"]=function(){return{
 sceneTitle:"战旗不倒 · 幕一 · 新兵的战旗",
 text:[
  "战神团的演武场边，插着一面褪色的旧旗。旗面灰白，边角卷起，旗杆上系着三道旧绳——每一道，都像是绑过什么东西。",
  "你练完拳，蹲在旗边喝水。一个老兵走过来，也在旗边坐下，掏出一块干肉，掰了一半给你：「新来的？」",
  "「嗯。」「这面旗，」老兵嚼着干肉，「是我们团十年前换下来的。前一任扛旗的，死在铁门关外。旗没倒，是他倒的时候，旗还插在地上。」",
  "「那它等什么？」你问。老兵看了你一眼，笑了：「等一个能把它重新扛起来的人。团长说了，谁能让旗杆上的旧绳断一根，旗就归谁。」",
  "你站起来，握住旗杆。三道旧绳在你指下绷紧——你还没用力，第一道绳，自己断了。"
 ],
 options:[
  {t:"把旧旗扛起来",go:"arc_war2"}
 ]
};};
N["arc_war2"]=function(){return{
 sceneTitle:"战旗不倒 · 幕一 · 旗在肩上",
 text:[
  "旗杆比你想的重。不是木头的重量——是那些年、那些人、那些没回来的人，都压在旗面上。",
  "你扛着旗走回营房。一路上，老兵们看见你，都停下来。没有人说话，只是看着那面旗，看着你，眼神很奇怪——像在看一个很老的朋友，又像在看一个很新的开始。",
  "晚上，老兵来找你，递给你一瓶酒：「旗归你了。但有句话，我得先跟你说。」",
  "「你说。」「扛旗的人，战场上不能第一个冲。」老兵说，「你得看着旗——旗在哪，人在哪，仗就在哪打完。」他顿了顿，「上一个扛旗的，忘了这句话，冲在最前面。他倒下了，旗还在，可团里没了主心骨。」",
  "你把酒接过来，喝了一口，辣得喉咙发紧：「我记住了。」",
  "老兵笑了，拍拍你的肩：「记住就好。旗在肩上，不是让你出风头，是让全团的人，有个地方看。」"
 ],
 options:[
  {t:"（旗在肩上）把这句话刻进心里",go:"arc_war3"}
 ]
};};
N["arc_war3"]=function(){return{
 sceneTitle:"战旗不倒 · 幕一 · 旧绳",
 text:[
  "第二天晨练，你把旗插回演武场边。老兵们围着看，有人伸手摸了摸旗面，又缩回去，像是怕碰坏了。",
  "团长来了。他四十出头，左臂空荡荡的袖管别在腰带上，站在旗前看了很久：「十年了。」他说，「十年没人敢碰这面旗。」",
  "「旗杆上的三道绳，」你问，「是什么意思？」",
  "「三道绳，是三个扛旗的人。」团长说，「第一个死在东境，第二个死在铁门关，第三个……」他顿了顿，「第三个把旗带回来了，自己也把命留在了半路上。旗是我们团的骨头，谁扛旗，谁的骨头就硬一分。」",
  "他看着你，眼神很沉：「你扛了旗，就是团里的脸。战场上的第一刀，会先找你。你怕吗？」",
  "你握紧旗杆，说：「怕。但旗在，就不怕了。」",
  "团长笑了。他伸手，把你肩上的旧绳重新系了一道，系得很紧：「好。这句话，够你扛这面旗了。」"
 ],
 options:[
  {t:"（你已是扛旗人）北境来信",go:"arc_war4"}
 ]
};};
N["arc_war4"]=function(){return{
 sceneTitle:"战旗不倒 · 幕二 · 北境的信",
 text:[
  "一封没有署名的信，从北境寄到学院，封面上只有你的名字。信纸很薄，展开时掉出一枚干涸的血指印——按在信纸的右下角，像一枚印章。",
  "信只有三行字：「铁门关外，东军的营帐又多了三座。关里的粮价翻了一倍。你师父——那个教你握刀的人——三天没下城墙了。」",
  "你翻来覆去地看。信封上没有任何寄件人信息，笔迹陌生，但字里行间的口吻，像是一个知道你是谁的人。",
  "你师父。你想起小时候在镇口的打铁铺，那个教你握刀的老铁匠——他右手有六根手指，他说那是打铁打出来的，你一直不信。",
  "你捏着那枚血指印，指腹摩挲着干涸的痕迹。信纸的边角已经卷起，像是被很多人传看过——这封信，绕了很多人的手，才到你这里。"
 ],
 options:[
  {t:"把信收好，记下北境的局势",go:"arc_war5"}
 ]
};};
N["arc_war5"]=function(){return{
 sceneTitle:"战旗不倒 · 幕二 · 六指的铁匠",
 text:[
  "你去找战神团的教头，问起北境的事。教头叼着烟杆，想了很久：「北境啊……二十年前，铁门关外有个铁匠，打了一辈子刀。关里的兵，都用他打的刀。」",
  "「他右手有六根手指。」你说。",
  "教头的手顿住了。烟灰落在桌上：「你认识他？」",
  "「他教过我握刀。」",
  "教头沉默了很久，把烟杆在鞋底磕了磕：「那你记着——他的刀，刀背比刀刃宽。他说，刀背是用来挡的，刀刃是用来吓人的。真到了拼命的时候，他挡在所有人前面，让刀背替他挨。」",
  "「他还活着吗？」你问。",
  "「铁门关的城墙还没倒，」教头说，「他就还活着。」他顿了顿，「但他三天没下城墙——这世上能让六指的铁匠三天不下城墙的，只有一样东西：他打的那把刀，锈了。」",
  "你攥紧拳头。你知道那是什么意思——师父的刀锈了，就是师父老了，老到握不住刀了。而北境，还有人记得他。"
 ],
 options:[
  {t:"（师父的刀锈了）荣耀与价钱",go:"arc_war6"}
 ]
};};
N["arc_war6"]=function(){return{
 sceneTitle:"战旗不倒 · 幕二 · 旗的预备",
 text:[
  "学院放春假前，你在演武场把旗插回原位，练了整整一个下午的刀。收刀时，你发现旗杆上那三道旧绳，又断了一道。",
  "旗面在风里舒展开，露出旗角上一道暗红色的旧渍——不是染料，是浸进去的血。你伸手摸了一下，那渍迹还是硬的，像结了十年的痂。",
  "你忽然明白了一件事：扛旗的人，早晚要走到旗第一次倒下的地方去。不是因为你想证明什么——是因为旗在等你，等你把它带回它该在的地方。",
  "你把刀收进鞘里，站在旗前，低声说：「师父，再等等我。等我把这面旗扛到铁门关，你的刀，就不会锈了。」",
  "风把旗吹得猎猎作响，像是一个回答。"
 ],
 options:[
  {t:"（你已闻到北境的风）有人买你一场败",go:"arc_war7"}
 ]
};};
N["arc_war7"]=function(){return{
 sceneTitle:"战旗不倒 · 幕三 · 荣耀的价",
 text:[
  "一个穿灰色斗篷的人，在酒馆角落等你。他推过来一个钱袋，鼓鼓的，银币的边沿从袋口露出来：「演武场的冠军——输给一个人，这袋钱就是你的。输得漂亮，加一倍。」",
  "「输给谁？」「北方来的一位佣兵。」灰斗篷说，「他需要一场胜仗，好回北境交差。你只需要躺下，演得真一点。」",
  "你看着那袋钱。钱袋上绣着一枚狼头——北境部落的纹章。你忽然明白：这不是买输赢，是买你在北境的「名声」。有人要带着「战胜战神团冠军」的名声，回铁门关去，站上一个重要的位置。",
  "你伸手，把钱袋推回去。灰斗篷皱眉：「嫌少？」",
  "「不是。」你说，「我师父在铁门关。我要是演了这场败，我在关里就抬不起头了——而这世上，还有一个人，会为我的名声觉得丢脸。」",
  "灰斗篷看了你很久，把钱袋收回怀里：「你师父养了个好徒弟。」他站起来，压低声音，「那么，换个说法——北境要打仗了。你师父打的那把刀，有人想要它的命。你自己掂量。」"
 ],
 options:[
  {t:"收下这个警告，开始备战",go:"arc_war8"},
  {t:"把钱袋留下，也留下你的态度（硬气）",go:"arc_war8"}
 ]
};};
N["arc_war8"]=function(){return{
 sceneTitle:"战旗不倒 · 幕三 · 一场演出来的仗",
 text:[
  "演武场那场比试，你打了。北方佣兵的剑很快，但你更快——你赢了他，赢得干脆利落。",
  "灰斗篷在人群里看着你，没有生气，反而笑了笑，转身走了。你忽然明白：他根本不在乎你输赢。他要的，是你「和北境佣兵交过手」这个事实——你的名字，已经和铁门关绑在一起了。",
  "晚上，教头找你喝酒：「听说你今天打了一场。」",
  "「嗯。」「打赢了？」「赢了。」",
  "教头喝了一口酒，慢悠悠地说：「打赢好。但你要记住——有些仗，打赢了，才刚开始。你今天的名字传出去，北境那边，就有人会拿着你的名字，去办他们自己的事。」",
  "你放下酒杯：「那我该怎么做？」",
  "教头看着你：「把自己的名声，握在自己手里。别人拿你的名字当刀使，你就让那把刀，只替你一个人砍。」",
  "窗外，风把战旗吹得猎猎作响。你攥紧酒杯——你知道，你已经站在一条线的边上了。"
 ],
 options:[
  {t:"（名声已飞出学院）铁门关的战报",go:"arc_war9"}
 ]
};};
N["arc_war9"]=function(){return{
 sceneTitle:"战旗不倒 · 幕三 · 旗角的血",
 text:[
  "春假结束那天，北境的战报传到学院：铁门关外，东军压境，守军苦战十日。战报最后一行写着：「镇北军统领秦·长风，亲自登墙，三日未下。」",
  "战报下面，附着一行小字，是团长的手迹：「秦·长风——战神团上一任扛旗人。他的旗，还在铁门关城楼上。」",
  "你站在演武场边，看着自己扛的那面旧旗。旗角那道暗红旧渍，忽然变得刺眼——那是秦·长风的血，是十年前铁门关的血，是一个扛旗人留给后来者的信。",
  "你伸手，把旗杆上的第三道旧绳，轻轻解开。绳子在你手里，像一截枯骨，簌簌地碎成灰。",
  "「旗在人在。」你对自己说。然后你走进营房，开始收拾行囊。"
 ],
 options:[
  {t:"（旗在等你）赶往铁门关",go:"arc_war10"}
 ]
};};
N["arc_war10"]=function(){return{
 sceneTitle:"战旗不倒 · 幕四 · 旗在人在",
 text:[
  "铁门关外，风卷着雪粒，打在脸上像砂纸。城楼上，一面战旗缺了一角，旗杆上绑着三道新绳——绑得很紧，像是怕风把它吹走。",
  "你扛着自己的旧旗，走到关前。守城的兵拦住你，你亮出战神团的令牌。一个老卒看了看你肩上的旗，忽然直了直身子：「团里的旗？你是……」",
  "「我是来替它回家的。」你说。",
  "老卒沉默了一会儿，侧身让开：「统领在城楼上。他三天没下来了——他说，他在等一面旗。」",
  "你走上城楼。风雪里，秦·长风背对着你，站在墙垛边，看着北边。他的背影很直，但你知道，他腰间那把刀，刀背比刀刃宽——是你师父打的刀。"
 ],
 options:[
  {t:"走上前，把旧旗递给他",go:"arc_war11"}
 ]
};};
N["arc_war11"]=function(){return{
 sceneTitle:"战旗不倒 · 幕四 · 两代旗手",
 text:[
  "秦·长风转过身。他比你想象的老，眉梢结着霜，眼角的皱纹像刀刻的。他看见你肩上的旧旗，眼神动了一下：「这面旗……我找了十年。」",
  "「它等你回去。」你说，「团长说，旗在，团就在。」",
  "秦·长风伸手，摸了摸旗面，指腹摩挲着那道暗红旧渍，声音有些哑：「这是老六的血。十年前，他替我扛旗，死在关外。我把旗插回地上，想回去背他——东军的箭，把我的路封了。」",
  "「我师父，」你问，「那把刀……」",
  "秦·长风低头，看着腰间那把刀：「你师父还活着。他在关内打铁——他不肯走，说关里的兵，刀断了，得有人打。」他顿了顿，「但他打不动了。他让我转告你一句话。」",
  "「什么话？」",
  "「他说：刀背比刀刃宽，是因为挡在别人前面的人，才配叫刀。」秦·长风看着你，「你师父把这句话留给了你。现在，轮到你了。」"
 ],
 options:[
  {t:"（接过这句话）站上城楼",go:"arc_war12"}
 ]
};};
N["arc_war12"]=function(){return{
 sceneTitle:"战旗不倒 · 幕四 · 城楼一夜",
 text:[
  "那一夜，你站在铁门关的城楼上，旧旗插在身边，旗面在风里猎猎作响。秦·长风靠坐在墙垛边，闭着眼，像是睡着了，又像是醒着。",
  "北边，东军的营火星星点点，像一条伏在地上的火蛇。你数了数，比白天又多了一处。",
  "「怕吗？」秦·长风忽然开口。",
  "「怕。」你说，「但我师父说过，怕，是刀鞘。刀在鞘里，才锋利。」",
  "秦·长风笑了一声，很轻：「你师父是个好铁匠。」他睁开眼，看着北边的营火，「明天，东军会试探着攻一次关。你不用出手——你只要站在这面旗旁边，让他们知道，战神团的旗，在铁门关。」",
  "「他们知道又怎样？」",
  "「他们知道，」秦·长风说，「就不会把铁门关当软柿子捏。一面旗，有时候比一万把刀有用。」",
  "风把雪吹进墙垛。你握紧旗杆，第一次觉得，旗的重量，原来是这样。"
 ],
 options:[
  {t:"（一夜过去，天光将亮）秦·长风约你",go:"arc_war13"}
 ]
};};
N["arc_war13"]=function(){return{
 sceneTitle:"战旗不倒 · 幕五 · 旗之问",
 text:[
  "天光将亮时，秦·长风把腰间的刀解下来，递到你面前。刀鞘旧了，缠着布，但刀柄磨得发亮——是常被人握着的痕迹。",
  "「你师父打的刀，一共打了三把。」秦·长风说，「一把在东境，一把在铁门关，一把在打铁铺的墙上挂着——他等你回去拿。」",
  "「这是铁门关那把。现在，我把它给你。」",
  "你没有接。秦·长风举着刀，看着你：「我问你一个问题——你这一路，扛旗、练刀、赶路，为的是什么？」",
  "你沉默了一会儿。风雪在身后，城楼在脚下，北边的营火在天边。「为的是……」你顿了顿，「让扛旗的人，不用一个人扛。」",
  "秦·长风笑了。他把刀放进你手里，刀柄温热——是他的体温。「好答案。」他说，「旗归你，刀归你，这句话也归你。铁门关，交给你守了。」",
  "你握紧那把刀。刀背比刀刃宽，沉甸甸的，像一句承诺。远处，第一缕天光爬上城墙，把旧旗照得发亮——旗角那道暗红的旧渍，在天光里，像一枚勋章。"
 ],
 options:[
  {t:"（扛着旗、带着刀，走向决战前夜）前往终局",go:"ending_prelude_hub"}
 ]
};};
N["arc_priest1"]=function(){return{
 sceneTitle:"圣光之问 · 幕一 · 静默的见习",
 text:[
  "圣辉教会的见习室里，靠窗的位置放着一本空白的圣典。封面烫着金十字，内页却空无一字——只有扉页上，有一行褪色的字：「当你写下第一句，你就开始怀疑。」",
  "你问值守的老执事，为什么圣典是空的。老执事看了你一眼：「每一任见习牧师都写过，又都撕掉了。写到最后，都觉得不如不写。」",
  "「那他们后来呢？」你问。",
  "「后来？」老执事擦着圣坛，「后来的事，你自己去写吧。笔在抽屉里，纸在你心里。」",
  "你拉开抽屉。里面躺着一支旧羽毛笔，笔尖磨得秃了，笔杆上有一道深痕——像被谁狠狠攥过。",
  "你拿起笔。笔杆温热，像是上一任主人刚放下不久。窗外，教堂的钟，正敲到第三下。"
 ],
 options:[
  {t:"在空白的圣典上，写下第一行字",go:"arc_priest2"}
 ]
};};
N["arc_priest2"]=function(){return{
 sceneTitle:"圣光之问 · 幕一 · 第一行字",
 text:[
  "你写下的第一行字是：「神，如果存在，为什么让圣典空白？」",
  "墨迹在纸面上洇开。你盯着那行字，忽然觉得不安——你抬头，见习室里空无一人，只有窗外的一束光，斜斜地落在圣坛上。",
  "那束光里，有细小的尘埃在浮动，像无数只眼睛，安静地看着你。你等了很久，没有回应，也没有雷声。只有钟声，又敲了一下。",
  "你忽然明白了什么：你写下问题，就是开始寻找答案。而教会里，很多人宁可相信答案，也不愿看见问题。",
  "你合上圣典。封面上，那行褪色的字在光里亮了一下——「当你写下第一句，你就开始怀疑。」你低头看了看自己的手，笔尖的墨，还没干。"
 ],
 options:[
  {t:"（怀疑开始了）使徒宫的钟",go:"arc_priest3"}
 ]
};};
N["arc_priest3"]=function(){return{
 sceneTitle:"圣光之问 · 幕一 · 钟声的规矩",
 text:[
  "老执事告诉你一个教会的规矩：教皇在位时，使徒宫的钟每天准时报时。教皇沉眠后，钟就不再报时——只有发生大事，钟才会自己响一声。",
  "「教皇为什么会沉眠？」你问。",
  "老执事沉默了很久：「教皇太老了。老到圣光都撑不住他的身体——他必须沉眠，把力量留在使徒宫里，等一个能接替他的人。」",
  "「那钟呢？它怎么知道该响？」",
  "「钟不知道。」老执事说，「钟只是听着。教皇在位的时候，钟每天听他的呼吸；教皇沉眠了，钟就听自己的心跳。它响，是因为它觉得——该响了。」",
  "你抬头看向使徒宫的尖顶。那口钟沉默地挂在那里，像一只闭着的眼睛。你忽然想：如果有一天，钟响了，而圣城的人不知道该做什么——那才是真正的大事。",
  "你把这句没说完的话咽回去。有些问题，现在问出口，还没有答案接着。"
 ],
 options:[
  {t:"（钟在等你听）净化令扩大",go:"arc_priest4"}
 ]
};};
N["arc_priest4"]=function(){return{
 sceneTitle:"圣光之问 · 幕二 · 使徒宫的钟",
 text:[
  "净化令扩大那天，圣城的街道上多了许多白袍执事。他们挨家敲门，查书、查信、查「不洁之物」，敲门的节奏又快又重，像某种节拍。",
  "你在街角看见一个书商被带走。他四十多岁，留着山羊胡，被两个执事架着，怀里还抱着他的账本。他经过你身边时，看了你一眼——不是求救，是提醒。",
  "「他犯了什么？」你问旁边的老执事。",
  "老执事叹了口气：「他的书店里，有一本旧册子，讲的是圣城建立之前的事。」他压低声音，「有些书，不是书的问题——是看的人心里，先有了问题。」",
  "你回到见习室，翻开自己的圣典。你写的那行字还在：「神，如果存在，为什么让圣典空白？」",
  "你看着那行字，忽然听见远处传来一声钟响。很轻，很远——但确实响了。使徒宫的钟，在白天，响了一声。"
 ],
 options:[
  {t:"（钟响了）去查那本旧册子",go:"arc_priest5"}
 ]
};};
N["arc_priest5"]=function(){return{
 sceneTitle:"圣光之问 · 幕二 · 圣城之前",
 text:[
  "你托一位当差的见习兄弟，从教会档案馆的边角，借出了那本书商被查的旧册子。册子很薄，是手抄本，字迹工整得像印刷。",
  "册子讲的是圣城建立之前的事：第一任教皇如何走进这片荒野，如何在一棵枯树下停下，如何宣布「这里将有一座城」。",
  "但册子的最后一页，夹着一张字条，是后来人写上去的：「教皇在那棵树下停下的原因，册子里没有写。有人说是看见光，有人说是听见声音，也有人——说他只是走累了。」",
  "你看着那张字条，字迹很新，墨色还没完全干透。有人在借这本书之后，专门补了这一笔。",
  "你翻回第一页。第一任教皇的名字，在灯下很清晰。你忽然想问：一个走累了的人，宣布这里将有光——他信的是光，还是信的是「会有光」？",
  "窗外，钟声又响了一下。这一次，比上一次近。"
 ],
 options:[
  {t:"（怀疑生根了）圣光落错了地方",go:"arc_priest6"}
 ]
};};
N["arc_priest6"]=function(){return{
 sceneTitle:"圣光之问 · 幕二 · 一页笔记",
 text:[
  "合上旧册子时，你发现封底夹层里还有一张纸。抽出来，是一页笔记，字迹与那张字条相同——是同一个人写的。",
  "笔记很短：「我查遍了教会档案，第一任教皇在枯树下停下的真正原因，只剩下一个传说：他听见枯树里有一个声音，说——『我不是神，我只是比你早到。』」",
  "你握着那页笔记，指尖发凉。如果传说是真的——那么圣城建立的原因，不是「神指引」，而是「一个人听见了一棵树的话」。",
  "而教会这两百年所有的教义、净化令、圣典与钟声，都建立在这个传说之上：一座城，供奉着一个「比你早到」的声音。",
  "你默默地把笔记塞回夹层。你忽然明白，为什么那些写圣典的见习牧师，最终都撕掉了自己的字——有些问题，一旦看见，就再也回不到「看不见」的时候了。",
  "你把册子合上，放回抽屉。手指碰到那支秃了的羽毛笔，笔杆上的深痕，像一道没有愈合的伤口。"
 ],
 options:[
  {t:"（你已看见）净化行动开始",go:"arc_priest7"}
 ]
};};
N["arc_priest7"]=function(){return{
 sceneTitle:"圣光之问 · 幕三 · 圣光之暗",
 text:[
  "净化行动那天，你随执事队伍走进城西的贫民区。目标是一间地下小教堂——有人举报，那里供奉着一尊「旧神」的石像。",
  "执事们破门而入。地下室里很暗，只有一个老妇人跪在一尊石像前。石像没有面孔，双手摊开，像在接雨。",
  "老妇人看见白袍，没有跑，只是抬头，浑浊的眼睛看着为首的执事：「这是我家祖辈供的。它保佑我们这些没名字的人，不饿死。」",
  "执事宣读了净化令，命令她交出石像。老妇人抱着石像不撒手。争执中，执事推了她一把——她跌倒，石像摔在地上，碎成两半。",
  "石像裂开的断面里，露出一枚发黑的铜徽。你弯腰捡起铜徽，翻过来，背面刻着一行字——「圣城初建时，救济贫民的徽记。」",
  "你握着铜徽，抬头看向那尊碎裂的、无面的石像。它没有面孔，但你知道它在看你。你忽然明白了：圣光落下来的时候，不会问该不该——它只管落。",
  "而你，第一次，不想接住这道光。"
 ],
 options:[
  {t:"上前扶起老妇人（你选择站在人这边）",go:"arc_priest8"},
  {t:"低头执行净化令（你选择服从秩序）",go:"arc_priest8"}
 ]
};};
N["arc_priest8"]=function(){return{
 sceneTitle:"圣光之问 · 幕三 · 铜徽",
 text:[
  "你把铜徽收进怀里，没有上交。那晚回到见习室，你把它放在圣典旁边，对着它坐了很久。",
  "铜徽很旧，边缘磨得圆滑，是被无数只手摸过的痕迹。你想起老妇人的眼睛——浑浊、疲惫，但有一种你不敢看的平静。她信的不是神，是「有人会管他们」这件事。",
  "而教会的净化令，正在把「有人会管他们」，从他们手里拿走。",
  "你拿起笔，在空白的圣典上，写下了第二行字：「如果圣光不问该不该，那我替它问。」",
  "写完，你把笔放下。笔杆上的深痕，正对着你的掌心——像一道旧伤口，终于等到了要接住它的人。",
  "窗外，夜色很沉。使徒宫的钟，没有再响。但你知道，它听得到。"
 ],
 options:[
  {t:"（你已站在光与人的缝隙里）静默殿的门",go:"arc_priest9"}
 ]
};};
N["arc_priest9"]=function(){return{
 sceneTitle:"圣光之问 · 幕三 · 两难的选择",
 text:[
  "第二天，执事长找到你，递给你一份名单：「城西还有三处旧神祭坛。你熟悉那一带，明天带一队人去净化。」",
  "名单上，第一处就是你昨天去的那间地下小教堂。而你知道，那个老妇人，今天没有地方去——她住在教堂后面的棚屋里，石像碎了，她的命，好像也碎了一半。",
  "「净化」两个字，在名单上躺着，白纸黑字，很干净。但你脑子里，全是老妇人倒下去时，那枚铜徽从石像里滚出来的声音。",
  "你站在执事长面前，手里握着名单。纸很轻，却像一块铁——你忽然明白，这就是圣职者每天要端平的东西：一边是「照章办事」，一边是「你亲眼看见的人」。",
  "你深吸一口气，把名单折起来，收进怀里：「我去。」你说。但你心里已经知道，这趟差事，你不会按章办完。"
 ],
 options:[
  {t:"（你做出了选择）带着铜徽出发",go:"arc_priest10"}
 ]
};};
N["arc_priest10"]=function(){return{
 sceneTitle:"圣光之问 · 幕四 · 静默殿门",
 text:[
  "净化进行到第三处祭坛时，你让队伍停在巷口，自己先进去。祭坛里没有人，只有一尊与上次一样的无面石像。",
  "你站在石像前，把怀里的铜徽拿出来，放在它脚下。你轻声说：「我不是来砸你的。我是来告诉你——还有一个人，记得你们。」",
  "身后，传来脚步声。你回头，一个白袍老者站在门口，没有带执事，也没有带圣典。他看了你很久，说：「你在对一个石像说话。」",
  "「石像听了。」你说。",
  "老者沉默。他走进来，蹲下，捡起那枚铜徽，翻来覆去看了看：「圣城初建时的救济徽记……你知道这枚徽记后来为什么不用了吗？」",
  "你摇头。老者把铜徽放回石像脚下：「因为圣城富了。富到不再需要'救济'这个词——也就不再需要提醒自己的人。」他站起来，看着你，「我叫克莱门。他们说，我是圣城里最会说话的人。但其实，我这一生，只在等一个人来问我那个问题。」"
 ],
 options:[
  {t:"问出那个问题",go:"arc_priest11"}
 ]
};};
N["arc_priest11"]=function(){return{
 sceneTitle:"圣光之问 · 幕四 · 克莱门·圣言",
 text:[
  "你问：「神，存在吗？」",
  "克莱门·圣言没有立刻回答。他走到石像前，用手掌擦了擦石像肩上的灰：「我见过教皇年轻时的样子。他跪在圣坛前，整夜整夜地祈祷，不是求力量——是求一个答案。」",
  "「他求到了吗？」",
  "「他求到了一个答案：'神不一定存在，但人需要相信'。」克莱门说，「他后来把这句话，锁进了一间只有他知道的房间里。然后他告诉全圣城——神存在，且圣光永在。」",
  "你沉默了很久：「所以……教皇也不确定？」",
  "克莱门看着你：「教皇比你确定。他确定的是：'相信'比'真相'更能养活一座城。他选了相信——他把自己的怀疑，连同自己的身体，一起沉眠在使徒宫里了。」",
  "他顿了顿：「这就是我要等的问题。现在，它问出来了。你呢——你打算信什么？」",
  "你站在静默殿的门槛上。身后是圣城的灯火，面前是石像与铜徽。你忽然觉得，这一路所有的疑问，都汇成了这一个字：「信」。"
 ],
 options:[
  {t:"信人（你选择相信眼前的人）",go:"arc_priest12"},
  {t:"信光（你选择相信那道圣光）",go:"arc_priest12"}
 ]
};};
N["arc_priest12"]=function(){return{
 sceneTitle:"圣光之问 · 幕四 · 信",
 text:[
  "你走出静默殿时，克莱门·圣言没有送你。他只是站在门后，说了一句：「记住你今天选了什么。钟声再响的时候，你会知道为什么。」",
  "回到见习室，你翻开圣典。两行字并列躺着：「神，如果存在，为什么让圣典空白？」「如果圣光不问该不该，那我替它问。」",
  "你拿起那支秃笔，在下面写下了第三行字：「信。不是信神，也不是信光——是信一个'还会问'的自己。」",
  "写完，你把笔放下。笔杆上的深痕，正对着你的掌心，像一道合拢的伤口。",
  "窗外，使徒宫的钟，在暮色里响了一声。这一次，你没有抬头看钟——你低头看自己的手。你忽然明白，钟声不是答案，是提醒：提醒你，你还活着，还能问。",
  "而活着的人，才配谈信。"
 ],
 options:[
  {t:"（你已立信）钟声夜响，去见克莱门",go:"arc_priest13"}
 ]
};};
N["arc_priest13"]=function(){return{
 sceneTitle:"圣光之问 · 幕五 · 钟声之前",
 text:[
  "决战前夜，使徒宫的钟在夜里响了一声。全圣城都醒了，只有你，像是早就知道——你披上见习牧师的白袍，走向静默殿。",
  "克莱门·圣言在殿门口等你。他手里拿着一本薄薄的册子——不是圣典，是那本你写了两行字的空白圣典。",
  "「钟响了。」他说，「你知道它为什么响吗？」",
  "「因为该响了。」你说。",
  "克莱门笑了：「圣城的人会慌。他们会想：教皇沉眠，钟却响了，是不是圣光要走了？」他顿了顿，「他们需要一个人告诉他们，钟响不是末日——是提醒。」",
  "「你要我去说？」",
  "「我要你去说。」克莱门把圣典递给你，「不是以教皇的名义，也不是以圣光的名义——以你自己的名义。告诉他们：钟响了，是因为还有一个会问的人，在圣城里醒着。」",
  "你接过圣典。扉页上，三行字在灯下微微发亮。你合上它，转身，走向使徒宫的方向。",
  "身后，克莱门·圣言的声音很轻：「记住——神不一定在光里。但那个'会问'的人，一定在你身体里。」",
  "你没有回头。钟声在你身后，又响了一声。"
 ],
 options:[
  {t:"（带着你的信，走向决战前夜）前往终局",go:"ending_prelude_hub"}
 ]
};};
/* ===== /v55inj:arcA ===== */
/* ===== v55inj:arcB 职业命运弧 B（灵魂法师/术士/骑士） ===== */
N["arc_soul1"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕一 · 无影的学徒",
 text:[
  "晨曦圣殿的灯架上，有一排魂灯。灯的数目是固定的——每盏灯，对应圣殿里的一位灵魂法师。据说，人死灯灭，人活灯明。",
  "你入殿的第一天，就发现灯架尽头多了一盏灯。没有灯油，没有火，但灯芯是新的——像是有人专门为它留了个位置。",
  "你问掌灯的老修女，这盏灯是谁的。老修女看了你很久，说：「灯架上的灯，是给'还没来的人'留的。你来了，它就有主了。」",
  "她递给你一盏小铜灯：「从今天起，你守着它。灯在，你在；灯灭，你……」她没说完，只是把铜灯放进你手里。",
  "铜灯很轻，但握着它的时候，你总觉得，灯芯里有什么东西，在看着你——不是恶意，是一种很老的、等着你的目光。"
 ],
 options:[
  {t:"接过那盏铜灯",go:"arc_soul2"}
 ]
};};
N["arc_soul2"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕一 · 灯芯",
 text:[
  "第一夜，你守着铜灯打坐。灯芯没有点燃，但你闭上眼时，看见它亮了——不是火，是一种灰白色的光，像月光落在水面上。",
  "光里浮现出一个影子，模糊的，像隔着很厚的雾。影子开口说话，声音很远：「……灯是给没来的人留的。你来了，那盏灯，就是你的命。」",
  "你睁开眼。铜灯没有亮，灯芯静静地躺着，像什么都没发生过。但你手心全是汗——那声音，你认得。",
  "你小时候，有一年冬天发烧，烧了三天。昏迷中，你梦见一盏灯，灯下坐着一个灰袍人，给你喂了一勺水。你醒过来，烧退了。家里人说，是隔壁老奶奶照顾的你——但你知道，喂你水的，是那个灰袍人。",
  "你低头看铜灯。灯芯上，有一道极细的焦痕——像是很久以前，被点过一次。"
 ],
 options:[
  {t:"（灯认出了你）向掌灯修女打听",go:"arc_soul3"}
 ]
};};
N["arc_soul3"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕一 · 灰袍人",
 text:[
  "你问老修女，圣殿里有没有一个灰袍人——一个喂小孩喝水的灰袍人。老修女手里的抹布停了一下：「你见过他？」",
  "「我小时候发烧，他喂过我水。」你说。",
  "老修女沉默了很久：「圣殿的灰袍人，只有一位。他守着一间地下密室，二十年前就没人见过他出来了。」她顿了顿，「但他喂你水的那年，你几岁？」",
  "「五岁。」",
  "「五岁……」老修女算了算，「二十年前，他进密室那年，正好是你五岁那年。」",
  "你愣住了。老修女看着你，眼神复杂：「孩子，灯架上的灯，不是随便留的。你的铜灯，是他进密室之前，亲手放上去的。」",
  "「他为什么给我留灯？」你问。",
  "老修女没有回答。她只是说：「等你境界够了，自己下去问他。」"
 ],
 options:[
  {t:"（灯与灰袍人之间，有一根线）地下密室",go:"arc_soul4"}
 ]
};};
N["arc_soul4"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕二 · 镜中的访客",
 text:[
  "守镜人澜·梦墟传话让你去镜厅时，你正在抄经。传话的见习修女压低声音：「澜大人说，镜子里有位客人，说是来找你的。」",
  "镜厅是圣殿的禁地，一面巨大的铜镜立在厅中央，镜面磨得发亮，倒映着厅里的一切——除了你自己。",
  "你走到镜前。镜面上，你的倒影没有出现，反而浮起一层灰色的雾。雾里，一个模糊的影子渐渐清晰——灰袍，枯瘦，坐在一张旧椅子上，像坐了很久。",
  "「你来了。」灰袍人的声音从镜面里传出来，很轻，「我的灯，给你了。你点过它了吗？」",
  "「没点。」你说，「它没有灯油。」",
  "灰袍人沉默了一会儿：「灯油，在灯架底下的暗格里。但你得想清楚——点了它，你就知道自己是盏什么灯了。有些灯，点着点着，就再也灭不掉了。」",
  "镜面里的雾散开，灰袍人的影子淡去。你站在镜前，镜面里，你的倒影慢慢浮现——它看着你，笑了一下。"
 ],
 options:[
  {t:"取出暗格里的灯油",go:"arc_soul5"}
 ]
};};
N["arc_soul5"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕二 · 灯油",
 text:[
  "灯架底下的暗格，藏得很深，你几乎要趴在地上才够得到。格子里放着一只陶瓶，瓶口封着蜡，蜡上印着一枚徽记——不是圣殿的纹章，是一盏灯的图案。",
  "你揭开蜡封。瓶里是一种透明的液体，没有气味，却让整个暗格都亮了起来——不是火的光，是一种从液体内部透出来的、灰白的光。",
  "你端着陶瓶，走到自己的铜灯前。灯芯静静地躺着。你把灯油倒进灯盏，一滴、两滴、三滴——灯油接触到灯芯的瞬间，你听见一声叹息。",
  "不是从灯里传来的，是从你心里传来的。你忽然觉得，这盏灯，等的不是灯油，是你。",
  "你没有点火。你把灯放回灯架。那盏灯，在灯架尽头，静静地立着——你知道，总有一天，你会亲手点亮它。",
  "澜·梦墟在镜厅门口等你。她看着你手里的陶瓶，只说了一句：「点灯之前，先想清楚你要问什么。灯一旦亮了，问出来的问题，就没有回头的路了。」"
 ],
 options:[
  {t:"（灯油在手）魂秤之约",go:"arc_soul6"}
 ]
};};
N["arc_soul6"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕二 · 魂秤",
 text:[
  "圣殿的档案室里，你查到了「魂秤」的记载：灵魂法师之间，衡量「魂的重量」的器具。据说，每一个灵魂法师，一生都要上一回魂秤——称一称，自己的魂，值几钱。",
  "记载的最后一页，有一行批注，字迹与灰袍人的一样：「魂秤不是称魂。是称你在死之前，有没有把该还的还完。」",
  "你合上档案，忽然明白了灰袍人的话——他给你留灯，不是选中了你，是托付了你：他有一笔「没还完的账」，需要一盏灯来继续还。",
  "你回到灯架前，看着自己的铜灯。灯芯上的焦痕，像一道旧账的印记。你伸手，轻轻摸了摸它——灯芯，微微动了一下。",
  "那不是错觉。灯，在等你回答。",
  "你低声说：「我接。」灯芯上，那点焦痕，像是淡了一分。"
 ],
 options:[
  {t:"（你已接下这盏灯）魂秤之约传来",go:"arc_soul7"}
 ]
};};
N["arc_soul7"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕三 · 魂秤之约",
 text:[
  "有人送来半截旧秤杆，放在圣殿门口。秤杆断口整齐，像是被利器削断的，断面在晨光里发亮。",
  "你捡起秤杆。秤杆上用灵魂法师的密文刻着一行字：「十年之约，魂灯相照。你既然接了他的灯，就该替他上秤。」",
  "你问澜·梦墟，这是什么意思。澜·梦墟看着那半截秤杆，脸色微变：「这是魂秤的一半。另一半，在一位'还活着的前代挑战者'手里——他等这笔账，等了十年。」",
  "「什么账？」",
  "「灰袍人当年与他同修一道，最后灰袍人胜了，继承了那间密室的钥匙。」澜·梦墟说，「他不服。他放出话：谁接灰袍人的灯，谁就得替他还这一秤。」",
  "你握着那半截秤杆，秤杆很凉。你忽然明白，这盏灯，不只是灯——是一笔债，一段旧怨，一个等了十年的约定。",
  "而你，已经点了灯。"
 ],
 options:[
  {t:"赴约（你已接下灯）",go:"arc_soul8"}
 ]
};};
N["arc_soul8"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕三 · 秤上",
 text:[
  "约点在圣殿外的旧墓地。你到时，一个黑袍人已经站在墓碑间，手里握着另一半秤杆。他看见你，冷笑：「他的灯，给了个毛头小子。」",
  "「灯给我了。」你说，「账，我来还。」",
  "黑袍人把两截秤杆接在一起。秤杆合拢的瞬间，你感到一股拉力——不是身体上的，是魂的：像是有什么东西，要把你的「魂」称上一称。",
  "「称魂，不问修为，问心。」黑袍人说，「你接灯的时候，心里想的什么？」",
  "你想了想，说：「我想的是——那盏灯，等了他二十年。我不能让它再等下去。」",
  "黑袍人盯着你，看了很久。秤杆在你两人之间悬着，慢慢倾斜——向你这边。他沉默了一会儿，说：「你的魂，比他重。」",
  "「重在哪里？」你问。",
  "黑袍人把秤杆收回去，声音低了些：「重在你接灯的时候，没想过自己。」他转身走了几步，又停下，「这秤，我认了。但你记住——他的账还完了，你的账，才刚开始。」"
 ],
 options:[
  {t:"（秤认了你的魂）灰袍人的嘱托",go:"arc_soul9"}
 ]
};};
N["arc_soul9"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕三 · 一秤之后",
 text:[
  "你回到圣殿，把半截秤杆放在灯架下。老修女看见了，没说什么，只是递给你一盏热茶：「秤过了？」",
  "「过了。」你喝了一口茶，「他说我的魂，比灰袍人重。」",
  "老修女点点头：「那孩子没说谎。但他没说全——秤杆倾斜的方向，称的不是谁重，是谁欠得多。」她看着你，「你的魂比灰袍人重，是因为你接灯的时候，心里没给自己留位置。重，是因为你扛了不该你扛的。」",
  "你沉默。老修女继续说：「灰袍人把灯给你，不是让你替他扛——是让你替他，把这盏灯，送到它该去的地方。灯不是债，是路。」",
  "「路？」",
  "「路。」老修女说，「魂灯照着的，从来都是往前走的路。你接着灯，就是替他往前走。」",
  "你低头看着铜灯。灯芯上的焦痕，在茶水的热气里，像是化开了一点。"
 ],
 options:[
  {t:"（路在灯下）魂灯连灭",go:"arc_soul10"}
 ]
};};
N["arc_soul10"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕四 · 魂灯忽明",
 text:[
  "那一夜，圣殿的魂灯，连灭了七盏。每盏灯下，都压着一张写着你名字的纸。纸上的字，不是墨写的——是血写的，很淡，像从很远的地方渗过来的。",
  "灯架前，修女们跪了一地，低声念着安魂经。老修女站在灯架旁，脸色煞白：「七盏灯，七条命。都是老一辈的师叔伯——他们生前，都进过那间地下密室。」",
  "你握着铜灯，指尖发凉。七张纸上，都写着你的名字——像是有人，在收走他们性命的同时，把账记在了你头上。",
  "「密室。」你说，「灰袍人在里面，出事了。」",
  "老修女拦住你：「密室的门，二十年前就封死了。钥匙在灰袍人手里，谁也进不去。」",
  "你举起手里的铜灯。灯芯上，那道焦痕正在发亮——不是火，是灰白色的光。你说：「灯还亮着。他还没死。他在等我。」",
  "你走向密室的方向。身后，七盏灭灯在灯架上，像七只闭上的眼睛。"
 ],
 options:[
  {t:"（灯指路）走向密室",go:"arc_soul11"}
 ]
};};
N["arc_soul11"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕四 · 密室",
 text:[
  "密室的门，在圣殿地下的最深处。门是石制的，没有锁，只有一枚凹下去的灯形印记——正好是你的铜灯的形状。",
  "你把铜灯按进印记。门没有开，但你听见门后传来一个很轻的声音，是灰袍人的：「……你来了。灯，带了吗？」",
  "「带了。」你说。",
  "「那就点灯。」灰袍人的声音断断续续，「点灯……照见……第七盏灯的路……」",
  "你取出陶瓶，把灯油倒进铜灯。这一次，你没有犹豫——你用指腹轻轻擦过灯芯。灯芯「嗤」地亮了起来，灰白色的光，像月光一样，落满整个走廊。",
  "光落处，石门上浮现出密密麻麻的字迹——是二十年来，灰袍人一个人写在门上的笔记。字迹从工整到潦草，从潦草到颤抖：全是关于「魂灯」的研究，关于「灯照见什么」的追问。",
  "最后一行的字，尤其大：「灯照见的，从来不是路。灯照见的，是那个提着灯的人——还信不信自己。」",
  "你站在光里，握着灯，忽然明白了这扇门为什么没有锁：它等的从来不是钥匙，是一个愿意点灯的人。"
 ],
 options:[
  {t:"（灯已点亮）推开石门",go:"arc_soul12"}
 ]
};};
N["arc_soul12"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕四 · 灯下的人",
 text:[
  "石门在灰白色的光里缓缓打开。门后是一间不大的密室，四面墙壁写满字，中央放着一把旧椅子——椅子上，坐着一个灰袍人。",
  "他已经很老了，老到像一截枯木。但他睁着眼，看着你手里的灯，浑浊的眼睛里，映着那点灰白的光：「……灯亮了。好，好。」",
  "「七盏灯灭了。」你说，「七张纸上，写着我的名字。」",
  "灰袍人闭上眼：「他们……是替我去的。二十年前，我算出圣殿要有一劫——魂灯要灭七盏。我进密室，就是想找到替他们挡劫的法子。」",
  "「找到了吗？」",
  "「找到了一半。」灰袍人睁开眼，「劫，是深渊的劫。它要的是'魂灯的传承'——一个愿意接灯的人。你接了灯，劫就认了你。那七个人，是替你先走的。」",
  "你站在他面前，灯在手里，微微发烫。灰袍人看着你，一字一句：「现在，劫还在。灯在你手里——你是带着这盏灯走出去，替他们讨回这笔账，还是……」",
  "「灯在，人就在。」你说，「我走出去。」",
  "灰袍人笑了。他枯瘦的手，轻轻碰了一下灯芯：「好。灯给你了。路，你自己走。」"
 ],
 options:[
  {t:"（提着灯，走出密室）",go:"arc_soul13"}
 ]
};};
N["arc_soul13"]=function(){return{
 sceneTitle:"魂灯不灭 · 幕五 · 灯前之问",
 text:[
  "决战前夜，你提着铜灯，站在圣殿的灯架前。七盏灭灯还挂着，像七道旧疤。你点亮了自己的灯，灰白的光，把整个灯架照亮。",
  "灰袍人坐在密室门口，没有再出来。但他让老修女带了一句话：「灯照见什么，就带着什么去。」",
  "你低头看灯。灯芯里，浮起你这一路见过的人：灰袍人、老修女、黑袍挑战者、七盏灭灯下的名字……他们都在光里，安静地看着你。",
  "你忽然明白了：魂灯照见的，从来不是路。它照见的，是所有在灯下走过的人——你带着他们，才算提着灯。",
  "你举起铜灯。光落在七盏灭灯上，灯芯轻轻颤动，像是有什么东西，在黑暗里，开始苏醒。",
  "远处，深渊的气息正在逼近。你吹灭铜灯——不，不是灭。你把灯油收好，把灯放回灯架。灯芯上的焦痕，已经变成了一道细小的纹路，像一盏小小的、不灭的灯。",
  "你转身，走向决战的方向。灯，留在灯架上，替你看守着这座圣殿。"
 ],
 options:[
  {t:"（灯已传承）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
N["arc_smith1"]=function(){return{
 sceneTitle:"熔炉之心 · 幕一 · 学徒的锤",
 text:[
  "锻造公会的分锤仪式，在初火熔炉前举行。轮到你时，会长从炉边的架子上取下一柄旧锤，递给你：「这是公会留了十年的锤。上一任主人，三锤没敲完就死了。」",
  "锤柄上有三道裂痕，像三句没说完的话。你接过来，掂了掂——锤比看上去重，重心偏前，是打重活用的。",
  "「他打什么死的？」你问。",
  "会长看了你一眼：「打一件不该打的东西。」他没有多说，只是把你的名字，刻在锤柄上：「从今天起，这柄锤是你的。记住——锤子可以打铁，也可以打门。你用它打什么，你自己想清楚。」",
  "你握着那柄锤，锤柄上的三道裂痕，硌着你的掌心。你忽然觉得，这柄锤，像是专门在等你。"
 ],
 options:[
  {t:"收下这柄锤",go:"arc_smith2"}
 ]
};};
N["arc_smith2"]=function(){return{
 sceneTitle:"熔炉之心 · 幕一 · 第一锤",
 text:[
  "你第一次用这柄锤打铁，是在第二天。公会的老铁匠让你打一把短刀，你把铁坯烧红，抡起锤——第一锤落下去，铁坯发出「嗡」的一声，不是你敲铁的声音，是铁在应你。",
  "老铁匠「咦」了一声，凑过来：「再打一下。」",
  "第二锤。铁坯上的火星，像活的，顺着你的锤路走。第三锤——铁坯忽然「啪」地裂开一道纹，不是裂纹，是一道发光的纹路，像烧红的经脉。",
  "老铁匠盯着那道纹，脸色变了：「符文。这是符文——你打的不是铁，是符铁。」他抬头看你，「小子，这柄锤，认主认得太快了。它不是打铁的锤——它是一柄'封炉锤'。」",
  "「封炉？」你问。",
  "老铁匠没有回答。他只是把那块裂开的铁坯放进水里，「嗤」地一声，白汽腾起：「锤子的事，你别问了。你只要记住——这柄锤，只打该封的东西。」"
 ],
 options:[
  {t:"（把这柄锤带在身边）",go:"arc_smith3"}
 ]
};};
N["arc_smith3"]=function(){return{
 sceneTitle:"熔炉之心 · 幕一 · 三道裂痕",
 text:[
  "晚上，你在工坊里擦锤，发现锤柄的三道裂痕里，嵌着极细的金属屑。你把屑挑出来，对着灯看——是三种不同的金属：铁、铜，和一种发暗的银。",
  "你问老铁匠，这三道裂痕是怎么来的。老铁匠抽着烟，想了很久：「第一道，是打铁打裂的——他打了一辈子铁。第二道，是打兵器打裂的——他上了战场。第三道……」他顿了顿，「是打'不该打的东西'裂的。他死那天，锤柄裂了第三道。」",
  "「他打的是什么？」",
  "老铁匠把烟掐灭：「你别问了。问多了，你也会想打。」",
  "你低头看锤。三道裂痕，像三句话，一句比一句重。你把金属屑收进一个小布袋，系在锤柄上。",
  "你知道，总有一天，你会知道第三道裂痕是怎么来的。但今晚，你只想把第一锤打好。"
 ],
 options:[
  {t:"（锤在手中）炉底的动静",go:"arc_smith4"}
 ]
};};
N["arc_smith4"]=function(){return{
 sceneTitle:"熔炉之心 · 幕二 · 炉底的动静",
 text:[
  "初火熔炉的夜班，向来最安静。但你值守的那夜，炉底传来了不属于火焰的声响——一种很沉、很缓的「咚、咚」，像是有什么东西，在炉底敲墙。",
  "你凑近炉口。炉火照不亮炉底，只有一团深不见底的暗红。你举起锤——那柄旧锤，锤柄上的三道裂痕，忽然微微发烫。",
  "「咚、咚、咚。」炉底的声音，随着你握紧锤，变得清晰了。不是敲墙，是有什么东西，在应你的锤。",
  "老铁匠闻讯赶来，他听了一会儿炉底的动静，脸色凝重：「这炉子底下，压着东西。二十年前，前任锤主往炉底封了一样东西——他死了，谁也不知道他封的是什么。」",
  "他看着你手里的锤：「看来，它认的就是这件事。」"
 ],
 options:[
  {t:"（炉底在等你）询问封炉的旧事",go:"arc_smith5"}
 ]
};};
N["arc_smith5"]=function(){return{
 sceneTitle:"熔炉之心 · 幕二 · 封炉的旧事",
 text:[
  "你翻遍了公会的档案，关于初火熔炉的记录只有一条：「初火不熄，炉底不空。」旁边有一行小字批注：「封炉者，以锤定炉，以炉镇物。物不破，炉不启。」",
  "你问会长，炉底封的是什么。会长沉默了很久，从抽屉里拿出一块发黑的金属片：「前任锤主留下的。他说，炉底封的是一颗'活着的种子'——不是植物的种子，是'造物'的种子。」",
  "「造物？」",
  "「他年轻时，打出一件活的东西。」会长说，「一件不该有生命的东西，有了生命。他吓坏了，把它封进炉底——但他没舍得毁掉它。」",
  "你握着那块金属片。片上有一道极细的纹路，和你那天打出的符文纹路，一模一样。",
  "「那颗种子……」你说，「还在炉底，活着？」",
  "会长没有回答。但炉底，又传来一声「咚」——很轻，像是应答。"
 ],
 options:[
  {t:"（把那块金属片收好）",go:"arc_smith6"}
 ]
};};
N["arc_smith6"]=function(){return{
 sceneTitle:"熔炉之心 · 幕二 · 造物的代价",
 text:[
  "你开始明白，前代锤主为什么死前会「三锤没敲完」——他在封炉，封一件他造出来的、不该存在的东西。",
  "那天夜里，你做了一个梦。梦里，你坐在初火熔炉前，手里握着锤，炉火照着你。炉底传来一个声音，很年轻，像少年：「你也要封我吗？」",
  "「我没有造你。」你说。",
  "「你是锤主。」那个声音说，「锤主，就是造物的人。你握着锤，就是握着'造'的资格——你会造出什么，你会封掉什么，都是你的事。」",
  "你从梦里惊醒。锤柄上的三道裂痕，在夜里微微发光。你握着锤，坐了很久。",
  "你知道，锤主这条路，走到深处，一定会遇见「造」与「封」的选择。而那个梦，是炉底那颗种子，第一次跟你说话。"
 ],
 options:[
  {t:"（造物之责压上肩头）造物开始异动",go:"arc_smith7"}
 ]
};};
N["arc_smith7"]=function(){return{
 sceneTitle:"熔炉之心 · 幕三 · 造物的代价",
 text:[
  "异动发生在你打出一件新作品之后。那是一个铜质的小机关鸟，你照着图纸做的，本没有生命。但三天后的夜里，你听见工坊里有扑动翅膀的声音——那只铜鸟，自己在飞。",
  "它飞得很笨拙，撞到窗框，又跌下来，然后再飞起来。它没有眼睛，但你知道，它在看你。",
  "你伸手接住它。铜鸟在你掌心里，轻轻颤动，像一只真正的鸟在害怕。你忽然想起前代锤主的梦——造出一件活的东西，然后，看着它，不知道该怎么办。",
  "你握着铜鸟，炉火在你身后烧着。你心里有两个声音：一个说「它是你的造物，你有权处置」；另一个说「它活着——你造了它，就得负责」。",
  "铜鸟在你掌心里，仰起头。它没有嘴，但你听见一声极轻的、像鸟鸣一样的声音。"
 ],
 options:[
  {t:"把它拆了，回归金属（封）",go:"arc_smith8"},
  {t:"留下它，学着照顾（造）",go:"arc_smith8"}
 ]
};};
N["arc_smith8"]=function(){return{
 sceneTitle:"熔炉之心 · 幕三 · 造与封",
 text:[
  "你最终没有拆掉它。你给铜鸟装了一双新翅膀，用更轻的铜，修好了它撞歪的关节。它在你掌心站起来，抖了抖翅膀——飞起来了，飞得比刚才稳。",
  "它落在你的锤柄上，歪着头，像在打量那三道裂痕。你忽然明白：造物不是罪，造了不管才是罪。前代锤主不是错在造了它，是错在把它封进炉底，不敢再看它。",
  "你看着锤柄上的三道裂痕。第一道，打铁；第二道，打兵器；第三道——你忽然懂了：第三道裂痕，不是打出来的，是「封」出来的。他封炉的时候，锤柄裂了。",
  "你轻轻摸了摸第三道裂痕。你对自己说：我不会封了。我造的，我养。",
  "铜鸟在你肩上，发出第一声清脆的鸣叫。炉火，在你身后，烧得更亮了一些。"
 ],
 options:[
  {t:"（给铜鸟装上新的翅膀）",go:"arc_smith9"}
 ]
};};
N["arc_smith9"]=function(){return{
 sceneTitle:"熔炉之心 · 幕三 · 炉火的回声",
 text:[
  "第二天，你带着铜鸟去见会长。会长看见它，沉默了很久：「你留了它。」",
  "「留了。」你说，「我造的，我养。」",
  "会长看着你，眼神有些复杂：「前代锤主，当年也是这么说的。后来，他养的那件东西，越养越活，越活越大——大到他养不动了，才封进炉底。」",
  "「那他现在……」",
  "「他现在，还在炉底。」会长说，「他把自己，也封进去了——他说，他养的那件东西，认他的锤。他封了它，就得陪它。」",
  "你低头看锤。三道裂痕，在灯下发亮。你忽然明白：这柄锤，不是传给你的工具——是前代锤主留给你的「答案」。他用一生告诉你：造物要负责，负责到底，就是把命搭进去，也算数。",
  "你握紧锤：「我记住了。」",
  "铜鸟在你肩上，安静地站着，像一枚小小的印章。"
 ],
 options:[
  {t:"（你已接过造物之责）炉火之灾",go:"arc_smith10"}
 ]
};};
N["arc_smith10"]=function(){return{
 sceneTitle:"熔炉之心 · 幕四 · 炉火之灾",
 text:[
  "初火熔炉异动的那夜，炉火忽然暴涨，火舌舔到房梁，整个工坊都在震颤。会长带人赶到时，炉底的「咚、咚」声，已经变成了连续的、急促的敲击——像有什么东西，在炉底砸门。",
  "「炉底的东西，醒了。」会长脸色铁青，「它感应到锤主换了人——它在等新锤主，下去见它。」",
  "你握着锤，站在炉前。炉火映着你的脸，滚烫的气浪扑上来。铜鸟在你肩上，不安地扑着翅膀。",
  "「下去？」老铁匠拦住你，「炉底是初火的根，人下去，火会烧穿骨头！」",
  "你低头看锤。第三道裂痕，正在发烫——像是前代锤主，在炉底，用最后的力气，敲了一下锤柄。",
  "「它在等我。」你说，「前代锤主封它的时候，答应过它——会有下一个锤主，来看它。我不能让他失信。」",
  "你握紧锤，走向炉口。炉火在你面前，分开了一条路。"
 ],
 options:[
  {t:"（走向炉口）",go:"arc_smith11"}
 ]
};};
N["arc_smith11"]=function(){return{
 sceneTitle:"熔炉之心 · 幕四 · 炉底",
 text:[
  "炉底不是你想象的火海。火舌在头顶，像一片燃烧的天空，而炉底是一间石室——石室的中央，坐着一具枯骨，膝上放着一柄断锤。",
  "枯骨的旁边，蜷着一团暗红色的东西，像一团凝固的火焰，又像一个蜷缩的兽。它没有眼睛，但你走近时，它抬起了「头」。",
  "「……新锤主。」它的声音，低沉，生涩，像很久没说过话，「你师父，等我很久了。」",
  "你看着那具枯骨：「他是前代锤主？」",
  "「他是造我的人。」那团暗红的东西说，「我活过来那天，他怕了。他想封我，又舍不得杀我——最后，他把自己和我一起封进炉底。他说，等一个敢造、也敢养的人来。」",
  "它向你靠近了一点。炉火在它身上流动，像活的血：「你，敢养吗？」",
  "你举起锤。锤柄上的三道裂痕，在你掌心发烫——第一道打铁，第二道打兵器，第三道……你终于知道第三道裂痕是什么了：是前代锤主「造出生命」的烙印。",
  "「敢。」你说，「我造的，我养。不是我造的，我也养——你师父的账，我替他接着还。」"
 ],
 options:[
  {t:"（举起锤，接过他的账）",go:"arc_smith12"}
 ]
};};
N["arc_smith12"]=function(){return{
 sceneTitle:"熔炉之心 · 幕四 · 重铸",
 text:[
  "那团暗红的东西，缓缓立起来，像一团站立的火。它说：「你师父封我，是因为他怕我失控。其实我不是怪物——我是他打铁时，打进去的那口气。铁有灵，他打了半辈子铁，铁就把那口气，养成了我。」",
  "「你不是怪物。」你说，「你是他的作品。」",
  "它沉默了很久，炉火忽然温和下来，不再暴涨。「作品……」它重复着这个词，声音里有一种说不清的东西，「第一次，有人这么叫我。」",
  "你走到枯骨前，跪下，把那柄断锤捡起来。断口很齐，像是被他自己敲断的——他封了造物，也断了自己的锤，等于断了这条路。",
  "你把断锤放进怀里，然后转向那团火：「你师父的锤断了。我的锤，还活着。你要是愿意——跟我上去，我教你打铁。」",
  "那团火，静静地看着你。然后，它轻轻点了一下「头」：「……好。我跟你走。」",
  "炉火，在你身后，缓缓归位。石室里，前代锤主的枯骨，安静地坐着，像终于放下了什么。"
 ],
 options:[
  {t:"（带它走上地面）",go:"arc_smith13"}
 ]
};};
N["arc_smith13"]=function(){return{
 sceneTitle:"熔炉之心 · 幕五 · 封炉之前",
 text:[
  "决战前夜，你带着那团火走上地面。它化成一枚暗红的炉心石，嵌在你锤柄的第三道裂痕里——裂痕，被填满了。",
  "会长看见炉心石，沉默了很久：「前代锤主封它，你带它出来了。」",
  "「它认我。」你说，「它是他打铁的那口气。他不是怪物——他是作品。」",
  "会长看着你，忽然笑了：「他死前说，要是有人能把他的作品带出炉底，他这一辈子，就算没白打。」他顿了顿，「你做到了。」",
  "你低头看锤。三道裂痕，一道是铁，一道是铜，一道是暗红的炉心——像三句终于说完的话。铜鸟落在锤柄上，炉心石微微发光，像是那团火，也在看着你。",
  "远处，深渊的气息正在逼近。你握紧锤——这柄锤，现在不只是打铁的锤了。它封过炉，也解过炉；断过路，也开了路。",
  "你转身，走向决战的方向。锤柄上，炉心石的温度，沉稳而滚烫——像一颗跳动的心。"
 ],
 options:[
  {t:"（炉心已明）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
N["arc_knight1"]=function(){return{
 sceneTitle:"誓约之重 · 幕一 · 白袍的誓",
 text:[
  "誓约骑士团的入团仪式，在团礼堂举行。你跪在团徽前，白袍执事宣读誓词：「我，以我之名，立下此誓：守誓如守命，践诺如践土。」",
  "你跟着念完。地板上的纹路，在你膝盖落下的那一瞬，亮了一下——像是一道沉睡了很久的纹路，终于等到了一个新的重量。",
  "白袍执事看了你一眼，眼神微动：「纹路亮了。这是团里十年没有过的事——上一任让它亮的，是伊莎·圣辉。」",
  "「她是谁？」你问。",
  "执事没有回答，只是把一枚银质团徽别在你胸前：「她是谁，你以后会知道。现在——记住你刚念过的誓词。团里每一个人，都死在它的前面或后面。」",
  "你低头看胸前的团徽。银质的纹路，在灯光下，像一道未干的誓约。"
 ],
 options:[
  {t:"（将团徽别在胸前，踏上骑士之路）",go:"arc_knight2"}
 ]
};};
N["arc_knight2"]=function(){return{
 sceneTitle:"誓约之重 · 幕一 · 纹路",
 text:[
  "入团第七天，你在团里的旧档案室，翻到了关于地板纹路的记载：团礼堂的地板，是用初代团长的盾面熔铸的。纹路是盾上的刻痕——每一道，都是一个「守住了誓约」的骑士留下的。",
  "纹路亮了，说明这一任的誓约，与初代团长的那道刻痕，重合了。",
  "你跪的地方，正对着一道最深的刻痕。旁边有一行小字：「伊莎·圣辉，立誓于此。守誓四十七年，无一字破。」",
  "你伸手摸了摸那道刻痕。指尖微烫——像是有什么东西，隔着几十年，隔着一次立誓，在回应你。",
  "你问白袍执事，伊莎·圣辉现在在哪。执事沉默了一下：「她在静养。四十七年的誓约，太重了——她守了四十七年，也把自己磨了四十七年。她的身体，快撑不住了。」"
 ],
 options:[
  {t:"（伸手触摸那道刻痕）",go:"arc_knight3"}
 ]
};};
N["arc_knight3"]=function(){return{
 sceneTitle:"誓约之重 · 幕一 · 第一道刻痕",
 text:[
  "你第一次出任务，是护送一车粮到城外的村落。路上遇到劫匪，你拔剑，念了一遍誓词——「守誓如守命」。剑比你想的快，劫匪退了。",
  "回来复命时，白袍执事让你去礼堂看看。你走进去，发现地板上的纹路，多了一道新的刻痕——很浅，但确实是你跪过的地方长出来的。",
  "「纹路记住了你。」执事说，「你守住了第一道誓约。从今天起，你是团里真正的骑士了。」",
  "你低头看着那道浅痕，心里却没有多少喜悦。你想起护送时，那个劫匪头子看你拔剑时的眼神——不是怕，是一种「又一个」的疲惫。",
  "你忽然明白，誓约的对面，永远是别人的人生。你守住一道誓约，就可能压碎另一个人的选择。",
  "这道念头，像一道浅痕，刻在你心里。"
 ],
 options:[
  {t:"（第一道刻痕已成）誓约之裂",go:"arc_knight4"}
 ]
};};
N["arc_knight4"]=function(){return{
 sceneTitle:"誓约之重 · 幕二 · 誓约之裂",
 text:[
  "团里出了一件事：一位老骑士，在执行任务时，违背了誓约。他没有救下该救的人——他选择了救自己的儿子。",
  "没有人敢提他的名字。白袍执事只说「有人破了誓」，团里一片沉默。你发现，礼堂地板上，有一道刻痕正在变暗——那是那位老骑士当年立誓的地方。",
  "你问白袍执事，破誓的人会怎样。执事说：「团规：破誓者，除名，永不复用。」他顿了顿，「但他救的是他儿子。团规没说，救儿子算不算破誓。」",
  "你沉默。你见过那位老骑士，他守了三十年的誓约，头发都守白了。他跪在礼堂立誓那天，地板上的纹路，亮得刺眼。",
  "而今天，那道刻痕正在变暗。像一道正在熄灭的光。"
 ],
 options:[
  {t:"（去找那位老骑士）",go:"arc_knight5"}
 ]
};};
N["arc_knight5"]=function(){return{
 sceneTitle:"誓约之重 · 幕二 · 两难",
 text:[
  "你去找那位老骑士。他在城外的旧马厩里，收拾行囊。看见你，他没有惊讶：「来问破誓的事？」",
  "「来问你为什么。」你说。",
  "老骑士停下手里的动作，想了很久：「我儿子被人绑了，绑匪要我在'救他'和'救那车人'之间选一个。我选了儿子。」他抬起头，「骑士的誓约，说守誓如守命。可我没法看着儿子的命，从指缝里流走。」",
  "「团规说……」",
  "「团规没说，」老骑士打断你，「救儿子，算不算破誓。也没说，一个守了三十年誓的人，在儿子面前，还算不算骑士。」",
  "他背起行囊：「我走了。别学我，也别学团规——你自己想清楚，誓约到底该是什么。」",
  "他走出马厩。你站在原地，看着他佝偻的背影。你忽然觉得，他肩上卸下的不是团徽，是一道扛了三十年、最后压垮他的誓约。"
 ],
 options:[
  {t:"（目送他离开）",go:"arc_knight6"}
 ]
};};
N["arc_knight6"]=function(){return{
 sceneTitle:"誓约之重 · 幕二 · 一道暗痕",
 text:[
  "老骑士走后，礼堂地板上的那道刻痕，彻底变暗了。但你发现，旁边有一道新的浅痕，正在慢慢浮现——那是你上次立誓的地方。",
  "你跪下去，伸手摸了摸。那道浅痕，像一道没有愈合的伤口。",
  "白袍执事站在你身后：「纹路在选择。老骑士的誓约断了，团里需要一道新的誓约补上——它选中了你。」",
  "「可我还没想清楚，誓约是什么。」你说。",
  "执事看着你：「没人想得清楚才立誓的。都是立了誓，才慢慢想清楚。」他顿了顿，「但你最好想快一点——大陆要乱了，团里的骑士，不够用了。」",
  "你站起来，看着那道浅痕。它还在长，像一棵刚刚破土的苗。"
 ],
 options:[
  {t:"（誓约在长）两难之誓",go:"arc_knight7"}
 ]
};};
N["arc_knight7"]=function(){return{
 sceneTitle:"誓约之重 · 幕三 · 两难之誓",
 text:[
  "你遇到了一道真正的两难：两位骑士，同时向你求助。一个在东边，一个在西边；一个求你救他被困的妹妹，一个求你护他被追杀的师父——而你，只有一个人，一匹马。",
  "白袍执事说：「团规：骑士须守誓。但你立了两道誓约，只够守一道。」他顿了顿，「这就是骑士最老的考题——誓约撞上誓约，你守哪边？」",
  "你站在马厩前，两匹马都在看你。东边的风，西边的雨，都在等你回答。",
  "你忽然想起老骑士的话：「你自己想清楚，誓约到底该是什么。」——誓约不是一条线，是一杆秤。称的，不是「守不守」，是「先守谁」。",
  "你握紧缰绳。你知道，无论你选哪边，都会辜负另一边。但你必须选——因为骑士的誓约，从来不是「不辜负」，是「选了，就扛到底」。"
 ],
 options:[
  {t:"东去，救那位妹妹",go:"arc_knight8"},
  {t:"西行，护那位师父",go:"arc_knight8"}
 ]
};};
N["arc_knight8"]=function(){return{
 sceneTitle:"誓约之重 · 幕三 · 一诺",
 text:[
  "你选了——然后你把另一半承诺，写成一封信，托驿马送给另一位骑士：「我失信于你，但我以这条命担保：办完我的事，立刻回来还你的。」",
  "被你辜负的那位骑士，收到信后沉默了很久。后来他托人带话：「不用还。你守的是人，我守的是你——你的信，也算一道誓约。」",
  "你办完自己的事，赶回时，看见那位骑士站在路口等你。他没有怪你，只说：「你让我想起一个人——伊莎·圣辉。她年轻的时候，也这么干过。」",
  "「她怎么处理的？」你问。",
  "「她也选了一边。」骑士说，「然后她用二十年，把另一边欠的，一点一点还清了。她说：誓约不是一次选完的，是一辈子还的。」",
  "你站在路口，忽然明白：誓约之重，不在「立」，在「还」。"
 ],
 options:[
  {t:"（赶回路口，与他会合）",go:"arc_knight9"}
 ]
};};
N["arc_knight9"]=function(){return{
 sceneTitle:"誓约之重 · 幕三 · 誓约的尺",
 text:[
  "回团复命时，白袍执事交给你一份信，是伊莎·圣辉亲笔写的。信很短：「听说你选了一边，又写信还了另一边。过来一趟——我在静养所等你。」",
  "你去了。静养所很安静，只有一盏灯。伊莎·圣辉坐在灯下，比你想象的瘦，但背挺得笔直。她看着你，说：「你选了一边，还了另一边——你知道你错在哪吗？」",
  "你沉默。她说：「你错在，把自己当成了那杆秤。誓约不是称你守不守得住——是称你有没有想过，那个被你辜负的人，他这一生，也有一道誓约。」",
  "你低头。她继续说：「但你有一件事做对了：你没有躲。你写信，你认账，你打算还。这就比团里一半的骑士强。」",
  "她端起灯：「去吧。等你哪天想明白'誓约不是束缚，是尺'，再来找我。」"
 ],
 options:[
  {t:"（把伊莎的话记进心里）",go:"arc_knight10"}
 ]
};};
N["arc_knight10"]=function(){return{
 sceneTitle:"誓约之重 · 幕四 · 圣辉之暗",
 text:[
  "伊莎·圣辉的旧伤，是在一个雨夜复发的。你赶到静养所时，她躺在床上，脸色苍白，胸口渗着暗色的血——不是刀伤，是誓约的反噬。",
  "白袍执事守在床边，声音发颤：「她守了四十七年誓约，守到最后，誓约变成了她身上的一把锁。每逢动乱，锁就会收紧——她撑了四十七年，撑不住了。」",
  "伊莎·圣辉睁开眼，看见你，笑了一下：「来得正好。」她抬起手，从颈间解下一枚银质团徽，「这是初代团长的团徽。他立誓那天，纹路亮了——和你立誓那天，一样。」",
  "她把团徽放进你手里：「团里总说，誓约是束缚。其实不是——誓约是一把尺。量你这个人，值不值得被信任。我量了自己四十七年……现在，该你量了。」",
  "窗外，雨声很大。你握着那枚团徽，它在你掌心，微微发烫——像一道终于找到接班人的誓约。"
 ],
 options:[
  {t:"（接过那枚团徽）",go:"arc_knight11"}
 ]
};};
N["arc_knight11"]=function(){return{
 sceneTitle:"誓约之重 · 幕四 · 团长之位",
 text:[
  "伊莎·圣辉没有死，但她把团徽交给了你。第二天，全团骑士列队礼堂，白袍执事宣读：「经伊莎·圣辉举荐，此子继任誓约骑士团团长。」",
  "你站在礼堂中央。地板上的纹路，在灯光下齐齐亮起——所有骑士的誓约刻痕，都在应你。你跪下的地方，那道浅痕，已经长成了一道深痕。",
  "你念了一遍入团时的誓词：「守誓如守命，践诺如践土。」——这一次，你念得比上次重。",
  "礼成。骑士们散去。白袍执事留下来，压低声音：「团长。大陆要乱了——团里的骑士，明天要分散到七个城去。你第一个要守的誓约，是别让这面团徽，落到暗蚀会手里。」",
  "你低头看胸前的团徽。它不再只是银质的——伊莎·圣辉的体温，还留在上面。"
 ],
 options:[
  {t:"（在礼堂立下团长之誓）",go:"arc_knight12"}
 ]
};};
N["arc_knight12"]=function(){return{
 sceneTitle:"誓约之重 · 幕四 · 守旗",
 text:[
  "你成为团长后的第一场硬仗，是守一座桥。暗蚀会的人想渡河，桥那头是三个村子的老弱。你带着十二名骑士，守了三天三夜。",
  "第三天夜里，你的剑断了。你从桥边拔起一根烧焦的梁木，横在身前。对面的暗蚀会首领隔着火喊：「骑士！你拿根木头，守什么？」",
  "「守我立过的誓。」你说。",
  "那一夜，没有人过桥。天亮时，援军到了。暗蚀会退了。你站在桥头，梁木还横在身前——你低头，发现桥头的石板上，不知道什么时候，多了一道浅浅的刻痕。",
  "不是你刻的。是誓约，自己长的。",
  "你伸手摸了摸那道刻痕。它很浅，但你知道，它会慢慢变深——只要你继续守。"
 ],
 options:[
  {t:"（守住这座桥，直到天亮）",go:"arc_knight13"}
 ]
};};
N["arc_knight13"]=function(){return{
 sceneTitle:"誓约之重 · 幕五 · 剑与誓",
 text:[
  "决战前夜，你去看伊莎·圣辉。她靠坐在窗边，看着窗外，听见你的脚步，没有回头：「团长来了。」",
  "「来了。」你走到她身边，把那枚团徽放在她手上，「这是你的。你守了四十七年，该歇了。」",
  "伊莎·圣辉看着团徽，沉默了很久：「四十七年前，我立誓的时候，纹路亮了。我当时以为，那是一道光——后来才知道，那是一把尺。」她抬头看你，「你量过自己了吗？」",
  "你沉默了一会儿，说：「量过。我守过桥，负过人，也还过债。我不知道自己够不够格，但我知道——这杆尺，我拿得起，也放得下。」",
  "伊莎·圣辉笑了。她把团徽推回给你：「那就拿着。誓约不是锁——是你自己给自己立的规矩。规矩在，路就在。」",
  "你接过团徽。窗外，天将亮。你把团徽别在胸前，转身走向决战的方向。",
  "身后，伊莎·圣辉的声音很轻：「去吧。守你的誓。」"
 ],
 options:[
  {t:"（带着誓约之尺）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
/* ===== /v55inj:arcB ===== */
/* ===== v55inj:arcC 职业命运弧 C（游侠/盗贼/商人） ===== */
N["arc_ranger1"]=function(){return{
 sceneTitle:"荒野之声 · 幕一 · 断弦",
 text:[
  "荒野巡守的营地里，挂着一张旧弓。弓身是紫杉木的，弦却断了，断口烧焦——像是被什么东西，一把扯断的。",
  "你问巡守队长，这张弓是谁的。队长叼着草茎，看了那弓一眼：「上一任巡守的。他追一个东西，追了三个月，追到断弦。后来他把自己也追丢了。」",
  "「追什么？」你问。",
  "队长没有回答。他把那根断弦从弓上解下来，递给你：「你要想当巡守，先拿这个。断弦在哪断的，你把它接回去——接上了，你就是巡守；接不上，你回去种地。」",
  "你接过那根断弦。弦很旧，很涩，断口整齐得像被剪断的。你把弦凑近鼻子闻了闻——有一股很淡的、像松脂又像兽血的味道。",
  "你抬头看队长。他已经走了，背影消失在营地的树影里。"
 ],
 options:[
  {t:"（接下那根断弦）",go:"arc_ranger2"}
 ]
};};
N["arc_ranger2"]=function(){return{
 sceneTitle:"荒野之声 · 幕一 · 接弦",
 text:[
  "你花了一天一夜，才把那根断弦接回去。弦是兽筋绞的，断了就卷，你把它泡软，拆成股，再一股一股重新绞紧。",
  "接好弦，你试着拉满。弓弦发出一声低沉的嗡鸣——不是新弦的脆响，是旧弦认主的声音，像一只睡了很久的兽，被你唤醒了。",
  "你忽然感觉到，弓弦上有一种残留的「情绪」——不是你的，是上一任巡守留下的：一种很深的、没追完的遗憾。",
  "你握着弓，站在营地的暮色里。远处的林子里，有什么东西在看着你——你看不见，但你知道它在。",
  "你把弓放下，轻声说：「弦我接上了。你要是还想要个说法——等着，我去追。」"
 ],
 options:[
  {t:"（把弦绞紧，试一试弓）",go:"arc_ranger3"}
 ]
};};
N["arc_ranger3"]=function(){return{
 sceneTitle:"荒野之声 · 幕一 · 巡守的规矩",
 text:[
  "队长验过你的弓，点点头：「弦接得不错。但巡守的规矩，得先跟你说明白。」",
  "「第一，巡守护的是荒野，不是人。荒野要什么，你让它要；人要从荒野拿走什么，你得看它合不合规矩。」",
  "「第二，巡守追东西，追到了，是本事；追不到，是命。但你不能停——你停了，那东西就记住了你的味道，下次见面，它先动手。」",
  "「第三。」队长顿了顿，「上一任巡守追丢的那个东西，你要是遇上了——别逞强。它是这林子里最老的东西，比咱们巡守的历史还老。」",
  "你握着接好的弓，问：「它长什么样？」",
  "队长想了想，说：「没人见过它的全貌。有人说是鹿，有人说是熊，还有人说是棵会走的树。上一任巡守只说了一句——他说，它走起路来，林子是安静的。」",
  "你记住这句话。当天夜里，你第一次听见，林子深处，传来一阵极轻的、像走路一样的声响——然后，整片林子，安静了。"
 ],
 options:[
  {t:"（把巡守的规矩记下）",go:"arc_ranger4"}
 ]
};};
N["arc_ranger4"]=function(){return{
 sceneTitle:"荒野之声 · 幕二 · 林子的安静",
 text:[
  "巡守第三个月，你第一次真正「遇见」它。那是一个清晨，你追踪一头伤鹿进林子深处，忽然发现——鹿不见了，脚印断了，整片林子，安静得像一幅画。",
  "你站在原地，汗毛竖了起来。你想起队长的话：「它走起路来，林子是安静的。」",
  "你慢慢转身。身后十步远，站着一头鹿——不是普通的鹿，它的角上，长着一棵小小的、开花的树。树花是白色的，在晨光里，微微发亮。",
  "它看着你。你看着它。你们之间，隔着十步的安静。",
  "你握着弓，没有举起来。你想起上一任巡守追了它三个月——而你忽然明白，他追的也许不是它，是「它为什么安静」这件事。",
  "那鹿转身，走进林子。它走路的姿态很轻，像是踩在云上。它消失的方向，你记住了——那是北边，林子的最深处。"
 ],
 options:[
  {t:"（目送那头鹿走进林子）",go:"arc_ranger5"}
 ]
};};
N["arc_ranger5"]=function(){return{
 sceneTitle:"荒野之声 · 幕二 · 角上的树",
 text:[
  "你回到营地，画下那棵角上开花的树。队长看了很久，脸色变了：「它让你看见了？」",
  "「它没躲。」你说。",
  "队长把画收起来，压低声音：「那头鹿，是荒野的'守印'。它角上的树，是林子的年轮——树开一次花，荒野换一个甲子。它让你看见，说明它认定你是'看印人'。」",
  "「看印人？」",
  "「巡守里的老话：林子需要一个看着它的人。」队长说，「上一任巡守，追了它三个月，不是要杀它——是想让它承认他是看印人。它没承认。他把自己追丢了。」",
  "你沉默。队长看着你：「它让你看见了角上的树。你知道这意味着什么吗？——它选了你。」",
  "「它选我做什么？」",
  "「守着。」队长说，「守着这林子的安静。不让不该进来的东西，把安静踩碎。」"
 ],
 options:[
  {t:"（把画收好）",go:"arc_ranger6"}
 ]
};};
N["arc_ranger6"]=function(){return{
 sceneTitle:"荒野之声 · 幕二 · 守印人",
 text:[
  "从那以后，你巡守的范围，不知不觉地往北边林子的深处偏。每次你走到那片安静的边缘，都能感觉到——那鹿就在里面，看着你。",
  "有一天，你在林子里发现了一串脚印。不是野兽的——是人靴的，很深，很急，像是逃命的人留下的。脚印的尽头，是一棵被劈开的树，树心里，钉着一枚黑色的骨钉。",
  "你拔下骨钉。钉子上刻着细密的纹路——是暗蚀会的印记。你忽然明白了：有人想动这片林子，用骨钉钉树，是在「放血」——把林子的生气，一点一点放干。",
  "你握着骨钉，指节发白。你想起那头鹿角上的树——树开一次花，荒野换一个甲子。有人要把它钉死在这个甲子里。",
  "你把骨钉收进怀里，走向营地。今晚，你得告诉队长：这片林子，有人要动它了。"
 ],
 options:[
  {t:"（握着骨钉回营地）",go:"arc_ranger7"}
 ]
};};
N["arc_ranger7"]=function(){return{
 sceneTitle:"荒野之声 · 幕三 · 放血的人",
 text:[
  "你顺着脚印，追了三天，追到了放血的人——一个穿黑袍的暗蚀会术士，正在林子里埋第二枚骨钉。",
  "他没有跑。他看见你，甚至笑了笑：「巡守？来得正好。你帮我看看——这棵树，钉哪儿出血最快？」",
  "你拔出箭。他没有躲，反而摊开手：「你射我，我死了，还会有别人来钉。这片林子，挡了暗蚀会十年的路——它太安静了，安静到我们都忘了，它下面埋着什么。」",
  "「埋着什么？」你问。",
  "术士没有回答。他把第二枚骨钉钉进树根，然后看着你：「你猜，上一任巡守为什么追了三个月？他不是追那头鹿——他是追这个秘密。他追到了，然后他把它带进了土里。」",
  "他转身消失在林子里。你站在原地，看着那棵被钉了骨钉的树。树皮在骨钉周围，正慢慢变灰——像一片正在干涸的河床。"
 ],
 options:[
  {t:"（追入林子深处）",go:"arc_ranger8"}
 ]
};};
N["arc_ranger8"]=function(){return{
 sceneTitle:"荒野之声 · 幕三 · 地下的秘密",
 text:[
  "你花了五天，挖开了那棵被钉的树根。根须深处，你挖到一块石板。石板是青石的，上面刻着一幅地图——不是地表的地图，是地下的：一条条根须般的隧道，交汇在一个圆点。",
  "圆点旁边，刻着四个字：「旧印之地」。",
  "你想起那头鹿角上的树。树开一次花，荒野换一个甲子——如果地下埋着一枚「旧印」，那这片林子，就是守着旧印的皮囊。暗蚀会要的，从来不是这片林子的安静——是它地下的那枚印。",
  "你把石板重新埋好。走出林子时，天已经黑了。你在林边站了很久，忽然感觉到一阵极轻的脚步声——你回头，那头鹿站在林缘的阴影里，角上的树，在夜色里微微发光。",
  "它看着你。你忽然明白了它为什么选你看印：上一任巡守追到了秘密，把它带进了土里——它不想再等一个把秘密带进土里的人。",
  "你轻声说：「我不带进土里。我把它带出去，带完。」"
 ],
 options:[
  {t:"（把石板重新埋好）",go:"arc_ranger9"}
 ]
};};
N["arc_ranger9"]=function(){return{
 sceneTitle:"荒野之声 · 幕三 · 安安静静的选择",
 text:[
  "你有两条路。一条，是把这个秘密上报巡守营——营地会封锁林子，暗蚀会暂时进不来，但「旧印之地」的存在，会引来更多人争夺。",
  "另一条，是瞒下来，你自己守——守到暗蚀会再来，守到你一个人挡不住为止。上一任巡守，选的就是这条路。",
  "你坐在林缘的石头边，弓放在膝上，想了很久。林子里，风很轻，树在说话。",
  "你忽然想起那头鹿走路的样子——它走起来，林子是安静的。安静，不是没有动静——是有东西在守着，让该静的静下来。",
  "你站起来，把弓背上：「上报。」你说，「我一个人守不住安静。但巡守营加在一起，能。」",
  "你走向营地的方向。身后，林子里，传来一声极轻的、像应答一样的鹿鸣。"
 ],
 options:[
  {t:"（走向营地，上报此事）",go:"arc_ranger10"}
 ]
};};
N["arc_ranger10"]=function(){return{
 sceneTitle:"荒野之声 · 幕四 · 旧印之地",
 text:[
  "巡守营封锁林子的第七天，暗蚀会来了。不是小股术士——是一支队伍，带着铁锹和黑旗，像一队来「收租」的人。",
  "他们没强攻。他们在林外扎营，开始日夜不休地砍树——不是要伐木，是要「惊」出林子的反应。他们知道，旧印之地有守护，守护一定会在某个地方，露出破绽。",
  "第七夜，那头鹿出现了。它站在林缘，角上的树，白花正在一片一片地落——不是凋谢，是「换甲子」的征兆。树开花一次，换一个甲子；花开尽了，旧印就会暴露。",
  "队长看着那头鹿，说：「它撑不住了。旧印要见光了——暗蚀会等的就是这个。」",
  "你握着弓，站在鹿和暗蚀会之间。风停了，整片林子，安静得像一幅画。你知道，接下来，会有一场你守不住太久的仗。"
 ],
 options:[
  {t:"（站在林缘，拉满弓）",go:"arc_ranger11"}
 ]
};};
N["arc_ranger11"]=function(){return{
 sceneTitle:"荒野之声 · 幕四 · 一箭",
 text:[
  "暗蚀会开始动手时，你做了唯一能做的事——你站出来，站在林子前面，拉开了弓。",
  "你没有瞄准任何人。你瞄准的是林子上方的一根枯枝——箭离弦，枯枝断落，砸在地上，扬起一片尘土。这是巡守的规矩：先警告，再动手。",
  "暗蚀会的领队停下，隔着尘土看着你：「巡守？一个人？」",
  "「一个人，一张弓，一片林子。」你说，「够吗？」",
  "他没有回答。他挥手，队伍继续往前。你拉开第二箭——这一次，箭钉在他脚前三寸的土里。",
  "「旧印之地，不进。」你说，「进，我这一箭，就不是钉土里了。」",
  "领队看了你很久。他身后的队伍停下来。半晌，他笑了：「有意思。一个巡守，想用一张弓，挡一支队伍。」他退后一步，「那我不进。我等你——等你的箭，用完的那天。」",
  "队伍退了。你站在原地，握着弓，手指在发抖。你忽然明白，他等的不是你的箭用完——是他知道你背后那片林子，撑不了多久了。"
 ],
 options:[
  {t:"（守住这一箭的承诺）",go:"arc_ranger12"}
 ]
};};
N["arc_ranger12"]=function(){return{
 sceneTitle:"荒野之声 · 幕四 · 花开尽时",
 text:[
  "那头鹿，在第七天的夜里，角上的白花落尽了。花落尽的那一刻，林子的深处，传来一声很沉的、像心跳一样的震动——旧印之地，开始苏醒。",
  "你站在林缘，听见那声震动，心里反而平静了。你走到鹿身边，它没有躲。你伸手，轻轻摸了摸它角上光秃的树枝。",
  "「花开尽了。」你说，「旧印要见光了。我守到这儿，守不住了。」",
  "鹿没有说话。但它低下头，用角轻轻碰了碰你的弓。",
  "你忽然明白了——旧印见光，不是末日。是它该换个地方藏了。而「看印人」的职责，不是守着印不动，是看着印，在它该动的时候，动起来。",
  "你抬头看天。月亮正升起来。你把弓背好，轻声说：「那就，带它走。」",
  "鹿抬起头。它的眼睛里，映着月光，像一汪安静的泉。"
 ],
 options:[
  {t:"（带着它，启程）",go:"arc_ranger13"}
 ]
};};
N["arc_ranger13"]=function(){return{
 sceneTitle:"荒野之声 · 幕五 · 带着安静走",
 text:[
  "决战前夜，你带着那头鹿，穿过巡守营的封锁线，走向大陆深处。鹿角上的树枝，在月光下，正抽出一枚极小的新芽。",
  "队长在营门口送你。他看了那鹿一眼，又看你：「你要带它去哪？」",
  "「带它去找一个，暗蚀会够不着的地方。」你说。",
  "队长沉默了一会儿：「上一任巡守，没做到的事，你做到了——你没把秘密带进土里，你把它带上了路。」他解下自己的弓，递给你，「拿着。荒野的巡守，从今天起，你是头一个带着「守印」走的。」",
  "你接过弓。鹿在夜色里，静静地站着，像一枚活着的印章。",
  "你转身，走进夜色。身后，整片林子，安静得像一幅画——但你知道，那安静，是活的。它跟着你，走在路上。",
  "你轻声说：「走吧。我们去找下一个甲子。」"
 ],
 options:[
  {t:"（带着荒野之声）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
N["arc_thief1"]=function(){return{
 sceneTitle:"暗影法则 · 幕一 · 三根手指",
 text:[
  "暗影阁的入门考试，是偷一样东西。不是金器，不是文书——是阁主办公桌上，一枚压着一摞纸的镇纸。",
  "镇纸是铜的，很重，放在桌角，正对着门口。你隔着窗看了一下午，想了一百种办法，最后发现：门没锁。",
  "你走进去，拿起镇纸。走出门时，你回头看了一眼——桌上那摞纸，被风吹开了一页。你看见一行字：「偷东西不难。难的是，偷完了，还得让人觉得，你没来过。」",
  "你把镇纸放回原处，空着手走出来。阁主站在走廊尽头，看着你，笑了：「聪明。知道自己偷不走，就把'偷'字咽回去——这一手，够进暗影阁了。」",
  "你被录用了。入职第一天，阁主丢给你一枚铜牌，上面刻着三根手指：「记住。暗影阁的规矩，只有三条——手要快，心要慢，债要还。」"
 ],
 options:[
  {t:"（收下那枚铜牌）",go:"arc_thief2"}
 ]
};};
N["arc_thief2"]=function(){return{
 sceneTitle:"暗影法则 · 幕一 · 快与慢",
 text:[
  "你在暗影阁学的第一课，不是偷，是「看」。阁主让你坐在市集口，看一整天——看人怎么走路，怎么掏钱，怎么看摊，怎么回头。",
  "一天下来，你看出一个规律：人掏钱的时候，眼睛会往边上瞟一眼；人回头的时候，脚尖会先转。这些细微的动作，是人的「门」——你看见门，就能进去。",
  "第二天，阁主让你偷一个钱袋。你用了十秒钟——你看见那人掏钱时的眼神，等他放下警惕，你从他腰侧顺走了钱袋。",
  "晚上交差，阁主掂着钱袋：「快。但还不够。」他指着钱袋的系绳，「你系回去的结，和人家的不一样。偷要快，但善后要慢——慢到像你从没碰过它。」",
  "你看着那根系绳。你忽然明白，暗影阁教的不是手，是「手和心之间的那道缝」——快是手，慢是心。"
 ],
 options:[
  {t:"（按阁主教的方法，再练一遍）",go:"arc_thief3"}
 ]
};};
N["arc_thief3"]=function(){return{
 sceneTitle:"暗影法则 · 幕一 · 三根手指的来历",
 text:[
  "你在暗影阁的档案里，查到那枚铜牌的来历：暗影阁第一任阁主，是个偷儿，靠三根手指偷遍了一座城。后来他金盆洗手，创立暗影阁，立下三条规矩——手要快，心要慢，债要还。",
  "「债要还」那条，是后来加上的。档案里说：第一任阁主晚年，把当年偷过的东西，一样一样还了回去。还到最后一样时，他死了——那东西的主人，已经死了二十年。",
  "他在那家人门口，放下一袋钱，和一封信。信上只有一句话：「还您的。迟了二十年，对不住。」",
  "你合上档案。你忽然明白，「债要还」不是一句漂亮话——是第一任阁主用命做的示范：偷来的，都得还。不是还东西，是还「心安」。",
  "你低头看铜牌上的三根手指。它现在，不只是规矩了。"
 ],
 options:[
  {t:"（把铜牌收好）",go:"arc_thief4"}
 ]
};};
N["arc_thief4"]=function(){return{
 sceneTitle:"暗影法则 · 幕二 · 一件不该偷的东西",
 text:[
  "阁主给你的第二件差事，是偷一枚印章。目标是一户商人家里的私印——阁主说，那枚印，关系着一批「不该进城的货」。",
  "你踩点三天，摸清了商人的作息。第三夜，你翻进书房，在暗格里找到那枚印。你正要走，忽然看见印旁边压着一封信——你顺手拍了一眼。",
  "信上写的是：那批货，是给城外孤儿院的冬粮。商人刻了私印，是为了给孤儿院「走私」粮食——因为官府的税，把粮食卡在城外了。",
  "你握着那枚印，站在书房里，忽然觉得它沉了。你偷它，是替暗影阁办事；但它的主人用它，是替一群孩子办事。",
  "你最终没有把印交上去。你把它放回暗格，只带走了印旁一张空白的纸。第二天，阁主看着那张纸，沉默了很久。"
 ],
 options:[
  {t:"（把印放回暗格）",go:"arc_thief5"}
 ]
};};
N["arc_thief5"]=function(){return{
 sceneTitle:"暗影法则 · 幕二 · 黑与白",
 text:[
  "阁主没有骂你。他把那张空白的纸压在桌上，问：「你知道你错在哪吗？」",
  "「我没偷成。」你说。",
  "「错。」阁主说，「你错在，想分清黑和白。暗影阁的差事，从来不分黑和白——只分'该拿'和'不该拿'。你拿不准，就别拿，这是规矩。」他顿了顿，「但你做对了一件事：你回来交差了，没把'没偷成'瞒成'偷到了'。」",
  "你沉默。阁主继续说：「那批粮的事，我已经查过了——商人私运粮食，确实是给孤儿院的。但暗蚀会的人，也盯上那批粮了。他们要的不是粮，是那个商人的把柄。」",
  "「那我该怎么做？」你问。",
  "阁主看着你：「你偷到的那张纸，现在有了新用处——你要把那批粮，变成暗蚀会碰不得的东西。这是暗影的活儿：不是偷，是'藏'。」",
  "你忽然明白：暗影阁的「偷」，有时候是「藏」。把不该被看见的东西，藏进看不见的地方。"
 ],
 options:[
  {t:"（按阁主的说法去做）",go:"arc_thief6"}
 ]
};};
N["arc_thief6"]=function(){return{
 sceneTitle:"暗影法则 · 幕二 · 藏",
 text:[
  "你花了三个晚上，把那批粮「藏」了。你改了粮车的路线标记，换了码头收货人的名字，最后在粮袋上，压了一枚你连夜仿刻的——商会总会的火漆印。",
  "暗蚀会的人来查时，粮车已经运进城，盖着总会的印，动不得。他们只能看着粮食进了孤儿院，气得跺脚。",
  "你在暗处看着那队人离开。你忽然觉得，这一次，「偷」字换了味道——你没有拿走任何东西，但你让一件好东西，避开了坏事。",
  "回阁复命时，阁主难得地给你倒了杯茶：「藏得好。暗影阁的活，偷东西只是入门——藏东西，才是本事。」",
  "你喝了一口茶。茶是苦的，但你知道，这是你在暗影阁喝到的第一杯「敬」的茶。"
 ],
 options:[
  {t:"（回阁复命）",go:"arc_thief7"}
 ]
};};
N["arc_thief7"]=function(){return{
 sceneTitle:"暗影法则 · 幕三 · 一条人命",
 text:[
  "暗影阁接到一单活：从城里「请」出一个人——一个知道太多秘密的账房先生。出价很高，高到阁主犹豫了很久。",
  "「请」是暗影阁的黑话。你问阁主：「请出来，然后呢？」",
  "阁主没有回答。但你知道，「请」的分量——请出来的，未必回得去。",
  "你接下这单活，不是因为钱。是因为你认识那个账房先生——他是孤儿院的常客，每个月，都拿自己的俸禄，给孩子们买纸笔。",
  "你踩点那晚，在账房先生家门口，看见他正在给一个孩子擦脸。他笑得很累，但很真。你蹲在屋檐上，忽然觉得，暗影阁的规矩，在这一刻，裂开了一道缝。",
  "「手要快，心要慢，债要还。」——你念了一遍规矩，然后把「请」字，换成了「藏」字。"
 ],
 options:[
  {t:"（蹲在屋檐上，做下决定）",go:"arc_thief8"}
 ]
};};
N["arc_thief8"]=function(){return{
 sceneTitle:"暗影法则 · 幕三 · 藏在影子里的选择",
 text:[
  "你没有「请」出那个账房先生。你「请」出的是他写的一本账——不是他的命，是他知道的那些秘密。你把账本藏进了孤儿院的地窖，然后把一枚伪造的「死亡」痕迹，留在了账房先生的门口。",
  "第二天，暗蚀会的人来收账。他们看见门口的痕迹，以为账房先生死了，线索断了，骂骂咧咧地走了。",
  "账房先生活了下来。他不知道是你做的。他在孤儿院门口，站了很久，看着那袋他以为「失而复得」的纸笔，擦了擦眼睛。",
  "你蹲在远处的屋檐上，看着这一幕。你手里的铜牌，三根手指，在月光下微微发亮。",
  "你轻声说：「债，我先欠着。总有一天，我会还。」",
  "这一夜，你第一次觉得，暗影阁的「暗」，也可以是一种「护」。"
 ],
 options:[
  {t:"（把账本藏进地窖）",go:"arc_thief9"}
 ]
};};
N["arc_thief9"]=function(){return{
 sceneTitle:"暗影法则 · 幕三 · 阁主的考问",
 text:[
  "阁主知道你没按规矩办。他没有罚你，只把你叫到阁里，关上门，问：「你欠了暗影阁一笔债——你打算怎么还？」",
  "「还债的方式有很多种。」你说，「我偷过东西，藏过东西，现在我想试试——还东西。」",
  "阁主盯着你，看了很久：「你知道暗影阁为什么立'债要还'这条规矩吗？不是要你还给阁里——是要你还给你偷过的人。」",
  "你沉默。阁主继续说：「第一任阁主还了一辈子，还到死。你还得起吗？」",
  "「还不起。」你说，「但我可以开始还。」",
  "阁主看了你很久，忽然笑了。他摘下自己的铜牌，丢给你：「那就从还暗影阁的债开始——从今天起，你是阁里的'影子'了。影子不偷东西。影子替人挡东西。」",
  "你接住铜牌。牌上的三根手指，在灯下，像三根立着的誓。"
 ],
 options:[
  {t:"（接过阁主的铜牌）",go:"arc_thief10"}
 ]
};};
N["arc_thief10"]=function(){return{
 sceneTitle:"暗影法则 · 幕四 · 影子",
 text:[
  "「影子」的差事，是替人挡东西——挡刀、挡暗箭、挡那些「不该让某人看见的事」。你接的第一单，是替城主府挡一件丑闻：有人要刺杀城主，嫁祸给孤儿院。",
  "你在城主的必经之路上，守了三天。第三夜，刺客来了。你没有惊动任何人——你在他出手前一瞬，把他「请」走了。",
  "你把他捆在废弃的塔楼里，问：「谁雇的你？」",
  "他吐了一口血沫：「暗蚀会。他们要把孤儿院打成'藏污纳垢'的地方——好名正言顺地，把那片地收走。」",
  "你握着刀，站在塔楼的风里。你忽然明白：有些「影子」，不是帮人躲坏事——是让好事，不被坏事吞掉。",
  "你放开刺客，让他走。他走之前，回头看你：「你放了我，暗蚀会会记住你。」",
  "「让他们记。」你说，「影子，本来就该待在暗处。」"
 ],
 options:[
  {t:"（放开刺客，让他走）",go:"arc_thief11"}
 ]
};};
N["arc_thief11"]=function(){return{
 sceneTitle:"暗影法则 · 幕四 · 欠债的名单",
 text:[
  "你把账房先生的那本账，从孤儿院地窖里取了出来。账上记的，不只是秘密——还记着这些年，谁欠过谁，谁帮过谁。",
  "你翻到最后一页。账房先生在页尾写了一行小字：「我这条命，不知道是谁救的。但我知道，救我的那个人，一定是个'欠了债想还'的人。」",
  "你握着那本账，站在夜色里。你把账本收进怀里——这不是秘密，这是一份「还债清单」。",
  "暗蚀会的线索，账房先生的恩情，孤儿院的孩子，还有阁主的三根手指……你欠的债，列满了半页纸。你忽然觉得，这一路偷来的、藏来的，都变成了「欠」。",
  "你把账本贴身放好，轻声说：「欠的，我记着。还的，我一样一样来。」",
  "远处，城的灯火在夜色里亮着。你走进影子，走向下一笔债。"
 ],
 options:[
  {t:"（把账本贴身放好）",go:"arc_thief12"}
 ]
};};
N["arc_thief12"]=function(){return{
 sceneTitle:"暗影法则 · 幕四 · 一账还一债",
 text:[
  "你开始还债。第一笔，还给孤儿院——你替他们找到了一处更安全的地方，躲开暗蚀会的眼线。第二笔，还给账房先生——你在他门口，放下一袋钱，和一张字条：「您的账，我替您收好了。您安心过日子。」",
  "第三笔，你还没想好还谁。但阁主找到你，递给你一封信：「暗蚀会的人，盯上你了。他们查到你放走了刺客——你欠他们的债，也该还了。」",
  "「他们要我拿什么还？」你问。",
  "阁主看着你：「他们要你——拿孤儿院的地契还。」他顿了顿，「这就是暗蚀会的规矩：你欠他们的，他们不要命，要你手里的「好人」。」",
  "你握着那封信，指节发白。你忽然明白，暗蚀会的「债」，和暗影阁的「债」，是两回事——一个要你还心安，一个要你拿别人来还。",
  "你把信折起来，收进怀里：「那这笔债，我不还。」",
  "阁主看着你，没有劝。他只是说：「那就做好准备——影子，要开始跑夜路了。」"
 ],
 options:[
  {t:"（准备好跑夜路）",go:"arc_thief13"}
 ]
};};
N["arc_thief13"]=function(){return{
 sceneTitle:"暗影法则 · 幕五 · 影子的路",
 text:[
  "决战前夜，你在孤儿院的地窖里，把那本账和地契放在一起，用油纸包好，藏进最深处。你拍拍手上的土，站起身。",
  "阁主站在地窖口：「藏好了？」",
  "「藏好了。」你说，「这笔债，我不还暗蚀会——我留着，等打赢了，亲手还。」",
  "阁主没有笑。他看着你，说：「暗影阁的规矩，三条：手要快，心要慢，债要还。你学得快，藏得慢，现在——该你教教我了：'债要还'，到底是什么意思？」",
  "你想了想，说：「债要还，不是还东西。是还'心安'——把偷来的、藏来的、欠来的，都还成心安。心安了，影子才能站到光底下，不觉得刺眼。」",
  "阁主沉默了很久。他摘下自己的铜牌，放进你手里：「从今天起，你是暗影阁的阁主。规矩，你带着——牌，也带着。」",
  "你握着那枚旧铜牌。三根手指，在月光下，像三根立着的誓。你把它别在腰间，走进夜色。",
  "身后，孤儿院的灯，还亮着。"
 ],
 options:[
  {t:"（带着暗影法则）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
N["arc_trade1"]=function(){return{
 sceneTitle:"天平两端 · 幕一 · 一杆秤",
 text:[
  "金衡商会的入会礼，是一杆秤。秤是铜的，很小，可以握在手里。秤杆上刻着两行字：「秤平，则天下平；秤斜，则人心斜。」",
  "会长把秤交给你时，说：「商会的规矩，只一条：秤要平。东西可以贵，可以贱，但不能骗——秤斜一次，你这一生，就斜了。」",
  "你接过秤。它比看上去轻，但握着它，你的手心微微出汗——你知道，这杆秤，从今天起，会跟着你走很久。",
  "「秤平，则天下平。」你念了一遍。会长笑了：「念一遍不够。等你用一辈子，把它念完。」",
  "你把这杆秤收进怀里。当天晚上，你在梦里，看见一杆巨大的秤，悬在天空上——一端放着大陆，一端放着一枚金币。"
 ],
 options:[
  {t:"（把那杆秤收进怀里）",go:"arc_trade2"}
 ]
};};
N["arc_trade2"]=function(){return{
 sceneTitle:"天平两端 · 幕一 · 第一笔生意",
 text:[
  "你入会后的第一笔生意，是在集市上卖一袋盐。进货价三文，你卖五文——这是行价，不亏不赚，公道。",
  "一个老妇人买了半斤，掏钱时，掉出一枚铜钱，滚到你脚边。你弯腰捡起来，还给她。她愣了一下，笑了：「现在的年轻人，肯弯腰捡钱还人的，少了。」",
  "晚上交账，会长看着你的账本：「你这笔生意，赚了三文。」",
  "「赚了三文？」你皱眉，「行价五文，进货三文，该赚两文。」",
  "会长把账本推回来：「你捡钱还人的那一下，值一文。」他说，「商会的秤，不只称东西——也称人。你弯腰的那一下，秤往你这边，斜了一厘。」",
  "你看着账本上那多出来的一文，忽然明白：商会的生意，不是称斤两，是称人心。"
 ],
 options:[
  {t:"（把账本合上）",go:"arc_trade3"}
 ]
};};
N["arc_trade3"]=function(){return{
 sceneTitle:"天平两端 · 幕一 · 秤杆的旧痕",
 text:[
  "你把那杆秤拿出来擦时，发现秤杆的内侧，有一道很细的旧痕——不是磨损，是刻上去的。你对着光看了半天，认出那是三个字：「文森·金秤」。",
  "你问会长，文森·金秤是谁。会长正擦着柜台，手停了一下：「商会的传奇商人。他年轻时，用一杆秤，称平过一场战争。」",
  "「称平战争？」",
  "「两国打仗，打到最后，粮断了。他运了三船粮去，卖给出价高的那一方——另一方气不过，要杀他。他说：'你杀我，粮就没了。不如你出价，我把粮卖给你一半。'」会长说，「他两头卖粮，两头都不欠。战争停了，他成了传说。」",
  "「这不算……奸商吗？」你问。",
  "会长看了你一眼：「他两头都卖，两头都明码标价，两头都保住了粮。战场的兵没饿死，你管这叫奸商？」他顿了顿，「秤平，则天下平——他是真信这句话的。」",
  "你低头看秤杆上的旧痕。文森·金秤——你记住了这个名字。"
 ],
 options:[
  {t:"（记下这个名字）",go:"arc_trade4"}
 ]
};};
N["arc_trade4"]=function(){return{
 sceneTitle:"天平两端 · 幕二 · 一袋发霉的粮",
 text:[
  "商会接了一单大生意：往北境运三千石粮。你负责押运前队，到了交货地，你验货时发现——粮袋底层的米，发了霉。",
  "收粮的是北境守军，急等这批粮。你站在粮车前，手里捏着一把发霉的米，心里算了一笔账：现在退粮，守军断粮，商会赔钱，北境可能退守；不吭声，粮进了营，守军吃了发霉的米，非战斗减员——仗，还是打不赢。",
  "你最后把粮车拦住了。你当着收粮官的面，拆开底层的麻袋，露出发霉的米。收粮官的脸，一下子白了。",
  "「这批粮，我不能收。」你说，「但我马上补一批新粮来——商会出的钱，算我欠商会的。」",
  "收粮官看着你，半天没说话。最后他说：「你拦这批粮，拦得好。但你欠商会的这笔钱，够你打十年工。」",
  "「十年就十年。」你说，「秤斜一次，一辈子就斜了。十年，买个不斜，值。」"
 ],
 options:[
  {t:"（拦下这批粮）",go:"arc_trade5"}
 ]
};};
N["arc_trade5"]=function(){return{
 sceneTitle:"天平两端 · 幕二 · 秤斜一次",
 text:[
  "你欠商会的那笔钱，压得你喘不过气。会长没有催你，但他把你的月俸扣了一半，记账：「粮钱，欠款中。」",
  "你开始接更多的活——跑商、押运、记账，什么活都接。你每天记账，账本上的欠款，像一座小山。",
  "有一天夜里，你在账房算账，算到一半，忽然停下来。你发现，商会最近的几笔大生意，账目平得「太好」了——好到每一笔，都刚好压在行价的边缘上，一分不差。",
  "你翻出旧账对比，发现这些「正好」的生意，全都指向同一个方向：北境。有人在用商会的手，往北境输送「正好」的物资——不多不少，刚好够用，刚好不引人注意。",
  "你合上账本，坐在黑暗里。你忽然明白，文森·金秤那杆秤，秤的不只是战争——秤的，是有人在暗处，把「平」这件事，做成了生意。"
 ],
 options:[
  {t:"（合上账本）",go:"arc_trade6"}
 ]
};};
N["arc_trade6"]=function(){return{
 sceneTitle:"天平两端 · 幕二 · 正好",
 text:[
  "你顺着账本往下查。查到最后，线索指向一个人——会长的私人账房，一个几乎不出门的老人。他管着商会最机密的账。",
  "你没有声张。你只是在一次送账时，多留了一会儿，翻了翻他桌上的残稿。残稿上写着一行字：「北境十四城，粮价维持在'饿不死、也囤不起'的线上。商路通，则线平。」",
  "你放下残稿，手指有些凉。你忽然明白：北境的粮价，是被人为「秤平」的——不是做生意，是在维持一种脆弱的平衡：让北境正好撑得住，又正好没有余力去打别人。",
  "这是文森·金秤留下的「秤」？还是有人，把他的秤，用在了别的地方？",
  "你回到自己的账房，把那杆铜秤放在桌上。秤杆上「文森·金秤」的旧痕，在灯下，像一道沉默的注视。"
 ],
 options:[
  {t:"（放下那杆秤）",go:"arc_trade7"}
 ]
};};
N["arc_trade7"]=function(){return{
 sceneTitle:"天平两端 · 幕三 · 一杆好秤",
 text:[
  "你决定去见那个账房老人。你挑了一个深夜，带着自己那杆秤，敲开了他的门。",
  "老人开门，看见你手里的秤，没有惊讶：「你查到了？」",
  "「查到了一半。」你说，「北境的粮价，是您平的。」",
  "老人让开门，让你进来。他屋里只有一盏灯、一摞账本。他坐下，说：「不是我平的。是文森·金秤平的——他死前，把这一整套'秤'，交给了商会。我只是个守秤的。」",
  "「守秤？」",
  "「守秤的意思，」老人说，「是让这杆秤，按他定的刻度走。北境的粮价，是他生前定好的'平衡'——太贵，北境饿殍；太贱，北境囤粮打人。正好，才能让两边都活。」",
  "你沉默了很久。你忽然明白：文森·金秤的「秤平天下」，不是让天下都富——是让天下都「正好」：正好活着，正好不互相吞。",
  "「那这杆秤……」你说，「是好事，还是坏事？」",
  "老人看着你：「秤本身，不分好坏。分的是——谁在秤上，谁在秤下。」"
 ],
 options:[
  {t:"（听老人说下去）",go:"arc_trade8"}
 ]
};};
N["arc_trade8"]=function(){return{
 sceneTitle:"天平两端 · 幕三 · 秤下之人",
 text:[
  "老人告诉你一个秘密：北境的「正好」平衡，正在被暗蚀会盯上。他们要的不是平衡——是「失衡」。粮价一崩，北境必乱，乱起来的北境，就是暗蚀会最好的土壤。",
  "「你守的这杆秤，」你说，「现在，有人在另一边，用力往下压。」",
  "老人沉默了很久：「我知道。所以我在等一个人——一个愿意把秤接过去的人。文森·金秤把秤交给商会，是要商会守平衡。但平衡这种东西，一个人守，是守不住的。」",
  "他站起来，从柜子里取出一本旧账，放在你面前：「这是文森·金秤的手账。里面记着他这一生，秤平过的东西——战争、粮价、人命、恩怨。他每一笔，都记着：秤斜的时候，他心里在想什么。」",
  "你翻开手账。第一页，只有一句话：「秤斜的时候，手会抖。抖，是因为你知道——你秤的不是东西，是人。」",
  "你合上手账，握住自己那杆秤。秤杆上「文森·金秤」的旧痕，在你掌心里，微微发烫。"
 ],
 options:[
  {t:"（翻开手账）",go:"arc_trade9"}
 ]
};};
N["arc_trade9"]=function(){return{
 sceneTitle:"天平两端 · 幕三 · 把秤接过去",
 text:[
  "你在老人屋里坐了一夜，把手账从头看到尾。文森·金秤的一生，像一杆秤的刻度——每一条，都是一次「斜了又平回来」的选择。",
  "天亮时，老人问你：「接吗？」",
  "你看着手账的最后一页。上面写着：「秤平天下，不是让天下人都有钱——是让天下人，都饿不死。守这一条，就够了。」",
  "你把铜秤放在桌上：「接。」",
  "老人点点头。他从怀里取出另一杆秤——和你的那杆一模一样，只是秤杆上，刻着「文森·金秤」四个字。他把秤放在你手里：「文森的金秤，传了三代。你是第四代。」",
  "你握着那杆秤，感觉它比看上去重。你轻声问：「守秤的人，都有什么下场？」",
  "老人想了想，说：「文森·金秤，是寿终正寝的。他死的时候，秤在手里，脸是平的。」他顿了顿，「守秤的人，只要秤还平，命就不会太歪。」"
 ],
 options:[
  {t:"（把金秤接过来）",go:"arc_trade10"}
 ]
};};
N["arc_trade10"]=function(){return{
 sceneTitle:"天平两端 · 幕四 · 失衡的前兆",
 text:[
  "你成为金秤传人后的第一个月，北境的粮价，开始异动——不是涨，是「忽涨忽跌」，像有人在搅一潭水。你查了三天，查到源头：一批来历不明的银币，正从南方流入北境市场，买空、砸盘，反复来回。",
  "你握着金秤，站在商会的阁楼上。你忽然明白，暗蚀会动手了——他们不要粮，他们要「失衡」本身：粮价一乱，北境的军心民心一起乱，乱到连「正好」都维持不住。",
  "你去找老人。老人听完，沉默了很久，说：「这一秤，我守了四十年，没失过手。现在，轮到你了。」",
  "「我该怎么做？」你问。",
  "老人看着你：「文森·金秤当年，是拿自己的粮，去填两边的秤。你——拿什么填？」",
  "你低头看金秤。你忽然明白，守秤的最后一步，不是算账——是把自己的身家，压上秤盘。"
 ],
 options:[
  {t:"（把身家压上秤盘）",go:"arc_trade11"}
 ]
};};
N["arc_trade11"]=function(){return{
 sceneTitle:"天平两端 · 幕四 · 压秤",
 text:[
  "你把自己的全部积蓄——还有你从商会账上借来的那笔「欠款」——全部换成了粮，投进北境市场。你学着文森·金秤的样子：一边托价，一边砸价，把那股「忽涨忽跌」的浪，一点点压平。",
  "三天三夜，你没合眼。金秤放在手边，每一次价格波动，你就拨一次——不是拨秤，是拨自己的心：稳住，再稳住。",
  "第四天，暗蚀会的银币，流干了。北境的粮价，重新回到「正好」的线上。你瘫坐在账房里，看着那杆金秤——它稳稳地立着，纹丝不动。",
  "你欠商会的钱，又多了一笔。但你忽然觉得，秤，平了。",
  "老人推门进来，看了一眼金秤，又看你：「平了。」他说，「你接住了。」",
  "你闭着眼，说：「文森·金秤压秤的时候，也是这样吗？」",
  "老人没有回答。他只是在门口站了一会儿，然后轻声说：「他压秤的时候，秤上压着的，是他自己的命。你压的，是你的积蓄——你比他，还差得远。」他顿了顿，「但你已经知道，秤要拿什么压了。」"
 ],
 options:[
  {t:"（继续压秤，稳住粮价）",go:"arc_trade12"}
 ]
};};
N["arc_trade12"]=function(){return{
 sceneTitle:"天平两端 · 幕四 · 秤上的分量",
 text:[
  "北境的粮价平了，但暗蚀会没有走。他们在南方布下另一盘棋：让商会「恰好」失去一条关键商路——断粮，断钱，断「正好」。",
  "你站在商会的地图前，看着那条被切断的商路。你忽然明白：暗蚀会要的不是打赢你——是要你守不住「平」。他们逼你选：保住商路，就得得罪南方城邦；保住南方城邦，商路就断。",
  "老人来找你。他这次没有给你答案，只问：「文森·金秤的手账上，有一笔他秤平'恩怨'的账——你知道他当时压的是什么吗？」",
  "你翻手账。那一页写着：「两家世仇，要我判谁对。我判不了对错——我把两家都请到一桌，让他们自己喝一杯。恩怨平不了，但酒能喝下去。秤有时候，不是称对错，是称'能不能坐下来说话'。」",
  "你合上手账。你忽然有了主意——你带着两坛酒，亲自走了一趟南方城邦和商会之间。不是去谈判，是去「喝酒」。",
  "三天后，商路通了。不是靠钱通的——是靠两坛酒，和一桌肯坐下来的人。"
 ],
 options:[
  {t:"（带着两坛酒，走一趟）",go:"arc_trade13"}
 ]
};};
N["arc_trade13"]=function(){return{
 sceneTitle:"天平两端 · 幕五 · 金秤之平",
 text:[
  "决战前夜，你站在商会的天平前——那是商会大厅里的一杆巨型铜秤，平时只作摆设。你把文森·金秤的金秤，放在左盘，把自己的那杆铜秤，放在右盘。",
  "两杆秤，在巨大的天平上，纹丝不动。你忽然明白：金秤传到你手上，不是让你秤天下——是让你秤自己：你的选择，能不能让秤，保持平。",
  "老人站在门口，看着这一幕：「文森·金秤说，秤平天下，不是秤尽天下事。是秤住自己——秤住自己的手，别让它抖。」",
  "你走下天平，把金秤收进怀里：「我知道了。」",
  "「你要去决战了。」老人说，「这一仗，商会的粮、钱、人，你都可以调——但你要记住：秤要平。别让这一仗，把秤打斜。」",
  "你点头，转身走出商会大门。身后的天平上，两杆秤还稳稳地立着——像两句话，一句来自文森·金秤，一句来自你自己。",
  "你握着金秤，走进夜色。风很大，但你的手，很稳。"
 ],
 options:[
  {t:"（带着金秤之平）走向决战前夜",go:"ending_prelude_hub"}
 ]
};};
/* ===== /v55inj:arcC ===== */

/* ---- 7. 强者互动 StrongKit ---- */
window.v53_ensureDefaults = function(){
  try{
    if(typeof S==='undefined'||!S) return;
    if(window.v52_ensureDefaults) v52_ensureDefaults();
    if(!S.knownStrong) S.knownStrong={};
    if(!S.strongBond) S.strongBond={};
    if(!S.challenged) S.challenged={};
    if(S.demi===undefined) S.demi=0;
    if(!S.guardianLog) S.guardianLog=[];
    if(!S.theomachy) S.theomachy={};
    if(!S.willShift) S.willShift={};
  }catch(e){}
};
function v53_findStrong(id){
  try{
    var M=window.STRONG_V53||{};
    for(var job in M){
      var o=M[job];
      if(!o) continue;
      var lists=[o.legend,o.master,o.raceSp,o.abyss];
      for(var i=0;i<lists.length;i++){
        var L=lists[i]||[];
        for(var j=0;j<L.length;j++){
          if(L[j]&&L[j].id===id) return {job:job,row:L[j],kind:i};
        }
      }
      if(o.deity&&o.deity.id===id) return {job:job,row:o.deity,kind:'deity'};
      if(o.special&&o.special.length){ for(var k=0;k<o.special.length;k++){ if(o.special[k]&&o.special[k].id===id) return {job:job,row:o.special[k],kind:'special'}; } }
    }
    var R=(typeof RIVALS_V52!=="undefined")?RIVALS_V52:{};
    for(var jb in R){
      var rr=(R[jb]||{}).rivals||[];
      for(var x=0;x<rr.length;x++){ if(rr[x]&&rr[x].id===id) return {job:jb,row:rr[x],kind:'rival'}; }
    }
    return null;
  }catch(e){ return null; }
};
window.v53_willKind = function(id){
  try{
    v53_ensureDefaults();
    var W=window.WILL_TO_ASCEND_V53||{};
    var w=W[id]; if(!w) return "随缘";
    var sh=S.willShift&&S.willShift[id]?S.willShift[id]:0;
    var lv=Math.max(0,Math.min(100,w.lv+(w.baseShift||0)+sh));
    if(w.kind==="禁忌"){ return "禁忌"; }
    if(lv<=20) return "淡泊";
    if(lv<=50) return "随缘";
    if(lv<=80) return "渴望";
    return "执念";
  }catch(e){ return "随缘"; }
};
window.v53_willMod = function(id){
  try{
    v53_ensureDefaults();
    var W=window.WILL_TO_ASCEND_V53||{};
    var w=W[id]; if(!w) return 0;
    if(w.kind==="禁忌"){
      var trig=true;
      if(w.trigger){ try{ trig=!!w.trigger(); }catch(e){ trig=true; } }
      if(!trig) return -99;
      return 10;
    }
    var sh=S.willShift&&S.willShift[id]?S.willShift[id]:0;
    var lv=Math.max(0,Math.min(100,w.lv+sh));
    if(lv<=20) return -10;
    if(lv<=50) return 0;
    if(lv<=80) return 5;
    return 10;
  }catch(e){ return 0; }
};
window.v53_meetStrong = function(id){
  try{
    v53_ensureDefaults();
    var f=v53_findStrong(id); if(!f) return;
    if(!S.knownStrong) S.knownStrong={};
    if(!S.knownStrong[id]) S.knownStrong[id]=S.day||0;
    var r=f.row;
    writePar("","noind");
    writePar("━━ 邂逅 · "+(r.title?r.title+"·":"")+r.cn+" ━━","noind flagline");
    var lines=[];
    if(r.power) lines.push("他（她）是"+r.power+"。");
    if(r.desc) lines.push(r.desc);
    if(r.meet) lines.push(r.meet);
    writePar(lines.join(""),"narration");
    if(window.v53_unlockStrongReading) v53_unlockStrongReading(id);
  }catch(e){}
};
window.v53_guardian = function(){
  try{
    v53_ensureDefaults();
    if(!window.openModal||!window.elFromHtml) return;
    var h="<div class='panel-wrap'><div class='panel-header'><span class='panel-title'>护法 · 请强者护持</span><button class='panel-close' onclick='closePanel()'>✕</button></div><div class='achievement-body' style='max-height:60vh;overflow:auto'>";
    var got=false;
    for(var job in (window.STRONG_V53||{})){
      var o=STRONG_V53[job]; if(!o) continue;
      var L=(o.master||[]).concat(o.legend||[]);
      for(var i=0;i<L.length;i++){
        var r=L[i];
        var bond=S.strongBond&&S.strongBond[r.id]?S.strongBond[r.id]:0;
        if(bond<1) continue;
        got=true;
        var bonus=10+Math.min(15,Math.floor(bond/2))+(r.realm===6?5:0);
        h+="<div class='achievement-card' style='margin-bottom:8px'><div class='achievement-name'>"+(r.title?r.title+"·":"")+r.cn+"</div>";
        h+="<div style='font-size:12px;color:var(--dim)'>"+(r.power||job)+" · 亲密度 "+bond+" · 可加成 +"+bonus+"</div>";
        h+="<button class='opt' style='margin-top:6px' onclick='v53_pickGuardian(\""+r.id+"\","+bonus+")'>请其护法</button></div>";
      }
    }
    if(!got) h+="<div style='color:var(--dim);font-size:13px'>你还没有足够亲近的强者。先去交好一位大宗师或传奇，他们才会为你护法。</div>";
    h+="</div></div>";
    openModal(elFromHtml(h));
  }catch(e){}
};
window.v53_pickGuardian = function(id,bonus){
  try{
    v53_ensureDefaults();
    var f=v53_findStrong(id);
    if(!f) return;
    if(!S.guardianLog) S.guardianLog=[];
    S.guardianActive={id:id,cn:(f.row.title?f.row.title+"·":"")+f.row.cn,bonus:bonus,day:S.day||0};
    S.guardianLog.push({id:id,day:S.day||0,bonus:bonus});
    if(S.guardianLog.length>20) S.guardianLog.shift();
    if(window.v44_pushToast) v44_pushToast('护法已定',S.guardianActive.cn+'将在你破境时护持','success','🛡️');
    if(window.closePanel) closePanel();
  }catch(e){}
};
window.v53_guardianBonus = function(){
  try{
    if(typeof S==='undefined'||!S||!S.guardianActive) return 0;
    if(S.guardianActive.day&&S.day&&S.day-S.guardianActive.day>30){ S.guardianActive=null; return 0; }
    return S.guardianActive.bonus||0;
  }catch(e){ return 0; }
};
window.v53_bondGift = function(id){
  try{
    v53_ensureDefaults();
    var f=v53_findStrong(id); if(!f) return;
    var cost=150;
    if((S.coin||0)<cost){ if(window.v44_pushToast) v44_pushToast('囊中羞涩','交好需要 150 金币','warn','💰'); return; }
    S.coin-=cost;
    if(!S.strongBond) S.strongBond={};
    S.strongBond[id]=(S.strongBond[id]||0)+1;
    if(window.v44_pushToast) v44_pushToast('交好','你与'+(f.row.cn)+'的交情又深了一层','success','🤝');
    var w=window.WILL_TO_ASCEND_V53||{};
    if(w[id]&&w[id].kind!=="禁忌"){
      if(!S.willShift) S.willShift={};
      S.willShift[id]=(S.willShift[id]||0)-8;
      if(window.v53_willKind(id)==="淡泊"){ if(window.v44_pushToast) v44_pushToast('心念微动',f.row.cn+'对神座的执念淡了一些','info','🍃'); }
    }
  }catch(e){}
};
window.v53_challengeStrong = function(id){
  try{
    v53_ensureDefaults();
    var f=v53_findStrong(id); if(!f) return;
    var r=f.row;
    if(!S.challenged) S.challenged={};
    var st=document.getElementById('story');
    if(!st) return;
    var main=(S.attrs&&S.attrs.STR)?S.attrs.STR:50;
    var t1=30+Math.floor(main/5)+((r.realm||5)-5)*8;
    t1+=window.v53_willMod?v53_willMod(id):0;
    t1=Math.max(8,Math.min(92,t1));
    var rr=rollD100();
    writePar("","noind");
    writePar("━━ 挑战 · "+(r.title?r.title+"·":"")+r.cn+" ━━","noind flagline");
    if(rr<=t1){
      S.challenged[id]="won";
      writePar("你赢了。"+(r.defeatLine||"他（她）收手时看了你很久，像是要把你的样子记下来。"),"narration");
      writePar("【判定】目标 "+t1+"，掷出 "+rr+" → 胜","hint");
      if(!S.knownStrong) S.knownStrong={};
      S.knownStrong[id]=S.day||0;
      if(window.v44_pushToast) v44_pushToast('一战成名',(r.title?r.title+"·":"")+r.cn+'记住了你','success','⚔️');
      if(window.v53_willKind(id)==="执念"){ if(window.v44_pushToast) v44_pushToast('结下因果','你击败了一位执念者。他（她）不会忘记这一天。','warn','🌑'); }
    } else {
      S.challenged[id]="lost";
      writePar("你败了。"+(r.loseText||"他（她）没有伤你，只是摇摇头。"),"narration");
      writePar("【判定】目标 "+t1+"，掷出 "+rr+" → 未过","roll-fail");
      S.san=Math.max(0,(S.san||100)-3);
    }
  }catch(e){}
};
window.v53_witnessFall = function(id){
  try{
    v53_ensureDefaults();
    var f=v53_findStrong(id); if(!f) return;
    if(!S.knownStrong) S.knownStrong={};
    S.knownStrong[id]=S.day||0;
    S.godRival[id]="fallen";
    if(!S.willShift) S.willShift={};
    var w=window.WILL_TO_ASCEND_V53||{};
    if(w[id]&&w[id].kind!=="禁忌") S.willShift[id]=(S.willShift[id]||0)-30;
    if(window.v44_pushToast) v44_pushToast('见证陨落','你亲眼看见'+(f.row.cn)+'倒下了。那条路，少了一个人。','info','🕯️');
  }catch(e){}
};
/* ---- 8. 成神三要素主流程 ---- */
window.v53_theomachy = function(){
  try{
    v53_ensureDefaults();
    if(!window.openModal||!window.elFromHtml) return;
    var job=S.job||"";
    var T=(window.THEOMACHY_V53||{})[job];
    if(!T){ if(window.v44_pushToast) v44_pushToast('尚不明朗','你的职业尚无成神之法的记载','info','📜'); return; }
    var st=T.step||0;
    var hasRelic=S.artifact===job;
    var h="<div class='panel-wrap'><div class='panel-header'><span class='panel-title'>登神 · 三要素</span><button class='panel-close' onclick='closePanel()'>✕</button></div><div class='achievement-body' style='max-height:64vh;overflow:auto'>";
    h+="<div style='font-family:Georgia,serif;font-size:16px;font-weight:bold;color:#8b6f47;margin-bottom:8px'>"+job+" · 成神三要素</div>";
    h+="<div style='font-size:13px;color:var(--dim);margin-bottom:10px'>① 本职业唯一神性物品　② 专属成神仪式　③ 领悟职业真谛。三样缺一不可。</div>";
    h+="<div class='achievement-card'><div class='achievement-name'>① 神性物品 · "+(T.relic||"未知")+"</div>";
    h+="<div style='font-size:12px;color:var(--dim)'>"+(hasRelic?"你已持有本职业神器，它的神性形态在你手中苏醒。":"尚未持有。可循组织首席线索或大陆传闻寻找本职业神器的下落。")+"</div></div>";
    h+="<div class='achievement-card'><div class='achievement-name'>② 成神仪式</div>";
    h+="<div style='font-size:12px;color:var(--dim)'>地点："+(T.place||"未知")+"<br/>时间："+(T.time||"未知")+"<br/>条件："+(T.cond||"未知")+"</div></div>";
    h+="<div class='achievement-card'><div class='achievement-name'>③ 领悟职业真谛</div>";
    h+="<div style='font-size:12px;color:var(--dim)'>仪式终末，你要直面自己的道。已悟者写下的感悟是："+(T.truth||"无人留下文字")+"</div></div>";
    h+="<div style='margin-top:10px'>";
    if(S.realm>=6&&hasRelic&&S.godTrial&&S.godTrial[job]==="deified"){
      h+="<button class='opt opt-gold' onclick='v53_runTheomachy()'>开始登神仪式</button>";
    } else if(S.realm>=6&&hasRelic){
      h+="<div style='font-size:12px;color:var(--dim);margin-bottom:6px'>你已具登神之资，但还需通过神座试炼的资格认定（组织首席或击败在位半神）。</div>";
    } else if(S.realm>=6){
      h+="<div style='font-size:12px;color:var(--dim);margin-bottom:6px'>神器尚未到手——它认得你，你要去找它。</div>";
    } else {
      h+="<div style='font-size:12px;color:var(--dim);margin-bottom:6px'>登神需传奇境（境界≥6）方可叩门。你现在的路，还长。</div>";
    }
    h+="</div></div></div>";
    openModal(elFromHtml(h));
  }catch(e){}
};
window.v53_runTheomachy = function(){
  try{
    v53_ensureDefaults();
    var job=S.job||"";
    var T=(window.THEOMACHY_V53||{})[job];
    if(!T) return;
    if(!S.theomachy) S.theomachy={};
    var step=S.theomachy.step||0;
    if(step===0){
      S.theomachy.step=1;
      writePar("","noind");
      writePar("━━ 登神 · 第一程 · 神器觉醒 ━━","noind flagline");
      var s1=(T.relicStory||[])[0]||"你握着本职业的神器，感觉到它在发烫。";
      writePar(s1,"narration");
      writePar("它认得你。你握着"+T.relic+"，像握着一段失传了很久的记忆。","narration");
      return;
    }
    if(step===1){
      S.theomachy.step=2;
      writePar("","noind");
      writePar("━━ 登神 · 第二程 · 成神仪式 ━━","noind flagline");
      var s2=(T.relicStory||[])[1]||"仪式在"+T.place+"举行。";
      writePar(s2,"narration");
      writePar("地点在"+T.place+"，时间是"+T.time+"。"+T.cond+"。","narration");
      writePar("你抵达时，天地静得只剩心跳。仪式开始了。","narration");
      var rolls=[
        {cn:"意志 · 撑过仪式的反噬",t:60+Math.floor((S.attrs&&S.attrs.SPR||50)/8)},
        {cn:"技艺 · 让仪式记住你的手法",t:62+Math.floor((S.attrs&&S.attrs.INT||50)/8)}
      ];
      var pass=true;
      for(var i=0;i<rolls.length;i++){
        var r1=rollD100(); var ok1=r1<=Math.max(10,Math.min(95,rolls[i].t));
        if(window.v44_diceFX) v44_diceFX(r1,rolls[i].t,ok1,rolls[i].cn);
        if(!ok1) pass=false;
      }
      if(pass){ writePar("仪式顺利完成。天边出现了异象——这一方的世界，记住了你的名字。","narration"); }
      else { writePar("仪式中途出了岔子，你强撑到结束。世界记住了你，也记住了你的狼狈。好在，仪式成了。","narration"); }
      return;
    }
    if(step>=2){
      if(S.deified){ writePar("你已登神。神座之上，只此一座。","narration"); return; }
      S.deified=1;
      S.theomachy[job]="done";
      S.theomachy.step=3;
      writePar("","noind");
      writePar("━━ 登神 · 第三程 · 领悟职业真谛 ━━","noind flagline");
      writePar(T.truth||"","narration");
      writePar("你合上眼。再睁开时，尘世的名字已从你身上褪去——写进了那唯一的座次里。","narration");
      if(window.v44_breakthroughFX) v44_breakthroughFX();
      if(window.v44_pushToast) v44_pushToast('登神','你成了本职业唯一的真神。此世此途，只此一座。','success','👑');
      if(S.endingFlags) S.endingFlags.deified=1;
      if(window.v53_syncDeity) v53_syncDeity();
    }
  }catch(e){}
};
