 {"id":"rm_m_灵魂法师1","sid":"m_灵魂法师1","text":"坊间说，他收徒只看一件事：肯不肯为一件事笨十年。","area":"","reading":""},
 {"id":"rm_r_druid1","sid":"r_druid1","text":"银叶城那边传来一件怪事：林卫里那位德鲁伊，已经一个月没出林子了。有人说，树在跟他说什么——他一直在听。","area":"银叶城","reading":""}
