RELATIONS_V56.push({a:"lv_knight1",b:"lv_priest1",type:"宿敌",note:"罗兰挡在书商面前也挡在执事面前，克莱门的净化令过不了他那一关",weight:3,rumorLine:"净化令最凶那几年，白盾团长站在书商门前，谁也不让。"});
