RELATIONS_V56.push({a:"theo_smith",b:"lv_smith1",type:"师徒",note:"索林守初火熔炉，格朗在炉边站了三百年听火说话",weight:4,rumorLine:"矮人们说，索林王的初火熔炉前，格朗站得最久。"});
RELATIONS_V56.push({a:"theo_smith",b:"lv_smith2",type:"师徒",note:"梅是老铸师捡回来的孤儿，索林是传承半神——铁峰堡的炉火认他们",weight:3,rumorLine:"有人说梅的炽芯里，还留着老铸师最后一句话。"});
RELATIONS_V56.push({a:"lv_smith1",b:"lv_smith2",type:"同门",note:"格朗与梅同为锻造公会，一个符文一个炽芯，铁峰堡最值钱的兵器都出自他们",weight:3,rumorLine:"锻造公会说，格朗的符文和梅的炽芯，是炉火的两个方向。"});
RELATIONS_V56.push({a:"lv_smith2",b:"rv_smith_a",type:"宿敌",note:"梅铸活物，灰指炼毒药——一个给铁心跳，一个给药五色",weight:2,rumorLine:"黑市上说，灰指的药和梅的锤，碰在一起就是灾祸。"});
RELATIONS_V56.push({a:"rv_smith_g",b:"theo_smith",type:"同门",note:"铁炉·格姆隐入矿洞前是锻造公会的人，索林知道他的炉火",weight:2,rumorLine:"铁峰堡的老炉工说，格姆的锤子还在公会，人却进了矿洞。"});
/* 商人类 */
RELATIONS_V56.push({a:"lv_trade1",b:"rv_trade_j",type:"宿敌",note:"文森是金衡总会长、光明正大做生意，金牙是黑市之王——一白一黑",weight:4,rumorLine:"交汇城说，金牙的金子和文森的账本，是这座城的两杆秤。"});
RELATIONS_V56.push({a:"lv_trade1",b:"lv_trade2",type:"挚友",note:"文森算账，洛佩斯看海——一个守老巷，一个挂半帆",weight:2,rumorLine:"商人们说，老巷铺子和南方船队从没红过脸。"});
RELATIONS_V56.push({a:"lv_trade2",b:"rv_trade_y",type:"同门",note:"洛佩斯是南方船王，燕来·沈是航运大亨——南方的船都看他们脸色",weight:3,rumorLine:"南方港城的码头说，燕来和半帆各占一半顺风。"});
RELATIONS_V56.push({a:"lv_trade2",b:"lv_war5",type:"挚友",note:"罗·断江在南方港城开酒馆，洛佩斯的船队常来喝酒",weight:3,rumorLine:"断江酒馆的招牌菜断江鱼，是半帆船队的水手们捧出来的。"});
RELATIONS_V56.push({a:"lv_trade1",b:"lv_war4",type:"挚友",note:"文森不赚让人活不下去的钱，叶·孤山只接守城的单——一个管账一个管城",weight:2,rumorLine:"自由城邦说，叶会长佣金里扣下的一成，文森总会长替他记着。"});
/* 灵魂法师系 */
RELATIONS_V56.push({a:"theo_soul",b:"lv_soul1",type:"师徒",note:"奥雷利安离开圣殿后，澜·梦墟是最后一位守镜人",weight:5,rumorLine:"晨曦圣殿说，回音之镜三千年没碎，因为守镜人从不敢照它。"});
RELATIONS_V56.push({a:"theo_soul",b:"rv_soul_r",type:"师徒",note:"赎夜替圣殿守了三十年夜，最后一夜走进深渊裂隙——奥雷利安没拦住",weight:4,rumorLine:"守望者们说，赎夜走进裂隙那夜，奥雷利安在塔顶站到天明。"});
RELATIONS_V56.push({a:"lv_soul1",b:"rv_soul_w",type:"同门",note:"澜守回音之镜，无面歌者流浪唱歌——圣殿的两条支流",weight:2,rumorLine:"圣殿说，无面歌者的歌没有词，守镜人却能听懂。"});
RELATIONS_V56.push({a:"theo_soul",b:"lv_mage5",type:"同门",note:"奥雷利安是守望者首席，伊尔·灰书是守望者藏卷师——一守深渊一守档案",weight:3,rumorLine:"守望者塔说，灰书的卷宗里有一页空白，是留给将来能彻底封住七印的人。"});
/* 跨系/跨种族 */
RELATIONS_V56.push({a:"lv_mage1",b:"lv_priest3",type:"挚友",note:"奥薇恩与艾诺尔都是银叶城的异类——一个不争神座，一个信人类的神",weight:2,rumorLine:"银叶城的老树听惯了她们俩的闲聊。"});
RELATIONS_V56.push({a:"lv_mage4",b:"lv_ranger1",type:"挚友",note:"瑟琳守世界树，艾琳追白鹿追到世界树脚下——都敬那棵树",weight:3,rumorLine:"世界树的根下，守树人见过一个追风的大巡守。"});
RELATIONS_V56.push({a:"lv_war2",b:"r_sham1",type:"同门",note:"喀兰是狼旗第一勇士，老萨满主持王庭祭典——一个打仗一个祭祖",weight:2,rumorLine:"兽人王庭说，赤峰出征前总要先去老萨满那里坐一坐。"});
RELATIONS_V56.push({a:"lv_war2",b:"lv_war3",type:"宿敌",note:"喀兰屠过村也守过村，秦·长风守铁门关挡东军——兽人与人类旧战的活证",weight:3,rumorLine:"喀兰的石像脸朝南对着人类地界，他说让人类看看草原不是只有仇恨。"});
RELATIONS_V56.push({a:"lv_thief1",b:"lv_thief2",type:"师徒",note:"杜·夜枭是现任阁主，薇·灰雾在暗影阁挂过名——灰雾的路子有阁主的影子",weight:2,rumorLine:"暗影阁的老人们说，灰雾的影子比人长，路数却像极了夜枭。"});
RELATIONS_V56.push({a:"lv_priest1",b:"rv_priest_s",type:"师徒",note:"克莱门是枢机主教，静默修女·安在圣城守夜——她欠的人里有他",weight:2,rumorLine:"圣城的下水道边，有人见过静默修女在等一个人。"});
RELATIONS_V56.push({a:"lv_war4",b:"rv_thief_y",type:"挚友",note:"叶·孤山在自由城邦独酌，夜鸢隐居在自由城邦——一明一暗都在那城",weight:2,rumorLine:"自由城邦的酒馆说，夜鸢还回去的东西，有几件是孤山守城守回来的。"});
RELATIONS_V56.push({a:"lv_smith2",b:"rv_smith_g",type:"师徒",note:"梅是锻造公会人类首席铸师，铁炉·格姆是隐入矿洞的老炉工——她的手艺有老炉工的底子",weight:2,rumorLine:"锻造公会说，梅的炽芯是传下来的，格姆的炉火也是。"});
RELATIONS_V56.push({a:"lv_knight2",b:"lv_priest3",type:"挚友",note:"伊莎在圣城平民窟长大，艾诺尔在圣城长大——两个都见过教会两面的人",weight:2,rumorLine:"圣城的老人们说，晨辉骑士和银冠主教是城里最不恨教会的人。"});
RELATIONS_V56.push({a:"rv_war_r",b:"lv_war5",type:"宿敌",note:"红鬃是北地佣兵之王，罗·断江是南方退役海卫——南北两大兵头，互相不服又互相敬",weight:2,rumorLine:"南北的兵都传：北红鬃，南断江，见面就要分个高下。"});
RELATIONS_V56.push({a:"lv_mage3",b:"lv_ranger2",type:"挚友",note:"凯·青焰在北方烧过一整支军队，贺·断弓在北方雪原猎不该存在的猎物——北地的孤人",weight:2,rumorLine:"北地说，青焰的旧灯和断弓的断弓，是雪原上两样不说话的东西。"});
RELATIONS_V56.push({a:"lv_priest2",b:"de_soul",type:"宿敌",note:"玛格达守静默殿的三百年夜，奥雷利安·晨曦的灵魂法师一脉触碰过灵魂禁忌的边界——守夜人警惕窥心者",weight:2,rumorLine:"静默殿的老人说，晨曦圣殿的人，守夜人从不让他们靠近烛光。"});
RELATIONS_V56.push({a:"lv_soul1",b:"ab_soul1",type:"宿敌",note:"澜守回音之镜，腐化的灵魂法师在深渊收集他人的梦——同源异路",weight:3,rumorLine:"圣殿说，镜子里最深的裂缝，是被深渊那边的回声震出来的。"});
RELATIONS_V56.push({a:"lv_mage2",b:"lv_war3",type:"挚友",note:"洛·晨雾守星落塔，秦·长风守铁门关——两个都替别人守着位置的人",weight:3,rumorLine:"北境和学院之间传：雾塔和长风，一个守塔一个守城，都说对方才是硬骨头。"});
/* ---- 动态事件 16 条（worldTick 触发，missedEvents 回收） ---- */
STRONG_EVENTS_V56.push({id:"ev56_duel_north",relId:"r_war_vs_war",kind:"决斗",day:21,text:["北地的风里传来消息：红鬃和断江在铁门关外碰了面。","两人没打起来。红鬃把一碗酒推过去，断江接了——南北两个兵头，喝了一碗酒，各自走了。","有人说他们约好了，等大陆的事了结，再分高下。"],effect:{force:"f_north",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_grudge_church",relId:"r_priest_split",kind:"反目",day:35,text:["圣城的枢机院里吵了一夜。","克莱门·圣言提起了被流放的炽言，说他「走错了路」。","第二天，静默殿的守夜人发现，静默修女·安在门前站了一整夜，手里攥着一封信。"],effect:{force:"f_church",delta:-1}});
STRONG_EVENTS_V56.push({id:"ev56_ally_tower",relId:"r_war_mage",kind:"联手",day:49,text:["铁门关传来消息：雾塔的洛·晨雾亲自南下，替镇北军加固了城防结界。","秦·长风在城头站了一夜，第二天让兵卒给星落塔送了一坛酒。","南来北往的商队都说，这是近十年北境和学院第一次走得这么近。"],effect:{force:"f_north",delta:3}});
STRONG_EVENTS_V56.push({id:"ev56_marry_leaf",relId:"r_elf_elf",kind:"联姻",day:63,text:["银叶城的老树下摆了三天宴。","精灵长老会的瑟琳·银冠，收了一个人类学徒——那孩子是商队里跑丢的孤儿。","奥薇恩站在树下看了很久，对艾诺尔主教说：这棵树，又记住了一个人。"],effect:{force:"f_elf",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_fall_blacksmith",relId:"r_smith_fall",kind:"寻仇",day:77,text:["铁峰堡出了事。","隐入矿洞多年的铁炉·格姆，一夜之间出现在锻造公会门口，锤子砸碎了三件「邪器」。","他什么也没说，砸完就走了。索林王在初火熔炉前坐了一夜。"],effect:{force:"f_dwarf",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_reconcile_sea",relId:"r_trade_trade",kind:"和解",day:91,text:["南方港城的两支船队，三年来第一次在同一个码头卸货。","洛佩斯·半帆站在船头，朝燕来·沈的船拱了拱手；对面回了一礼。","码头上的人说，风要变顺了。"],effect:{force:"f_south",delta:3}});
STRONG_EVENTS_V56.push({id:"ev56_hunt_abyss",relId:"r_abyss_ranger",kind:"联手",day:105,text:["雪原深处传来消息：断弓的猎队和一头腐化的雪兽打了一夜。","天亮时，断弓的背囊空了——那根留了多年的弓弦，断了。","他在避风处坐了很久，然后说：弦没了，仗还没打完。"],effect:{force:"f_abyss",delta:-2}});
STRONG_EVENTS_V56.push({id:"ev56_vigil_soul",relId:"r_soul_watch",kind:"和解",day:119,text:["晨曦圣殿的回音之镜，裂了一道缝。","守镜人澜·梦墟在镜前站了一夜，没有照它。","第二天，她在门口放了一盏灯——给深渊裂隙里那个人的。"],effect:{force:"f_watcher",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_black_war",relId:"r_war_war",kind:"决斗",day:133,text:["兽人王庭的草原上，喀兰·赤峰和断山·库鲁打了一架。","两人都没用全力——打到一半，喀兰把红布头巾系在库鲁刀柄上，说：留着，草原认你。","老萨满说，这不是争第一，是争「谁先替草原挡灾」。"],effect:{force:"f_orc",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_lamp_mage",relId:"r_mage_lamp",kind:"寻仇",day:147,text:["北地的雪原上，有人看见一盏旧灯亮了一瞬。","凯·青焰蹲在灯前看了很久，然后烧掉了一座暗蚀会的哨站。","没人知道他找到了什么。"],effect:{force:"f_abyss",delta:-3}});
STRONG_EVENTS_V56.push({id:"ev56_shield_city",relId:"r_knight_war",kind:"联手",day:161,text:["圣城来了一支北境的商队，带着秦·长风的信。","罗兰·白盾读完信，把盾漆成了新的白色，然后亲自护送那批「书」出了城。","净化的风，在圣城门口停了一停。"],effect:{force:"f_church",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_merchant_ledger",relId:"r_trade_ledger",kind:"和解",day:175,text:["交汇城的老巷里，文森·金秤的铺子来了个不速之客。","金牙站在门口，放下一本黑账，说：这一页，还你。","文森拨着算盘，头也没抬：记上了。"],effect:{force:"f_trade",delta:3}});
STRONG_EVENTS_V56.push({id:"ev56_ruin_old",relId:"r_old_legend",kind:"寻仇",day:189,text:["大陆深处的一座古战场，被人翻了个底朝天。","有人说是断山·库鲁在找他父亲的断刀，有人说是红鬃在找当年血战的遗物。","只有守墓的老人知道：那天夜里，有个独臂的人站在最高的土丘上，站到天明。"],effect:{force:"f_north",delta:1}});
STRONG_EVENTS_V56.push({id:"ev56_whisper_abyss",relId:"r_abyss_soul",kind:"联手",day:203,text:["深渊裂隙附近的村子，一夜之间没了声音。","腐化的灵魂法师在那里「收集」了一整夜的梦。","守镜人澜·梦墟第二天进了裂隙——她带了那盏灯。"],effect:{force:"f_abyss",delta:-2}});
STRONG_EVENTS_V56.push({id:"ev56_crown_elf",relId:"r_elf_crown",kind:"联姻",day:217,text:["银叶城给圣城递了一张帖子：瑟琳·银冠要收那个孤儿学徒为正式弟子。","奥薇恩在帖子上加了一行字：树已记住。","克莱门主教读完，把那页禁书合上了很久。"],effect:{force:"f_elf",delta:2}});
STRONG_EVENTS_V56.push({id:"ev56_final_omen",relId:"r_omen",kind:"联手",day:231,text:["第七印的封印，松了一寸。","伊尔·灰书的档案室彻夜亮着灯，他在那页空白上，写了一行字。","第二天，守望者塔的信鸽飞向大陆所有方向：请他们各自守好自己的那盏灯。"],effect:{force:"f_watcher",delta:-2}});
/* ---- 告示板 ---- */
window.NOTICE_V56=[
 {id:"lv_war3",text:"镇北军统领秦·长风驻守铁门关，近日严查北境商路。"},
 {id:"lv_trade1",text:"金衡商会总会长文森·金秤：灾年粮价不涨，商户勿囤。"},
 {id:"lv_knight1",text:"誓约骑士团团长罗兰·白盾：圣城夜巡加岗，净化令暂停三日。"},
 {id:"lv_ranger1",text:"荒野巡守大巡守艾琳·逐风：林道有异兽出没，商队请绕行。"},
 {id:"lv_priest1",text:"圣辉教会枢机克莱门·圣言：明日大公祈祷，全城禁喧哗。"}
];


/*v56inj:talk*/
window.QUEST_V56 = window.QUEST_V56 || {};
/* ===== 魔法师 ===== */
TALK_V56["lv_mage1"]={理念:["神座只有一把椅子，路有无数条。我赢了太久，赢过的人最该记得：法术是为什么存在的。"],"传闻":["银叶城的商队说，北地的雪今年来得早。你路上要是碰见一个烧青色火焰的法师，替我带句话：灯还亮着吗。"],"修行":["不急着赢。你先赢自己，再赢别人。你连自己为什么学都忘了的时候，赢什么都白赢。"],"闲聊":["你看这叶子，转圈的时候多好看。元素不着急，你着急什么。"]};
TALK_V56["lv_mage2"]={理念:["星落塔的灯，不是给看得见的人点的。坐神座不难，难的是坐上去还记得自己是个人。"],"传闻":["你问奥伦？他离塔十二年了。星徽还在第七层窗台上，没人敢碰。你要是见着他，告诉他：塔没塌，就是灯灭了一盏。"],"修行":["一道法则，能刻几层，要看它自己愿意承受几层。你的法力也是这样——别硬刻，会裂。"],"闲聊":["双子星升起来的时候，塔顶风最大。你要是睡不着，可以上来看看。"]};
TALK_V56["lv_mage3"]={理念:["火烧完了才算活过吗？我也不知道。我只知道，那盏灯亮着的时候，全村人都不怕夜。"],"传闻":["雪原深处有东西在动。不是兽，是更深的。断弓那家伙在盯着，我信他。"],"修行":["你的火太新。烧不亮我的灯，也烧不疼敌人。火要养，像养一盏灯。"],"闲聊":["你说，火这种东西……算了，问你也不懂。"]};
TALK_V56["lv_mage4"]={理念:["树活一万年，我守它两百年，像给它挠了个痒。你们人类总想登顶，我们精灵只想多听几遍风。"],"传闻":["结界外的林子里，最近多了些脚印。不是兽的。你走路轻一点，别惊着树。"],"修行":["你身上有它喜欢的味道。树认人，不认修为。静下来，它自然会告诉你该怎么走。"],"闲聊":["拿着这片叶子。树说，你会回来的。"]};
TALK_V56["lv_mage5"]={理念:["七印的事，比神座要紧。我记了三千年的松动，每一笔都像记自己孩子的生辰。"],"传闻":["第七印松了一寸。守望者塔的信鸽都出去了。你要是去圣城，替我看看那页空白——还空着吗。"],"修行":["你想看哪一页？先说好，看完要还。知识这东西，借了就要还，不然它会咬你。"],"闲聊":["灰布书里没有我。你翻遍了也找不到我，因为我从没把自己写进去。"]};
/* ===== 战士 ===== */
TALK_V56["lv_war1"]={理念:["盾不是用来挡自己的，是用来让别人敢往前走的。我这两百年，就干了这一件事。"],"传闻":["矿道里最近不太平。老兄弟们说，听见了不该有的响动。我走不开，你路过铁峰堡时替我带句话给索林王。"],"修行":["你的劲儿使在了刀上，没使在心上。盾兵的手是稳的，因为心先稳了。"],"闲聊":["来，帮我看看这道新凹痕——三天前替一个小姑娘挡的。够不够深？"]};
TALK_V56["lv_war2"]={理念:["草原上的规矩很简单：你敬狼，狼敬你。我屠过村，也守过村——草原记着，人类也记着。"],"传闻":["我在找一块旧碑。上面刻着兽人和人类第一份和平条约。找到了，我就把它重新立起来。"],"修行":["你的刀还差一点风的味道。草原的风是活的，你的刀是死的。去跑一跑，让它活。"],"闲聊":["吃。吃饱了，我们聊点比打仗重要的事。"]};
TALK_V56["lv_war3"]={理念:["城在，我在。这不是豪言，是账——我欠这座城七天命，要还一辈子。"],"传闻":["北境的风向要变了。东军蠢蠢欲动。你走商路的话，别走夜路，关口我加了岗。"],"修行":["你什么时候懂了城为什么在，再来找我。那之前，你的枪还太轻。"],"闲聊":["（他摩挲着木臂，没说话。风把他的披风吹得笔直。）"]};
TALK_V56["lv_war4"]={理念:["守城的人，心要凉一点。心热的人守不住，因为你会忍不住冲出去。"],"传闻":["交汇城的佣兵又涨价了。随他们涨，我只接守城的单，从不涨价。"],"修行":["你刀法不差，心还太热。凉下来，刀就稳了。"],"闲聊":["坐。这杯请你——赌你将来守得住一座城。"]};
TALK_V56["lv_war5"]={理念:["打够了，就该过自己的日子。神座那张椅子，不如我酒馆里的旧木凳坐着舒服。"],"传闻":["海上不太平。海盗最近又起来了。我这把老骨头是不动了，年轻人们去管吧。"],"修行":["你的手太急。擦杯子擦久了你就懂：活儿要慢，心才稳。"],"闲聊":["今天新到的鱼，很新鲜。吃鱼吗？"]};
/* ===== 牧师 ===== */
TALK_V56["lv_priest1"]={理念:["圣光是唯一的路。可走这条路的人，脚下沾着泥。我信圣光，也信泥——这才是完整的信仰。"],"传闻":["净化令的事，圣城吵了一夜。我不后悔主张它，也不后悔偷偷救那书商。两者都是真的。"],"修行":["你的心还不够安静。神只对安静的人说话。先安静下来，再问神。"],"闲聊":["（他翻开一页禁书，又合上。祷告室的灯，晃了一下。）"]};
TALK_V56["lv_priest2"]={理念:["这里没有神，只有夜。夜记得每个人——你做过什么，夜都替你记着。"],"传闻":["静默殿的蜡烛，今年烧得快了些。是风大了，还是夜长了？我不知道。"],"修行":["你还没有准备好，在黑暗里坐三百年。先从一夜开始吧。"],"闲聊":["（她轻轻吹了吹烛火，影子在墙上晃了晃。）"]};
TALK_V56["lv_priest3"]={理念:["神不分种族，黑暗也不分。我这盏灯，是替两种族的黑暗点的。"],"传闻":["银叶城的精灵们，最近在议论圣城的事。他们问我：净化令会烧到银叶城吗？我说：灯在，就不会。"],"修行":["你的光太亮，会烧着叶子。收一收，让光能照进树影里。"],"闲聊":["进来吧。这盏灯下，没有教条，只有人。"]};
/* ===== 盗贼 ===== */
TALK_V56["lv_thief1"]={理念:["暗影无神，故无戒——只有规矩：事成拂衣去，深藏身与名。我偷了一辈子，唯一不想偷的，是一个名字。"],"传闻":["码头最近有批「不该存在」的货。灰鼠在盯。你要是碰见黑市的货，绕开走。"],"修行":["跟着光走的人，看不见我。你想学暗影，先学会别让光找到你。"],"闲聊":["（阴影里传来一声极轻的响动。他走了，你没看见他走。）"]};
TALK_V56["lv_thief2"]={理念:["影子比人长——混血的代价，也是混血的礼物。我在两个世界之间活着，神座只有一个，我怕坐上去，就只剩一个世界了。"],"传闻":["商路上有句话：别在雾天跟灰雾谈生意。你记住就行，别的别多问。"],"修行":["你的影子太干净了。跟着我，我怕你被晒黑。先去泥里滚一圈再来。"],"闲聊":["巧了，我正好认识一个「不存在的人」。你要找的那个，我见过。"]};
/* ===== 游侠 ===== */
TALK_V56["lv_ranger1"]={理念:["你追的不是鹿，是路。路比神座长——神座只有一把椅子，路有无数条。"],"传闻":["林道最近有异兽出没。商队绕行了，狼群也跟着绕了。万物都在让路，你也让一让。"],"修行":["你的脚还太急。路不着急，你着急什么？跑起来之前，先学会走。"],"闲聊":["（她折了片叶子，吹了个调子。林子里有什么回应了一声。）"]};
TALK_V56["lv_ranger2"]={理念:["弓断了还能打——这是北方猎人的老话。弦没了，仗还没打完。"],"传闻":["雪原深处有东西在动。不是兽。是更深的。我盯着呢，你别进深雪区。"],"修行":["你的火气太大，会把雪原的兽都惊跑。稳下来，像雪一样静。"],"闲聊":["吃块干肉。雪原不认生人，认味道。"]};
/* ===== 骑士 ===== */
TALK_V56["lv_knight1"]={理念:["白，是因为我挡下的东西都不配留在上面。你进城，是想改变它，还是想利用它？"],"传闻":["净化令暂停三日。三日够书商们搬走一批书了。这是我当团长能做的全部。"],"修行":["你的剑还太飘。守护的剑，要沉。沉到能替别人挡下东西。"],"闲聊":["来，按个手印。你是它认识的新人。"]};
TALK_V56["lv_knight2"]={理念:["我的剑，只守值得守的东西。平民窟教会了我：善和恶，不在教义里，在人做的事里。"],"传闻":["枢机院又要开会了。我去劝，不一定有用，但总要有人去劝。"],"修行":["你的剑还太年轻，没见过值得守的东西。先去守一守，再谈剑。"],"闲聊":["（她解下头盔，露出一头短发，笑得坦荡。）"]};
/* ===== 术士 ===== */
TALK_V56["lv_smith1"]={理念:["铁不用重锤，铁用耐心。你摸到铁的纹理，它才会把秘密说给你听。"],"传闻":["铁峰堡的炉火今年旺了些。索林王说，是初火在等什么。你说，它在等什么？"],"修行":["你的火候还差一点。铁这东西，急不得。你急，它就裂。"],"闲聊":["来，帮我看看这把刀——它说它想变剑。"]};
TALK_V56["lv_smith2"]={理念:["造物该有自己的脾气。我铸的东西会活，不是傀儡术——是它自己愿意活着。"],"传闻":["矿洞里传出过锤声。格姆那老家伙，还活着。"],"修行":["你的手还太抖。铸师的手，要稳过心跳。稳住了，你铸的东西才有心跳。"],"闲聊":["别碰那柄锤——它今天心情不好。"]};
/* ===== 商人 ===== */
TALK_V56["lv_trade1"]={理念:["账算得精，不如算得久。不赚让人活不下去的钱——灾年不涨价，丰收年不压价，这是我四十年的账。"],"传闻":["灾年粮价，你涨不涨？答错了别来见我。答对了，账上记你一笔。"],"修行":["你的算盘太响，会惊着客。生意要静着做，钱才留得住。"],"闲聊":["这铺子开了四十年，货还是当年的货。你要什么？"]};
TALK_V56["lv_trade2"]={理念:["留一半，给风变卦。我抢过十年，还了三十年——风会变，船不能满。"],"传闻":["南方的海路最近有条新航线，海盗还没摸到。你要出海，走老路，稳。"],"修行":["你的秤还太满。做生意，要留一半。满秤的买卖，做不长。"],"闲聊":["上船？先说好，我的船只载两条路：发财的路，和还债的路。"]};
/* ===== 灵魂法师 ===== */
TALK_V56["lv_soul1"]={理念:["镜子会告诉我，我走这条路是为了看见别人，还是为了逃避自己。我还没准备好听那个答案。"],"传闻":["深渊裂隙那边，最近有回声。不是我的镜子里的。你要小心。"],"修行":["你身上有两道声音。一道很响，一道很轻。你想让我听哪一道？"],"闲聊":["（她侧着身，始终没有正眼看你。）"]};
/* ===== 兽王/隐世/散人 ===== */
TALK_V56["lv_兽王"]={理念:["（一声低沉的咆哮。兽王守的是兽群的规矩，不是人的。）"],"传闻":["（它盯着深渊的方向，喉咙里滚着闷雷一样的怒意。）"],"修行":["（它看了你很久，然后让开了路——这是它能给的最高礼遇。）"],"闲聊":["（它没理你，转身走向领地深处。）"]};
TALK_V56["lv_隐世"]={理念:["（他不说话。传闻说他早就不在了，可强者榜仍有一席。）"],"传闻":["（无。）"],"修行":["（无。）"],"闲聊":["（无。）"]};
TALK_V56["lv_散人"]={理念:["（独臂，不说话。他抬头看了你一眼，又低下头。）"],"传闻":["（无。）"],"修行":["（他伸出那只独臂，比了个「稳」的手势。）"],"闲聊":["（无。）"]};
/* ===== 委托（每传奇 1 条） ===== */
QUEST_V56["lv_mage1"]={title:"替树带一句话",tip:"「银叶城老树下的风声，比信鸽快。你要是去北境，替我问问凯·青焰：那盏灯，亮了吗？」",reward:{reading:""}};
QUEST_V56["lv_mage2"]={title:"寻找奥伦",tip:"「我走不开。你要是遇见一个叫奥伦·星弦的法师，告诉他：塔没塌，就是灯灭了一盏。星徽，还给他留着。」",reward:{reading:""}};
QUEST_V56["lv_mage3"]={title:"旧灯的火",tip:"「听说死亡沙漠深处有一种不灭的火。我出不去——你去看看，它能不能点亮旧灯。」",reward:{reading:""}};
QUEST_V56["lv_mage4"]={title:"林中的脚印",tip:"「结界外的脚印不是兽的。你替我去看看，别惊动它，回来告诉我它往哪走了。」",reward:{reading:""}};
QUEST_V56["lv_mage5"]={title:"那一页空白",tip:"「守望者塔有一页空白卷宗。你去圣城时，替我看看：那一页，有人写字了吗？」",reward:{reading:""}};
QUEST_V56["lv_war1"]={title:"矿道里的响动",tip:"「铁峰堡矿道最近有响动。我走不开，你去看看，回来学给我听——老兄弟们都在等消息。」",reward:{reading:""}};
QUEST_V56["lv_war2"]={title:"旧碑的下落",tip:"「听说北方雪原有一座旧碑，刻着兽人与人类的旧约。你去找找，找到的碑文，抄一份给我。」",reward:{reading:""}};
QUEST_V56["lv_war3"]={title:"关口的一封信",tip:"「铁门关有封军报要送去圣城，给罗兰·白盾。你顺路的话，替我送到——军报不比货物，不能丢。」",reward:{reading:""}};
QUEST_V56["lv_war4"]={title:"守城的账",tip:"「佣兵会有一笔「留给守不住的城」的账，存在老巷铺子。你去取来，路上别让人看见。」",reward:{reading:""}};
QUEST_V56["lv_war5"]={title:"海上的消息",tip:"「南方海盗最近又起来了。你出海的话，替我看看哪条航线还干净，回来告诉我。」",reward:{reading:""}};
QUEST_V56["lv_priest1"]={title:"那本禁书",tip:"「我祷告室有本禁书，读完了。你替我还回它原来的地方——书商巷第三家，夜半敲门。」",reward:{reading:""}};
QUEST_V56["lv_priest2"]={title:"新蜡烛",tip:"「静默殿的蜡烛要换了。你去买三支素烛，放在殿门口就行，别进来。」",reward:{reading:""}};
QUEST_V56["lv_priest3"]={title:"给圣城的信",tip:"「我写给克莱门主教一封信。你送到圣城，亲手给他——内容你别看。」",reward:{reading:""}};
QUEST_V56["lv_thief1"]={title:"还债",tip:"「自由城邦旧钟楼底下，埋着一样我偷了三十年没还回去的东西。你替我取出来，交给钟楼守夜人。」",reward:{reading:""}};
QUEST_V56["lv_thief2"]={title:"雾天的账",tip:"「商路上有笔账，压在雾里。你去码头找一个叫灰鼠的人，报我的名字，他会给你。」",reward:{reading:""}};
QUEST_V56["lv_ranger1"]={title:"追鹿",tip:"「白鹿往北跑了。你替我看看它往哪去了，别追，只看。」",reward:{reading:""}};
QUEST_V56["lv_ranger2"]={title:"深雪区的记号",tip:"「深雪区边缘有个记号，是我留的。你去看看还在不在——在，雪原就还稳。」",reward:{reading:""}};
QUEST_V56["lv_knight1"]={title:"书的护送",tip:"「圣城书商巷有一批书要送去银叶城。你替我护送——书比命贵，至少我是这么信的。」",reward:{reading:""}};
QUEST_V56["lv_knight2"]={title:"平民窟的药",tip:"「平民窟的老医馆缺药。你替我送一批药过去，报我的名字，不用给钱。」",reward:{reading:""}};
QUEST_V56["lv_smith1"]={title:"剑的愿望",tip:"「那把刀说它想变剑。你替我去矿洞找一块老铁——格姆认得那种铁。」",reward:{reading:""}};
QUEST_V56["lv_smith2"]={title:"炉火的信",tip:"「替我送一封信给索林王。信里写的是老铸师最后一句话——我一直没敢亲自去说。」",reward:{reading:""}};
QUEST_V56["lv_trade1"]={title:"人情账",tip:"「老巷铺子有笔「不赚的钱」记在账上。你替我把账上的货送到灾区的粮站，钱我出，别说是我的。」",reward:{reading:""}};
QUEST_V56["lv_trade2"]={title:"还回去的东西",tip:"「我船舱里锁着一批当年抢来的东西。你替我还回去——地址在箱子上，一件一件还。」",reward:{reading:""}};
QUEST_V56["lv_soul1"]={title:"一盏灯",tip:"「深渊裂隙边，有一盏我留的灯。你替我去看看它熄了没有——熄了，就别告诉别人。」",reward:{reading:""}};
QUEST_V56["lv_兽王"]={title:"兽群的委托",tip:"「（它用爪子在地上划出深渊的方向，又划出一条绕过深渊的路。它要你走那条路，替它看看。）」",reward:{reading:""}};
QUEST_V56["lv_隐世"]={title:"（无人委托）",tip:"（他不说话，也不接你的话。）",reward:{reading:""}};
QUEST_V56["lv_散人"]={title:"（无言委托）",tip:"（他看了你很久，递给你半块干粮，然后指了指北方。）",reward:{reading:""}};


/*v56inj:story*/
/* ---- 魔法师 ---- */
N["v56s_mage1_a"]=function(){return{title:"银冠",text:["老树下的风很轻。奥薇恩坐在树根上，指尖转着一片叶子，叶子绕着她的手指转圈，像在陪她。","「你来得正好。」她没抬头，「叶子说，你身上有北地的味道。北地风大，人容易把自己弄丢。」","她把叶子放回树根：「我年轻时打遍北境，赢了每一场该赢的仗。然后我停了——赢太久的人，容易忘了法术是为什么存在的。」","「有人问我为什么不争神座。你猜我怎么答？」"],options:[{t:"「神座只有一把椅子，路有无数条。」",go:"v56s_mage1_b"},{t:"「……你见过神座？」",go:"v56s_mage1_c"}]}};
N["v56s_mage1_b"]=function(){return{title:"银冠",text:["奥薇恩笑了，笑得像叶子转圈：「你倒会抄我的话。」","「神座空着两千年了。星落塔第七层的灯，亮了又熄，没有一盏是为自己点的。法师们把这叫『空座之惑』——不是没人想坐，是没人觉得自己配坐。」","她顿了顿：「寂光陨落前留了一句话：坐上去不难，难的是坐上去之后，你还记得自己是个人。」","「我教了三百年的孩子认元素。你要是哪天也赢了太多，就回来看看这棵树——它不会问你争不争神座，它只问你，累不累。」"],options:[{t:"（向她告辞，回到银叶城）",go:"faction_elf_main"}]}};
N["v56s_mage1_c"]=function(){return{title:"银冠",text:["奥薇恩把玩着那枚银冠，像把玩一枚旧铜钱：「见过。我成神那天，自己为自己戴上的。」","「可我没坐上去。我站在神座前，看见它只容得下一个人——而我身后，还有三千个孩子等着学认元素。」","「神座不会老，孩子会。我选了会老的那边。」","她把银冠收进袖里：「回去吧。北地的风要是太冷，就想想这棵树。」"],options:[{t:"（颔首离去）",go:"faction_elf_main"}]}};
N["v56s_mage2_a"]=function(){return{title:"雾塔",text:["星落塔第七层的风，比楼下更冷。洛·晨雾站在窗边，衣角纹丝不动，像在等风先开口。","「你来得正好。」他说，「帮我看看，这道元素法则，第七层能不能再刻一层。」","他指的是一道刻在窗台上的旧纹路——不是他刻的。纹路很旧，旧得像十二年前。","「奥伦离塔那天，把首席的星徽留在这窗台上。我捡起来，戴上，一戴十二年。」他说这话时，没有看星徽。","「我没资格看它。它本来不属于我。」"],options:[{t:"「那你还戴着？」",go:"v56s_mage2_b"},{t:"「他为什么走？」",go:"v56s_mage2_c"}]}};
N["v56s_mage2_b"]=function(){return{title:"雾塔",text:["洛·晨雾沉默了很久。风从窗缝里挤进来，吹得他衣角终于动了一下。","「戴着，是为了记住：这位置是借的。我替奥伦管着学院，管到他回来——或者管到我确认，他不会回来了。」","「塔里的老执事说，我每年双子星升起的夜里都失眠。他们说得对。我站在观星台，看这枚星徽，像看一道没做完的题。」","他忽然转头看你：「你要是遇见奥伦，告诉他：塔没塌，就是灯灭了一盏。星徽，还给他留着。」"],options:[{t:"「我记下了。」（离开观星台）",go:"academy_elda_hub"}]}};
N["v56s_mage2_c"]=function(){return{title:"雾塔",text:["「他走，是因为在观星台看到了什么东西。」洛·晨雾的声音低下去，「他走那天只说了一句话：『这塔的灯，照不见我要去的地方。』」","「十二年了。我管理着学院的一切，唯独没弄明白他看到了什么。星落塔的灯照不见的地方……我翻遍了所有卷宗，也没有一处记载。」","他抬起手，指腹轻轻擦过那道旧纹路：「有时候我怀疑，他看到的不是外面，是里面——是这枚星徽底下压着的什么东西。」","「你要是查到了什么，回来告诉我。这塔的第七层，永远给你留着窗。」"],options:[{t:"（郑重应下，离开）",go:"academy_elda_hub"}]}};
N["v56s_mage3_a"]=function(){return{title:"青焰",text:["北地的雪原上，凯·青焰蹲在一处熄灭的篝火边，看了很久。火堆里埋着一截焦黑的木，他伸手拨了拨，像在给谁整理衣襟。","「你说，火这种东西，到底是烧完了才算活过，还是亮着才算？」他问，没有抬头。","「那盏旧灯，是村里唯一的东西。全村人轮流添油，说灯不灭，村不亡。东军破村那夜，我抱着灯逃出来，灯熄了。」","他摩挲着腰间那盏熄灭的旧灯：「我成了法师。烧过桥，烧过城，烧过一整支军队。可这盏灯，再没亮过。」"],options:[{t:"「也许它不是在等火，是在等人。」",go:"v56s_mage3_b"},{t:"「让我看看那盏灯。」",go:"v56s_mage3_c"}]}};
N["v56s_mage3_b"]=function(){return{title:"青焰",text:["凯·青焰抬起头。他的眼睛在雪光里显得很淡，像一层冻过的灰。","「等人？」他重复了一遍，声音有点哑，「全村人都死了。我等谁？」","风卷过雪原，把篝火余烬吹散了一些。他把旧灯护在怀里，像护着最后一点热。","「……也许你说得对。我等的人，可能就是那个在火灭之后，还愿意蹲下来看灰烬的人。」","他站起来，把灯挂回腰间：「走吧。雪要大了。你要是路过死亡沙漠，替我问问——那里的火，是不是不灭的。」"],options:[{t:"（点点头，转身走进风雪）",go:"north_tavern"}]}};
N["v56s_mage3_c"]=function(){return{title:"青焰",text:["凯·青焰犹豫了一下，把旧灯从腰间解下来，放在你面前。","灯身是铜的，磨得发亮——那是被手摩挲了无数遍的光泽。灯芯只剩短短一截，焦黑。","「你碰碰看。」他说。","你伸手碰了碰灯芯。指尖传来一点温热，不是火焰的热，是另一种——像有人刚握过它。","「……它还记得。」他收回灯，声音低得几乎听不见，「村灭那夜，我把它抱在怀里跑了三天三夜。它替我挡过一箭。」","「就凭这一点，我欠它一辈子。」"],options:[{t:"（无言，目送他消失在雪里）",go:"north_tavern"}]}};
N["v56s_mage4_a"]=function(){return{title:"银叶",text:["世界树的根下，瑟琳·银冠坐在一片巨大的树根上，怀里抱着一卷发黄的册子。风穿过树冠，她的浅金色眼睛眯了眯。","「你身上有树喜欢的味道。」她把一片树叶递给你，「拿着。树说，你会在树下坐一会儿。」","你接过树叶，在另一条树根上坐下。树皮粗糙，坐着却有种说不出的安稳。","「我二十岁就摸到了传奇的门槛。可我没继续走——我选了结界，选了守树。」她翻开那卷册子，「这里面记着世界树听见的所有秘密。你要听一条吗？」"],options:[{t:"「听。」",go:"v56s_mage4_b"},{t:"「为什么选守树？」",go:"v56s_mage4_c"}]}};
N["v56s_mage4_b"]=function(){return{title:"银叶",text:["瑟琳翻到某一页，指尖点了点一行字。那页的墨迹很淡，像是很多年前写的。","「三千年前，有个法师在世界树下坐了一夜。树听见他念了一整夜的名字——他在背每一个死在他法术下的人。」","「第二天他走了，再没来过。树把那些名字记住了。」她合上册子，「树不评判。它只是记着。谁来过，谁做过什么，树都记着。」","「我守的结界，护的其实不是树——是树记住的那些东西。它们需要一个地方待着，不至于被风刮散。」"],options:[{t:"（沉默良久，把树叶放回树根）",go:"faction_elf_main"}]}};
N["v56s_mage4_c"]=function(){return{title:"银叶",text:["「你们人类总想登顶。」瑟琳笑了笑，声音像风穿过树叶，「我们精灵，只想活得久一点，多听几遍风。」","「奥薇恩老师教过我：赢了太久的人，最容易忘了法术是为什么存在的。树不用赢——它活一万年，本身就是答案。」","她抬手，让一片落叶在你面前转了一圈：「你看，叶子不急着落地。你急什么？」","「去走你的路吧。树会记住你来过——下次路过，它认得你。」"],options:[{t:"（行了一礼，走出结界）",go:"faction_elf_main"}]}};
N["v56s_mage5_a"]=function(){return{title:"灰书",text:["守望者塔的档案室，光线很暗。伊尔·灰书坐在长桌尽头，那卷灰布包着的书摊开在面前，他正往一页空白的纸上写着什么。","「你想看哪一页？」他头也不抬，「先说好，看完要还。」","你走近。桌上摊开的卷宗密密麻麻，全是关于七印的记录——哪一年松了多少，哪一年补了多少，墨迹的颜色深浅不一，横跨几十年。","「第七印，今年松了一寸。」他说，「三千年来，它松了十七次。每一次我都补了档案。」他抬起头，「可你知道最可怕的是什么吗？」"],options:[{t:"「什么？」",go:"v56s_mage5_b"}]}};
N["v56s_mage5_b"]=function(){return{title:"灰书",text:["「最可怕的，是档案越补越厚，可能看懂的人，越来越少。」伊尔·灰书合上那卷灰布书，「这卷书里记着七印的每一次松动，可谁有资格看它？谁敢看它？」","他顿了顿：「守望者内部说，我的卷宗里有一页是空白的——那是留给『将来能彻底封住七印的人』的。我写了三千年，那一页还是空白。」","「你要是想成为那个名字，先别急着问怎么封印。先问自己：你愿意为一件与你无关的、三千年后的事，搭上一辈子吗？」","「想清楚了，再来看这一页。」他把灰布书轻轻推向你，「今晚你可以替我看一夜。」"],options:[{t:"（在档案室坐了一夜，天亮才离开）",go:"event_hub"}]}};
/* ---- 战士 ---- */
N["v56s_war1_a"]=function(){return{title:"铁壁",text:["铁峰堡的城墙上，格罗·铁壁坐在墙垛边，用一块旧布擦盾。盾面上密密麻麻的凹痕，在夕阳里泛着深浅不一的光。","「来，帮我看看，这道新凹痕，够不够深。」他举起盾，指着一道浅浅的印子，「三天前，替一个小姑娘挡的。她非要站在城头看她爹回城——箭来的时候，她没躲。」","「盾这东西，不是用来挡自己的，是用来让别人敢往前走的。」他擦盾的动作很慢，像在给老朋友掸灰。","「这两百年，我挡过三场围城。每道凹痕后面，都站着一个人——他们现在都活得好好的，这才是盾该有的样子。」"],options:[{t:"「你后悔过吗？」",go:"v56s_war1_b"},{t:"「让我看看最深的凹痕。」",go:"v56s_war1_c"}]}};
N["v56s_war1_b"]=function(){return{title:"铁壁",text:["格罗·铁壁沉默了一会儿，把盾立在墙垛边。","「后悔过。塌方那夜，我用自己的背顶住落石，救了整队矿工。可那年我才十六岁，不知道背会疼一辈子。」他拍了拍腰，「现在一到阴雨天，这里就发酸。」","「可我从不后悔拿起盾。你问我后不后悔——不如问我，要是重来一次，我还挡不挡。答案是挡。一万次也是挡。」","他笑了，笑声在城墙上滚得很远：「挡在别人前面，是这世上最划算的买卖。你看我这两百年，换了三百七十二道凹痕，和三百七十二个活人。」"],options:[{t:"（向他行了个战士礼）",go:"city_ironpeak_tavern"}]}};
N["v56s_war1_c"]=function(){return{title:"铁壁",text:["格罗·铁壁把盾转过来。盾心有一道极深的凹痕，几乎贯穿盾面，边缘的金属像被什么咬掉了一块。","「这是第一场围城。铁门关还没修好，北边来人，一夜之间围了城。我用这面盾，在城门洞里顶了三天。」","「盾裂了，人没退。城也没破。」他的手指抚过那道凹痕，「后来铁匠说，这面盾废了，换一面吧。我说不换——它替我挡过的东西，都在上面。」","「凹痕是盾的记性。人活一辈子，总得有点东西替你记着。」"],options:[{t:"（郑重点头，离开城墙）",go:"city_ironpeak_tavern"}]}};
N["v56s_war2_a"]=function(){return{title:"赤峰",text:["草原的篝火边，喀兰·赤峰用刀尖挑着一块烤肉，翻了个面。火苗舔着肉，油脂滴进火里，滋滋响。","「吃。」他递给你一块，「吃饱了，我们聊点比打仗重要的事。」","你接过肉。草原的风很大，吹得火苗东倒西歪，可喀兰坐着，像一棵扎了根的树。","「我在找一块旧碑。碑上刻着兽人和人类第一份和平条约——三千年前的。」他咬了一口肉，「有人把它藏起来了。藏它的人，不想让两个种族想起来：我们也曾好好说过话。」"],options:[{t:"「找到了会怎样？」",go:"v56s_war2_b"},{t:"「我帮你找。」",go:"v56s_war2_c"}]}};
N["v56s_war2_b"]=function(){return{title:"赤峰",text:["「找到了，我就把它重新立起来。」喀兰·赤峰说，「立在草原和人类地界的交界处。让往来的商队都看见：这地界上，不光有刀和血，还有过一纸约定。」","「我成传奇那年，王庭给我立了石像。我让人把石像的脸朝南，对着人类的地界——让他们看看，草原上不是只有仇恨。」","「我屠过村，也守过村。草原上的规矩很简单：你敬狼，狼敬你。人类要是肯先敬草原一步，我就敢用这把刀，替他们挡一夜的狼。」","他撕下一块肉递给你：「你走的地方多。要是听见旧碑的下落，回来告诉我——草原记你的情。」"],options:[{t:"（记下此事，与他对饮）",go:"faction_orc_main"}]}};
N["v56s_war2_c"]=function(){return{title:"赤峰",text:["喀兰·赤峰大笑，笑声惊起一片篝火边的火星。","「好！草原认你！」他解下刀柄上缠着的红布，系在你手腕上，「这是我母亲的头巾。她死在兽人与人类的旧战里——我带着它，是为了不忘记战争长什么样。」","「你要是真能找到旧碑，就把它带回来。带不回来，抄一份碑文也好。」他顿了顿，声音沉下来，「让我母亲那一代人看看：他们没白死，这地界，还能好好说话。」"],options:[{t:"（收下红布，郑重应下）",go:"faction_orc_main"}]}};
N["v56s_war3_a"]=function(){return{title:"长风",text:["铁门关城头，风大得要把人吹跑。秦·长风站在垛口边，左臂的木臂按在城砖上，披风被吹得笔直，像一面活着的旗。","「上来！站这儿看，你才知道什么叫北境！」他朝你吼。","你站到他身边。北境的风灌进衣领，冷得像刀刮。城墙下，商队的灯火蜿蜒向北，像一条缓慢移动的河。","「我十五岁入伍，打过大小四百余仗。断左臂那场，守了铁门关七天七夜——用右手单手使枪。」他拍了拍木臂，「这木臂里刻着北境要塞的地图。我把它带在身上，是因为我答应过它们：我在，它们就在。」"],options:[{t:"「七天七夜……怎么撑下来的？」",go:"v56s_war3_b"},{t:"「木臂里那张纸，写着谁的名字？」",go:"v56s_war3_c"}]}};
N["v56s_war3_b"]=function(){return{title:"长风",text:["秦·长风沉默了一会儿。风把他的披风扯得猎猎响。","「撑下来？不是撑，是熬。第一天靠杀意，第三天靠麻木，第五天靠城墙——你想，你背后是整座城的人，他们都在等你告诉他们：不用逃。」","「第七天，援军到了。我靠在城垛上，手抖得拿不住枪。老兵给我递水，我喝了三口，吐了两口——全是血。」","他笑了笑，笑容在风里很快就散了：「关里的老兵说：那不是七天，是他替整座城，多活了七天。其实我记不清那七天的事了。我只记得，城墙没破。」","「城在，我在。这不是豪言，是账。」"],options:[{t:"（沉默良久，与他并立城头）",go:"north_tavern"}]}};
N["v56s_war3_c"]=function(){return{title:"长风",text:["秦·长风的手按在木臂上，停了一会儿。","「……你问这个，没人敢问。」他低声说，「写着一个女人的名字。她是我断臂那年，在关外收尸的。」","「她把我从尸堆里拖出来，用她的裙子给我包扎。我醒过来问她叫什么，她说：『等你活着守完这座城，我再告诉你。』」","「后来她在东军的一次夜袭里死了。我没来得及问她名字。我托人查了三个月，查到一个——不知道是不是她。」","他拍了拍木臂：「所以我把它刻在木臂里，带着上城头。这样每次守城，我都觉得，她在看着我。」"],options:[{t:"（无言，向他行了一礼）",go:"north_tavern"}]}};
N["v56s_war4_a"]=function(){return{title:"孤山",text:["交汇城的酒馆角落，叶·孤山一个人坐着，面前一壶酒，一只杯。他斟满，没有喝，看着杯沿。","「坐。这杯请你——赌你将来守得住一座城。」他把酒杯推过来。","你坐下。酒馆里人声嘈杂，可这个角落安静得像另一间屋子。","「我三百人的佣兵会，从来不参加聚会。孤山嘛，站得远才看得清。」他自嘲地笑了一下，「守城守久了，就不太会跟人热络了——你习惯了替一城人操心，就忘了怎么替自己高兴。」"],options:[{t:"「为什么不接大单了？」",go:"v56s_war4_b"},{t:"「那笔『留给守不住的城』的账，是真的吗？」",go:"v56s_war4_c"}]}};
N["v56s_war4_b"]=function(){return{title:"孤山",text:["叶·孤山抿了一口酒，慢悠悠地开口。","「不接大单，是因为我见过太多城破了。」他摩挲着杯沿，「大单打的是名声，守城打的是命。一座城破，城里的人不会问你名声多响——他们只会问，你为什么不早点来。」","「我成名于一场围城。那城是自由城邦的卫星城，守军跑了，我带着三百佣兵守了三个月。城没破。」","「从那以后，我只接『守城』的单。而且从不涨价——城守住了，商路就通，商路通了，你们这些骂我傻的人，才有钱付账。」","他朝你举了举杯：「这个道理，你什么时候想通了，什么时候就能守得住一座城。」"],options:[{t:"（举杯回敬）",go:"faction_free_tavern"}]}};
N["v56s_war4_c"]=function(){return{title:"孤山",text:["叶·孤山笑了，笑得有点淡：「你连这个都听说了。」","「是真的。佣金结算时，我总要扣下一成，记在账上，说是『留给守不住的城』。」他指了指酒馆外，「那笔账存在老巷铺子，文森替我管着。他那人，账算得精，也守得住。」","「为什么留这笔钱？因为我知道，总有一座城会在我到之前破掉。我救不了那一座，但至少能让破城之后的人，有钱买口热粥。」","「守城的人，心要凉一点——可凉不是冷。凉，是知道自己救不了所有人，还愿意救下一个。」"],options:[{t:"（记在心里，默默喝酒）",go:"faction_free_tavern"}]}};
N["v56s_war5_a"]=function(){return{title:"断江",text:["南方港城的断江酒馆，罗·断江坐在柜台后，用一块旧布擦一只酒杯。杯子擦得锃亮，像新的。","「坐。今天新到的鱼，很新鲜。」他头也不抬。","你坐下。柜台后的墙上，横着一根房梁，房梁上插着一柄旧枪，枪尖朝海。","「那是我的旧枪。插在那儿二十年了。」他朝房梁努了努嘴，「枪尖朝海——留给将来守海的人。」","「年轻的时候，一人一枪，拦过一条满载海盗的江船。本可以封侯拜将，可我退役了。打够了，就该过自己的日子。」"],options:[{t:"「打够了……是种什么感觉？」",go:"v56s_war5_b"},{t:"「那柄枪，还会有人拔下来用吗？」",go:"v56s_war5_c"}]}};
N["v56s_war5_b"]=function(){return{title:"断江",text:["罗·断江放下杯子，想了一会儿。","「打够了，就是你半夜醒来，不用先摸枕头底下的刀了。」他给自己倒了杯酒，「我拦江那夜之后，整整十年，睡觉都是睁一只眼的。」","「后来我开了这酒馆。第一天打烊，我躺下，一觉睡到天亮——那是我这辈子睡得最沉的一觉。」","「神座那张椅子，不如我酒馆里的旧木凳坐着舒服。有人觉得我是可惜了，可我知道：我能一觉睡到天亮，这比什么传奇都值。」","他给你也倒了一杯：「你要是哪天也打累了，来这儿坐坐。鱼管够。」"],options:[{t:"（与他碰杯，听了一夜海风）",go:"city_nanfang_tavern"}]}};
N["v56s_war5_c"]=function(){return{title:"断江",text:["罗·断江抬头看了看房梁上的旧枪，目光很平静。","「会。总会有人把它拔下来的。」他说，「这世上的海，总有人要守。我守不动了，自然有年轻人来。」","「我留着那柄枪，不是念旧——是给后来人留个念想：你看，有人在这儿守过二十年，你也可以。」","「南方的传奇只有两位，我是最不『传奇』的那位。可酒馆里的水手都叫我一声『断江爷』——这个名号，我比当传奇听得舒坦。」"],options:[{t:"（点点头，记下这个约定）",go:"city_nanfang_tavern"}]}};
/* ---- 牧师 ---- */
N["v56s_priest1_a"]=function(){return{title:"圣言",text:["大教堂的回廊里，克莱门·圣言站在一扇彩窗前，光线透过玻璃落在他脸上，半明半暗。","「你身上有犹豫的味道。来，跟我说说，你在犹豫什么。」","你斟酌了一下：「犹豫……是不是所有坚持，都要付出代价。」","克莱门没有立刻回答。他看了那扇彩窗很久，窗上的圣像在光里沉默。","「我主持过三次大公会议，每一次都让教会内部的裂痕更深——又更稳。」他终于开口，「我主张净化令，可我也偷偷救过被净化令收缴的书商。你问我犹豫什么？我每天都在犹豫。」"],options:[{t:"「那你还怎么走下去？」",go:"v56s_priest1_b"},{t:"「你救书商的事，是真的？」",go:"v56s_priest1_c"}]}};
N["v56s_priest1_b"]=function(){return{title:"圣言",text:["克莱门·圣言轻轻笑了一下，笑意没有到眼睛里。","「走下去，不是因为不犹豫，是因为犹豫也得有个方向。」他转过身，「圣光是唯一的路——这句话我说了几十年，可我比谁都清楚，走这条路的人，脚下沾着泥。」","「我信圣光，也信泥。泥里埋着那些被净化令碾碎的人，他们也是圣光照过的地方。」","「枢机院的人觉得我是最矛盾的一个。可我知道，正是因为我矛盾，净化令才没有走到最黑的那一步。」他顿了顿，「矛盾，有时候是神给人留的刹车。」"],options:[{t:"（沉默许久，行了一礼）",go:"faction_church_main"}]}};
N["v56s_priest1_c"]=function(){return{title:"圣言",text:["克莱门·圣言沉默了一会儿，从袖中取出一本书。封面被摩挲得发旧，边角卷起。","「是真的。这本书，是书商巷第三家的。净化令收缴的书，本该送去焚毁——我留下了它。」","「每晚读一页，然后向神忏悔。可忏悔什么呢？忏悔我救了一本书？还是忏悔我没能救下更多？」","他把书放回袖中：「我主张净化令，是因为我相信圣光是唯一的路；我救书商，是因为我见过书里写的东西——有些话，不该被火吞掉。」","「这两件事在我心里打架，打了二十年。但我不后悔。因为如果我哪一天不矛盾了，那才是我真正背叛圣光的时候。」"],options:[{t:"（无言，退出了回廊）",go:"faction_church_main"}]}};
N["v56s_priest2_a"]=function(){return{title:"静烛",text:["静默殿的烛光很暗，暗到只能照见玛格达·静烛的半张脸。她的眼睛在黑暗里待得太久，见不得强光，说话的声音轻得像怕惊动什么。","「你来了。坐吧，这里没有神，只有夜。」","你在烛光边坐下。殿里很静，静到能听见烛芯燃烧的细响。","「我十二岁进静默殿，守了三百年夜。我的蜡烛从没熄灭过——不是守得好，是这殿里的夜，怕我。」她轻轻说，「教会要升我当大主教，我拒绝了。我走了，谁来替神守这段最黑的光？」"],options:[{t:"「最黑的光……是什么？」",go:"v56s_priest2_b"},{t:"「那支蜡烛，为什么用头发搓芯？」",go:"v56s_priest2_c"}]}};
N["v56s_priest2_b"]=function(){return{title:"静烛",text:["玛格达·静烛看着烛火，火光在她眼里跳了一下。","「太阳升起前那段最黑的光。」她说，「圣临——就是现在教会拜的那位神——成神前，是静默殿的守夜人。他守了三百年夜，没见过太阳升起。他守的，就是这段光。」","「他成神那天，晨祷的钟没敲。他推开静默殿的门，站在晨光里说：我不用再守夜了。」","「他走了，可夜还在。总得有人接着守。」她伸手，轻轻拢了拢烛火，「三百年了，我守着这段黑——不是等他回来，是替所有还在夜里的人，把这段黑守过去。」"],options:[{t:"（在静默殿坐了一夜，没有惊动任何人）",go:"faction_church_main"}]}};
N["v56s_priest2_c"]=function(){return{title:"静烛",text:["玛格达·静烛的手停在烛台上，很久没有说话。","「……你连这个都听说了。」她的声音更轻了，「那芯，是用初代守夜人的头发搓的。她是圣临的未婚妻。」","「圣临守夜三百年，她等了他三百年。他成神那天，没有带她走。她后来老死在静默殿的侧屋——临终前，把头发留给了我。」","「她说：『替我看着他守的这段夜。要是他哪天回来，告诉他，我一直在。』」","「圣临没有回来过。三千年了，没有回来过。可我还是守着这烛——替她等，也替夜等。」"],options:[{t:"（沉默良久，轻轻退出了静默殿）",go:"faction_church_main"}]}};
N["v56s_priest3_a"]=function(){return{title:"银冠",text:["银叶城的小教堂门口，艾诺尔·银冠正在给门口的一盏油灯添油。教堂很小，可收拾得很干净。","「进来吧，这盏灯，是替两种族的黑暗点的。」她笑了笑。","你走进教堂。里面供奉着一尊神像——面容是精灵的，却穿着人类牧师的袍子。","「我是在圣城长大的精灵。养父母是圣城的牧师。我见过教会最好的一面，也见过最坏的一面。」她看着那尊神像，「所以我回来，建了这座小教堂。只有精灵会来——但灯，是对所有人点的。」"],options:[{t:"「这尊神像……为什么是精灵面容？」",go:"v56s_priest3_b"}]}};
N["v56s_priest3_b"]=function(){return{title:"银冠",text:["艾诺尔·银冠看着那尊神像，目光温和。","「因为只有我能看见神像的表情。」她轻声说，「我雕它的时候，照着两族的记忆雕的——让精灵看见亲切，让人类看见熟悉。」","「神不分种族，黑暗也不分。可信徒是人，人需要一张看得懂的脸。」她顿了顿，「我在圣城见过教会用净化令烧掉别人的信仰。我不想银叶城也变成那样——所以我让神，先长出一张精灵的脸。」","「有一天，要是两族能坐在同一盏灯下做祈祷——那这尊像，就可以换回原来的样子了。」她笑了笑，「我等着那一天。」"],options:[{t:"（在教堂里坐了一会儿，替她点了灯）",go:"faction_elf_main"}]}};
/* ---- 盗贼 ---- */
N["v56s_thief1_a"]=function(){return{title:"夜枭",text:["暗巷的阴影里，传来一个声音，听不出方位：「跟着光走的人，看不见我。说吧，你找我，是想偷什么，还是想还什么？」","你站定：「……想听一个故事。」","阴影沉默了一会儿。然后，半扇门开了一道缝，门缝里透出一点光，照见一只手——指节很长，指甲修剪得很干净。","「故事？」那声音里带了一点极淡的笑意，「我偷了一辈子东西，还没人敢来向我讨故事。坐吧——隔着这道门，我讲给你听。」"],options:[{t:"「你接任阁主那天，杀了前一任？」",go:"v56s_thief1_b"},{t:"「旧钟楼底下埋着什么？」",go:"v56s_thief1_c"}]}};
N["v56s_thief1_b"]=function(){return{title:"夜枭",text:["门缝里的光晃了一下。","「对。这是暗影阁的规矩：阁主之位，从来不是传的，是抢的。我杀了前一任，坐上那把椅子。」那声音顿了顿，「可坐上之后，我做的第一件事，是封了暗影阁最深的库房。」","「里面堆着历代阁主偷来的『不该偷的东西』。王冠、国玺、信件、还有……人心。」他说，「这些东西太重了。历任阁主都把它锁着，假装不存在。」","「我说：这些是债，要还。从那以后，暗影阁不再是『偷』，是『收债还债』。」他轻轻笑了一声，「你可能觉得我虚伪——可一个连自己偷的东西都不敢还的人，没资格当阁主。」"],options:[{t:"（门缝后的光灭了，你知道他走了）",go:"faction_free_tavern"}]}};
N["v56s_thief1_c"]=function(){return{title:"夜枭",text:["门缝后的声音沉下去：「……你连这个都知道。」","「旧钟楼底下，埋着一件我偷了三十年都没能还回去的东西。每年除夕，我都会去一趟，站在钟楼下，想一想。」","「那是我年轻时偷的——从一个死人身上。他临死前攥着它，攥得很紧。我掰开他的手拿走了。三十年来，我查遍了所有线索，找不到它该还的地方。」","「它没有主人了。可它不该在我手里。」他说，「你要是能替我找到它该回的地方，钟楼底下的门，会为你开一次。」"],options:[{t:"（记下此事，退出暗巷）",go:"faction_free_tavern"}]}};
N["v56s_thief2_a"]=function(){return{title:"灰雾",text:["商队的马车边，薇·灰雾坐在车辕上，晃着腿。她的影子在夕阳下拉得很长——长到有点不自然。","「听说你在找一个『不存在的人』？巧了，我认识一个。」她笑吟吟地说。","你看着她。她伸了个懒腰，影子跟着晃了晃：「我白天是行商，晚上是灰雾。两个世界都不愿说的话，我都愿意偷来卖。」","「我成传奇那天，两个世界都沉默了——他们都不承认我，可他们都怕我。」她眨眨眼，「你知道这叫什么吗？这叫活得自由。」"],options:[{t:"「影子为什么比人长？」",go:"v56s_thief2_b"},{t:"「你卖消息，卖到什么为止？」",go:"v56s_thief2_c"}]}};
N["v56s_thief2_b"]=function(){return{title:"灰雾",text:["薇·灰雾看了看自己的影子，笑得像在讲别人的事。","「混血的代价，也是混血的礼物。我一半精灵，一半人类——精灵说我半调子，人类说我是杂种。」她晃了晃脚，「影子比人长，是因为我走在两个世界之间，两个世界的光，都只照我一半。」","「可你知道吗？正因为我两半都照不全，我才能看见两个世界都看不见的东西。」她压低声音，「比如，精灵议会不想让人知道的事，和人类教会不想让精灵知道的事——它们在我这儿，是同一笔买卖。」","「影子长，路就宽。我不恨它。」"],options:[{t:"（若有所思，与她道别）",go:"faction_free_tavern"}]}};
N["v56s_thief2_c"]=function(){return{title:"灰雾",text:["薇·灰雾收起笑，认真了一瞬。","「卖消息卖到什么为止？卖到它伤人的时候为止。」她说，「我偷过皇冠，偷过国玺，偷过人心——可我有一条底线：不卖会让一个活人送命的消息。」","「做我这一行，什么都能标价，只有一样不行：人命。」她顿了顿，「这规矩，是从一个差点害死我的人身上学会的。」","「你要是哪天听到有人用我的名头卖要命的消息——那人不是我。你替我戳穿他。」"],options:[{t:"（郑重应下，她笑着朝你挥挥手）",go:"faction_free_tavern"}]}};
/* ---- 游侠 ---- */
N["v56s_ranger1_a"]=function(){return{title:"逐风",text:["林间小路上，艾琳·逐风靠着一棵树，手里折了一片叶子，放在唇边，吹出一个很短的调子。林子里，有什么东西回应了一声。","「赶路？正好，我也赶路。」她收起叶子，笑了一下。","你与她并肩走了一段。她的弓背在背上，弓身是活的——世界树枝条做的，会自己调整弦的松紧。","「我年轻时追过一只白鹿，追了整整一年。追过山，追过河，追到世界树脚下，白鹿不见了——树根下坐着一个老人，是初代林语者留下的一缕记忆。」她边走边说，「老人说：你追的不是鹿，是路。」"],options:[{t:"「后来呢？」",go:"v56s_ranger1_b"},{t:"「那只鹿，还在追吗？」",go:"v56s_ranger1_c"}]}};
N["v56s_ranger1_b"]=function(){return{title:"逐风",text:["艾琳·逐风踩着落叶，脚步很轻，像怕惊动路。","「后来，我不再追猎物了。我追路。」她说，「成了大巡守，可我一年里有一半时间不在巡守所——我在路上。」","「林子里的巡守笑我：大巡守不巡林，天天走路。可我知道，路才是林子的血脉。你守着路，林子自己会守着自己。」","「初代林语者走遍了所有森林，把双叶之环留在世界树顶。她没有成神——她说：路比神座长。神座只有一把椅子，路有无数条。」","她停下来，回头看你：「你要是有空，也走一条没人走的路试试。你会发现，路会认你。」"],options:[{t:"（向她告别，走上林间岔路）",go:"faction_elf_main"}]}};
N["v56s_ranger1_c"]=function(){return{title:"逐风",text:["艾琳·逐风笑了，笑得像风吹过树梢。","「还在追。那只白鹿是林语者留给我的一道题。」她说，「我追了三百年的那只鹿——它每跑一段，我就多懂一段路。它其实不是在躲我，是在带我认路。」","「有人说我傻，追一只追不上的鹿。可我知道，等哪天我追上它了，我就该停下不追了——那才是真的没路可走了。」","「追着，就说明还有路。多好。」"],options:[{t:"（会心一笑，与她分道）",go:"faction_elf_main"}]}};
N["v56s_ranger2_a"]=function(){return{title:"断弓",text:["雪原的避风处，一堆火正旺。贺·断弓坐在火边，弓横在膝上。弓断了一截，用兽皮缠着。","「吃点。雪原不认生人，认味道。」他递过来一块干肉。","你接过干肉坐下。火光把他的脸照得半明半暗。","「我这弓，断了十二年。用兽皮缠着，照样能打。」他拍了拍断处，「弓断了还能打——这是北方猎人的老话。人也是一样，断了胳膊，还能活。」"],options:[{t:"「你打的是什么猎物？」",go:"v56s_ranger2_b"},{t:"「背囊里那根弓弦，是留给谁的？」",go:"v56s_ranger2_c"}]}};
N["v56s_ranger2_b"]=function(){return{title:"断弓",text:["贺·断弓往火里添了根柴，火苗窜了窜。","「打那些『不该存在』的猎物。」他说，「雪原深处的东西，有些不是野兽。它们从深渊那边过来，在雪下头爬，专挑落单的商队。」","「我原是镇北军的斥候。那场仗里，弓断了，我用半截弓捅死了三个追兵，救了整支斥候队。战后我退役，进了雪原——因为我见过那些东西。别人不认，我认。」","「断弓打不了远的，可打这些爬的、钻的，够用了。」他拍了拍弓，「雪原上的人都知道：看见断弓的火，就绕开走——那火边上，多半有不干净的东西。」"],options:[{t:"（坐在火边，替他守了一夜）",go:"north_tavern"}]}};
N["v56s_ranger2_c"]=function(){return{title:"断弓",text:["贺·断弓沉默了一会儿。他解开背囊，取出一根完整的弓弦——绷得很直，保养得很好。","「这根弦，是我留着等『最后一仗』用的。」他说，「等雪原底下那东西真正爬出来的那天，这根弦会装回弓上。断弓换新弦，打最后一仗。」","「打完那仗，我就退役，找个地方烤一辈子火。」他顿了顿，「要是没打完——这根弦就留给你。你拿着它，替我打。」","「雪原的猎人都知道：断弓的弦，从来不借人。你是第一个。」"],options:[{t:"（郑重收下这个承诺）",go:"north_tavern"}]}};
/* ---- 骑士 ---- */
N["v56s_knight1_a"]=function(){return{title:"白盾",text:["圣城城门，罗兰·白盾立在门洞中央，盾立在地上。盾面雪白，没有一丝划痕。","「你要进城？先回答我——你进城，是想改变它，还是想利用它？」","你看着他，又看了看那面白盾。盾面干净得不像用过，可你知道，他守了圣城三十年。","「白，是因为我挡下的东西，都不配留在上面。」他顺着你的目光，说了一句，「我每次战斗后，都把它重新漆成白色。」","「三十年了。净化令最凶那几年，我挡在书商面前，也挡在执事面前——我挡的是『不问青红皂白』。」"],options:[{t:"「累吗？」",go:"v56s_knight1_b"},{t:"「盾上真的没有划痕？」",go:"v56s_knight1_c"}]}};
N["v56s_knight1_b"]=function(){return{title:"白盾",text:["罗兰·白盾低头看着盾面，沉默了一会儿。","「累。可累也得站着。」他说，「我接任团长那年，圣城正乱。我立下骑士团三百年来第一条新誓约：团长之盾，永不后退。」","「三十年，我挡过净化令的刀，挡过北境的箭，挡过自己人的质疑。每次收队，我都要站在这城门口，看着进出的人——看他们脸上有没有『怕』字。」","「有怕，就说明我还没挡够。没有怕，我才能回去睡个觉。」他抬起头，「累不是问题。问题是，你累的时候，身后有没有人替你撑着。」","「这三十年，我一直撑着。因为城里的老百姓，没有第二面盾。」"],options:[{t:"（深深行了一礼，走进城门）",go:"faction_church_main"}]}};
N["v56s_knight1_c"]=function(){return{title:"白盾",text:["罗兰·白盾把盾转过来，对着光。盾面确实光滑，但你要是凑近看，能看到极浅的、几乎看不见的擦痕——被一层又一层的白漆盖住了。","「没有划痕？你仔细看。」他说，「有。只是都被我漆掉了。」","「挡下一刀，漆一遍。挡下一箭，漆一遍。三十年，我数不清漆了多少遍。」他顿了顿，「有人问我为什么不换面新盾——因为换一面，就忘了那些该记住的。」","「白，不是干净。是我把每一次挡下的东西，都记在心里，然后告诉自己：该翻篇了。」他拍了拍盾，「这面盾不记仇。它只记着，还有人需要它站着。」"],options:[{t:"（无言，向他颔首）",go:"faction_church_main"}]}};
N["v56s_knight2_a"]=function(){return{title:"晨辉",text:["晨曦圣殿门口，伊莎·晨辉正在系马鞍。她的铠甲上缀着两个徽记——圣辉教会的，和骑士团的。","「来吧。我正好要去劝枢机院，你陪我走一段。」她解下头盔，露出一头短发。","你跟上她的马。圣城的街道上，行人见了她，有的行礼，有的侧目。","「两边都戴，两边都劝。」她指了指胸前的两个徽记，「我出身圣城平民窟，见过教会的善，也见过教会的恶。所以我立誓：我的剑，只守『值得守』的东西。」"],options:[{t:"「『值得守』怎么判断？」",go:"v56s_knight2_b"},{t:"「铠甲内侧刻着的名字，是谁？」",go:"v56s_knight2_c"}]}};
N["v56s_knight2_b"]=function(){return{title:"晨辉",text:["伊莎·晨辉勒了勒马，让马慢下来。","「判断『值得守』——不看教义，看人。」她说，「我在平民窟长大。教会说净化异端是对的，可我知道，被净化的书商里，有人是替我邻居看病的大夫。」","「所以我立誓的时候，加了一条：我的剑，只守值得守的东西。谁来劝我『这是命令』，我就问他：你见过那个人吗？他家里有孩子吗？」","「枢机院的人说我不好管。可我知道，正是因为我『不好管』，净化令的刀，才慢了那么几次。」她笑了一下，「慢一次，可能就多救一家人。」"],options:[{t:"（与她并肩走到枢机院门口）",go:"faction_church_main"}]}};
N["v56s_knight2_c"]=function(){return{title:"晨辉",text:["伊莎·晨辉沉默了一下。马蹄踏在石板路上，哒哒地响。","「铠甲内侧刻着的名字……是我在平民窟时的邻居。」她说，「她是个裁缝，死在了第一次净化令里。罪名是窝藏一本『禁书』——其实那本书，是我塞给她的。」","「那年我十四岁。我想让她看看书里写的东西，让她知道我为什么相信『值得守』。净化令来的时候，她没供出我。」","「她死的时候，我的剑还在鞘里。」她低下头，「所以我把她的名字刻在铠甲内侧——每次穿甲，都提醒自己：我的剑，要快过下一场净化令。」"],options:[{t:"（沉默地陪她走完了整条街）",go:"faction_church_main"}]}};
/* ---- 术士 ---- */
N["v56s_smith1_a"]=function(){return{title:"符文",text:["锻造公会的炉边，格朗·符文盘腿坐着，手里那把像刻刀的小锤子在铁坯上轻轻敲着。他每敲一下，都要停一停，像在听铁说话。","「来，帮我看看这把刀——它说它想变剑。」他头也不抬。","你凑近。那把刀坯躺在铁砧上，刃口已经被敲出了形状，但刀身的弧度，确实隐隐偏向剑的线条。","「铁有纹理。你摸到它的纹理，它就把心事说给你听。」他放下锤子，「我年轻时是矿道里最笨的矿工——别人一天挖十车，我一天挖一车，因为我每挖一块石头，都要看看它的纹理。」"],options:[{t:"「铁会说话吗？」",go:"v56s_smith1_b"},{t:"「你听见过初火的声音吗？」",go:"v56s_smith1_c"}]}};
N["v56s_smith1_b"]=function(){return{title:"符文",text:["格朗·符文笑了，笑得像炉火一样温吞。","「铁不说话。它只显纹理——哪里密，哪里疏，哪里受过伤。你读懂了纹理，就听懂了它的话。」他拿起铁坯，「这把刀，它的纹理一直往剑的方向走。它不是想变剑——是它本来该是剑，被打岔成了刀。」","「我做符文，就是把纹理里本来藏着的东西，用符文引出来。让铁自己记住该怎么做。」他顿了顿，「人也是一样。你心里本来就有纹理，只是被生活打岔了。找回来，就是你的『符文』。」"],options:[{t:"（看着那把渐渐成形的剑，若有所思）",go:"city_ironpeak_tavern"}]}};
N["v56s_smith1_c"]=function(){return{title:"符文",text:["格朗·符文停下锤子，看着炉火，看了很久。","「听见过一次。」他说，「我在初火熔炉前站了三百年，听火说了一句话。」","「那句话是：『你不是在打铁，是在把自己打进去。』」他指了指那把铁坯，「我打了三百年铁，每一件兵器里，都有一小块我。铁替我记着，我这一辈子是怎么熬过来的。」","「索林王守初火熔炉，说铸把火留给他，是让他看着炉子。我看炉子看了三百年——看着看着，就把自己看进去了。」","他重新拿起锤子，敲了一下：「你要是在这行待久了，也会明白：造物，是造物者自己的镜子。」"],options:[{t:"（在炉边站了很久，看着他打完那柄剑）",go:"city_ironpeak_tavern"}]}};
N["v56s_smith2_a"]=function(){return{title:"炽芯",text:["工坊里，炉火映着梅·炽芯的脸。她正对着一柄锤子说话，语气像哄孩子：「你今天心情不好？那就歇歇，我不怪你。」","锤子自己跳回了架子上。她回头看你，一点也不意外：「你来了。别碰那柄锤——它今天心情不好。」","「我铸的东西会『活』。不是傀儡术——是造物自己有了脾气。」她走到炉边，添了块炭，「这炉火，是老铸师留给我的。他死前，把一生的心血凝成一颗炽芯，放进我的胸膛。」","「我从此能感觉到铁的『心跳』。」她按了按胸口，「你说，这是福气，还是债？」"],options:[{t:"「债……怎么说？」",go:"v56s_smith2_b"},{t:"「那柄无刃的剑，是给谁的？」",go:"v56s_smith2_c"}]}};
N["v56s_smith2_b"]=function(){return{title:"炽芯",text:["梅·炽芯往炉里添了块炭，火苗蹿了蹿，映得她的眼睛发亮。","「老铸师把火传给我，是把一辈子的心血交到我手里。这份情，我怎么还？」她轻声说，「我成首席铸师那天，给老铸师的坟前铸了一柄无刃的剑——我说，这是给『不会打铁的人』的。」","「他打了一辈子铁，从没给自己打过一样东西。那柄无刃的剑，是替我谢他：谢谢你让我听见铁的心跳。」","「债这个东西，还的方式有很多种。我选了把这份火，传下去——就像他传给我一样。」她看着炉火，「炽芯不是我的。是借我的。总有一天，我要再把它交出去。」"],options:[{t:"（沉默地站在炉边，替她看了一会儿火）",go:"city_ironpeak_tavern"}]}};
N["v56s_smith2_c"]=function(){return{title:"炽芯",text:["梅·炽芯的手指抚过炉沿，声音轻了一点。","「那柄无刃的剑……是给老铸师的。」她说，「他这辈子，只会打铁，不会别的。他走的时候，我把一生的火传给他——不，是他把火传给了我。」","「我成首席那天，在坟前烧了那柄剑。没有刃，烧起来干干净净的。」她顿了顿，「有人问我为什么不铸一把好剑给他陪葬。我说：他一辈子替别人打铁，那把没刃的，是替他打的——不用上战场，不用杀人，就干干净净地，是他自己的。」","「他打了一辈子铁，总该有一件，是只属于他自己的。」"],options:[{t:"（陪她在炉边坐到火暗下去）",go:"city_ironpeak_tavern"}]}};
/* ---- 商人 ---- */
N["v56s_trade1_a"]=function(){return{title:"金秤",text:["老巷的铺子里，文森·金秤坐在柜台后拨算盘。铺子不大，货架上摆着些寻常东西，没有一件是贵的。","「想学做生意？先回答我——灾年粮价，你涨不涨？」他头也不抬。","你想了想：「……不涨。」","文森终于抬起头，看了你一眼。他放下算盘，从柜台下摸出两只杯子，倒了两杯茶：「坐。」"],options:[{t:"「答对了？」",go:"v56s_trade1_b"},{t:"「你那本『人情账』，记的是什么？」",go:"v56s_trade1_c"}]}};
N["v56s_trade1_b"]=function(){return{title:"金秤",text:["文森·金秤把茶推给你，自己端了一杯。","「答对了。至少这一题对。」他说，「我做了四十年生意，只有一条规矩：不赚『让人活不下去』的钱。灾年不涨价，丰收年不压价。」","「别人笑我傻。他们说，灾年粮价翻三倍，你守着平价，一年少赚一座金山。」他喝了一口茶，「我说：账算得精，不如算得久。你今年赚了灾民的血汗钱，明年灾民穷了，你的粮卖给谁？」","「做生意的最高境界，不是把账算到最后一文钱，是把账算到十年后还平。」他放下杯子，「我成了总会长，大陆一半的物价我点头才算——可我的铺子，还开在当年那条巷子里，卖的还是当年的货。」"],options:[{t:"（接过茶，敬了他一杯）",go:"faction_free_tavern"}]}};
N["v56s_trade1_c"]=function(){return{title:"金秤",text:["文森·金秤放下茶杯，从柜台下摸出一本旧账本。账本封皮磨得发白，像被翻了无数遍。","「这上面记的不是钱，是人情。」他翻开一页，「你看——『春三月，粮价平，让利三成，给城东王婆。她家小子要去考学。』」","「每一笔『不赚的钱』，都记在另一页上。等有一天，那些受过我让利的人站稳了，他们会回来——也许不是还钱，是还一份情。」他合上账本，「账算得精，不如算得久。人情账，就是最长的账。」","「我做了四十年生意，攒下的最大一笔财富，不是金衡商会的家底——是这本账。它比什么都值钱。」"],options:[{t:"（看着那本账本，久久无言）",go:"faction_free_tavern"}]}};
N["v56s_trade2_a"]=function(){return{title:"半帆",text:["南方港口的船头，洛佩斯·半帆站在甲板上，海风吹得他眯起眼。他的船队只挂半帆——船帆半张着，像留了一手。","「上船？先说好，我的船，只载两条路：发财的路，和还债的路。」他笑了笑，拍了拍船舷。","你跳上甲板。船舷的木板上，刻着密密麻麻的记号——有些是正字，有些是叉。","「我年轻时是海盗，抢了十年。然后上岸，用抢来的第一桶金买了第一条船，开始做生意。」他说，「做生意和当海盗一样狠——但有一条：不劫商船，不抢妇孺。」"],options:[{t:"「船舱里那间锁着的房间，装的是什么？」",go:"v56s_trade2_b"},{t:"「为什么只挂半帆？」",go:"v56s_trade2_c"}]}};
N["v56s_trade2_b"]=function(){return{title:"半帆",text:["洛佩斯·半帆沉默了一会儿。海风把他的胡子吹得微微颤动。","「那间房里，堆着我当年抢来的、又一件件还回去的东西。」他说，「我抢了十年，还了三十年。那间房，现在还空着一半——等我死前，要把另一半也还完。」","「有人问我：你当年抢的东西，大多不知道主人是谁了，怎么还？」他顿了顿，「我把它们一件件摆出来，托各地的商队打听。打听到一个，还一个。还到没人认领的，就捐给港口的老兵堂。」","「抢来的东西，迟早要还。还完了，海风才敢放心吹我的帆。」"],options:[{t:"（看着那扇锁着的门，点了点头）",go:"city_nanfang_tavern"}]}};
N["v56s_trade2_c"]=function(){return{title:"半帆",text:["洛佩斯·半帆抬头看了看船帆，目光里有种老水手才有的平静。","「挂半帆，是因为风会变，船不能满。」他说，「我抢了十年，最怕的就是『满』。满帆的船，遇到变风，想收都来不及。」","「做生意也一样。你赚得满盆满钵的时候，最危险——因为你看不见风在变。留一半，是给自己留收帆的余地。」","「我成了南方船王，可我的船，不管顺风逆风，永远只挂半帆。水手们笑我，说这是富贵病。」他笑了笑，「他们不懂。我这一辈子，就是靠『留一半』活下来的。」"],options:[{t:"（在船头站了一会儿，看他的船队出海）",go:"city_nanfang_tavern"}]}};
/* ---- 灵魂法师 ---- */
N["v56s_soul1_a"]=function(){return{title:"梦墟",text:["回音室门口，澜·梦墟侧着身站着，没有正眼看你。她的眼睛是雾色的，像隔着一层梦。","「你身上有两道声音。一道很响，一道很轻。你想让我听哪一道？」","你站在原地，没有答话。她等了一会儿，又说：「响的那道，是你想让人听见的。轻的那道，是你自己都还没听见的。」","「我守回音之镜九十年，见过镜子里所有人的另一面——唯独没见过自己的。因为我从不照镜子。」她顿了顿，「镜子会告诉我，我走这条路，是为了看见别人，还是为了逃避自己。我还没准备好听那个答案。」"],options:[{t:"「你害怕那个答案？」",go:"v56s_soul1_b"},{t:"「镜子……能看见什么？」",go:"v56s_soul1_c"}]}};
N["v56s_soul1_b"]=function(){return{title:"梦墟",text:["澜·梦墟沉默了很久。回音室里很静，静到能听见自己的心跳。","「怕。怕得很。」她的声音很轻，「我生下来就看不见『表面』，只能看见人的『另一面』。所以我从不敢看任何人超过一炷香——因为看得越久，越发现，人心里最深的那个答案，往往不是他们想成为的样子。」","「我怕镜子告诉我：我守镜九十年，不是想看见别人，是不敢看见自己。」她终于说，「我怕那个答案，比怕深渊还怕。」","「奥雷利安老师说得对：灵魂法师的道，是先把自己看穿，再看别人。我把自己看了九十年，还没看穿。」"],options:[{t:"（轻轻退出了回音室）",go:"faction_church_main"}]}};
N["v56s_soul1_c"]=function(){return{title:"梦墟",text:["澜·梦墟抬起手，指向前方：「那面镜子，就在回音室正中。它照出的，永远是问镜者自己没听见的那句话。」","「三千年来，它没有碎过。因为每个人站到镜前，听见自己那句话之后，都吓得后退了——镜子替他们承受了那句话的重量。」","「只有奥雷利安老师，他在镜前站了一夜，然后说：『我还没把自己看透。看透自己的那天，就是我坐上去的那天。』他没有碎，镜子也没有碎。」","「你要是哪天准备好了，可以去照一次。但记住——镜子不会说谎。它只会告诉你，你一直在逃避的那句话。」"],options:[{t:"（在回音室门口站了一会儿，终究没有推门）",go:"faction_church_main"}]}};
N["v56s_soul1_d"]=function(){return{title:"梦墟",text:["你转身要走的时候，澜·梦墟忽然叫住了你。","「等等。」她侧着身，雾色的眼睛看着虚空，「你身上那道轻的声音……它在说：『我怕的不是死，是没人记得我来过。』」","你僵住了。","「我不问你怎么知道的。」她轻轻说，「我只告诉你——镜子不会说谎，但它也不会审判。你怕的那句话，说出来，就轻了一半。」","她终于第一次正眼看了你一次，雾眼眨了眨：「你的另一面，不太坏。」"],options:[{t:"（向她点了点头，走出回音室）",go:"faction_church_main"}]}};
/* ---- 兽王/隐世/散人 ---- */
N["v56s_beast1_a"]=function(){return{title:"兽王",text:["大陆深处的密林里，你循着巨大的足迹，走到一处被踩平的谷地。一头巨兽卧在那里——鬃毛如铁，眼瞳是熔金一样的颜色。","它看了你很久。你感觉那目光不是在衡量你的实力，而是在闻你身上的味道。","「（低沉的咆哮。它用爪子在地上划出深渊的方向，又划出一条绕过深渊的路。）」","它要你走那条路。它不开口，但你看懂了：它守这片林子，就像你守你心里那点东西——守得久了，就懂了谁该放行，谁该拦下。"],options:[{t:"（朝它行了一礼，沿它指的路离去）",go:"faction_elf_main"}]}};
N["v56s_hermit_a"]=function(){return{title:"灰袍",text:["你在一处废弃的渡口遇见他。灰袍人坐在破船上，手里握着一根钓竿，竿上没有线。他钓的不是鱼，是河。","你走近，他没有抬头。风把他的灰袍吹得鼓起来，又落下。","「……你来了。」他开口，声音像从很远的地方传来，「河认得你。你身上有河的味道——流过很多地方，也淹过很多东西。」","他放下钓竿，从怀里摸出一块石头，放在船舷上：「拿着。等哪天你明白河为什么往前流，就把它扔回河里。」"],options:[{t:"（接过石头，他划着破船消失在雾里）",go:"faction_free_tavern"}]}};
N["v56s_swordsman_a"]=function(){return{title:"独臂",text:["南方的旧戏台边，独臂·萧坐在台阶上，独臂搭在膝上，望着空荡荡的台面。台上没有人唱戏，可他的眼神像在听。","你在他旁边坐下。他没有看你，也没有赶你走。","过了很久，他忽然开口，声音沙哑：「我这条胳膊，是替一个人断的。那人欠我一句谢，一直没还。」","「我走遍大陆找他还。找了很多年。后来我想通了——他不还，我就替他记着。记着记着，就把整座大陆的路都走熟了。」","他站起来，独臂指了指台面：「戏散了，人就该走了。你也一样。」"],options:[{t:"（起身，向他抱了抱拳）",go:"city_nanfang_tavern"}]}};
/* ---- 半神/挑战者精选 ---- */
N["v56s_rv_o_a"]=function(){return{title:"星弦",text:["北地的孤峰上，奥伦·星弦坐在峰顶，面前摆着一盏熄灭的灯。他看得不是灯，是灯后的虚空。","「你来了。」他没有回头，「洛让你来找我的？他说塔没塌，就是灯灭了一盏——我猜到了。」","「我离塔十二年，在找一条没人走过的元素路。不是更快的路，是更真的路。」他顿了顿，「塔里的路，是寂光铺好的。我想走一条，能看见自己脚印的路。」","「星徽我留给他了。那东西，谁戴着都一样——可塔，需要有人守着。」"],options:[{t:"「找到了吗？」",go:"v56s_rv_o_b"}]}};
N["v56s_rv_o_b"]=function(){return{title:"星弦",text:["奥伦·星弦笑了笑，笑声在孤峰的风里很淡。","「还没。十二年，我试过一百三十二条路，都走不通。可我每试一条，就更清楚寂光为什么把法则刻进魔网第一层——他在替后来人铺路，哪怕没人看见。」","「我要找的，不是比寂光更强的路。是能让我自己看得起自己的路。」他站起来，「你回去告诉洛：塔他没看错人。星徽他戴着，合适。」","「至于那盏灭了的灯——它没灭。它只是换了个地方亮。」"],options:[{t:"（记住他的话，下山时，天边泛起了光）",go:"north_tavern"}]}};
N["v56s_rv_soul_a"]=function(){return{title:"赎夜",text:["深渊裂隙边缘，风从裂口涌上来，带着硫磺和冷。一个黑袍人站在裂口边，背对着你，衣摆被风扯得猎猎响。","「你走得太近了。」他说，声音没有起伏，「圣殿的人，不该走到这儿来。」","「我替圣殿守了三十年夜，最后一夜走进裂隙。奥雷利安没拦住我——他站在塔顶，看着我从他视线里消失。」","「他以为我是去找答案。其实我只是想知道：灵魂的尽头，到底是什么在等我。」"],options:[{t:"「你看到了吗？」",go:"v56s_rv_soul_b"}]}};
N["v56s_rv_soul_b"]=function(){return{title:"赎夜",text:["赎夜没有回头。风从深渊里涌上来，吹得他的声音断断续续。","「看到了。尽头有一面镜子——和圣殿的回音之镜一模一样的镜子。它照出的，是每一个走到尽头的人，最不敢听的那句话。」","「我站到镜前，听见了那句话。然后我退了回来。」他顿了顿，「不是怕。是还没到时候。我欠圣殿三十年的夜，还没还完。」","「你回去告诉澜·梦墟：那面镜子里，她的那句话还在等她。她准备好了再去，别像我一样，被自己吓退。」"],options:[{t:"（看着他消失在裂隙边缘的风里）",go:"event_hub"}]}};

/* ===== /v56inj:engineEnd ===== */
